def generate_image(size):
    """Create a square image whose pixels hold sequential integers."""
    image = []
    for i in range(size):
        row = []
        for j in range(size):
            row.append(float(i * size + j))
        image.append(row)
    return image


def validate_kernel(kernel):
    """Raise ValueError unless the kernel is a proper 3x3 grid."""
    if len(kernel) != 3:
        raise ValueError("kernel must have exactly 3 rows")
    for i in range(3):
        if len(kernel[i]) != 3:
            raise ValueError("kernel row %d must have exactly 3 columns" % i)


def apply_filter(image, kernel):
    """Convolve a 2D image with a 3x3 kernel, treating out-of-bounds as 0."""
    validate_kernel(kernel)
    height = len(image)
    width = len(image[0]) if height else 0
    for i in range(height):
        if len(image[i]) != width:
            raise ValueError("image row %d is ragged" % i)

    result = []
    for i in range(height):
        row = []
        for j in range(width):
            total = 0.0
            for k in range(9):
                di, dj = k // 3 - 1, k % 3 - 1
                y, x = i + di, j + dj
                if 0 <= y < height and 0 <= x < width:
                    total += image[y][x] * kernel[di + 1][dj + 1]
            row.append(total)
        result.append(row)
    return result


def format_grid(grid, width=8):
    """Render a 2D list as aligned rows of text."""
    lines = []
    for i in range(len(grid)):
        cells = []
        for j in range(len(grid[i])):
            cells.append("%*.1f" % (width, grid[i][j]))
        lines.append("".join(cells))
    return "\n".join(lines)


def row_sums(grid):
    """Return the sum of each row, a quick summary of the filter response."""
    sums = []
    for i in range(len(grid)):
        total = 0.0
        for j in range(len(grid[i])):
            total += grid[i][j]
        sums.append(total)
    return sums


def main():
    image = generate_image(5)
    edge_kernel = [[-1.0, -1.0, -1.0],
                   [-1.0, 8.0, -1.0],
                   [-1.0, -1.0, -1.0]]
    filtered = apply_filter(image, edge_kernel)
    print("Input image:")
    print(format_grid(image))
    print("Edge-detected image:")
    print(format_grid(filtered))
    sums = row_sums(filtered)
    for i in range(len(sums)):
        print("row %d sum: %.1f" % (i, sums[i]))
    return filtered


if __name__ == "__main__":
    main()

