def multiply_polynomials(poly1, poly2):
    """Return the coefficient list of poly1 * poly2."""
    if not poly1 or not poly2:
        return []
    product = [0] * (len(poly1) + len(poly2) - 1)
    for i in range(len(poly1)):
        for j in range(len(poly2)):
            product[i + j] += poly1[i] * poly2[j]
    return product


def add_polynomials(poly1, poly2):
    """Return the coefficient list of poly1 + poly2, padding the shorter one."""
    length = max(len(poly1), len(poly2))
    padded1 = list(poly1) + [0] * (length - len(poly1))
    padded2 = list(poly2) + [0] * (length - len(poly2))
    total = []
    for k in range(length):
        total.append(padded1[k] + padded2[k])
    return total


def validate_polynomial(poly, name):
    """Raise TypeError unless poly is a sequence of numbers."""
    if not isinstance(poly, (list, tuple)):
        raise TypeError("%s must be a list of coefficients" % name)
    for n in range(len(poly)):
        if isinstance(poly[n], bool) or not isinstance(poly[n], (int, float)):
            raise TypeError("%s[%d] is not a number" % (name, n))
    return list(poly)


def trim(poly):
    """Drop trailing zero coefficients so the degree is accurate."""
    end = len(poly)
    while end > 0 and poly[end - 1] == 0:
        end -= 1
    return poly[:end]


def format_polynomial(poly):
    """Render a coefficient list as a human readable polynomial string."""
    poly = trim(poly)
    if not poly:
        return "0"
    terms = []
    for i in range(len(poly) - 1, -1, -1):
        coeff = poly[i]
        if coeff == 0:
            continue
        if i == 0:
            terms.append("%g" % coeff)
        elif i == 1:
            terms.append("%gx" % coeff)
        else:
            terms.append("%gx^%d" % (coeff, i))
    text = terms[0]
    for j in range(1, len(terms)):
        term = terms[j]
        if term.startswith("-"):
            text += " - " + term[1:]
        else:
            text += " + " + term
    return text


def main():
    polynomials = [[1, 2], [3, 0, 4], [0, -5, 1, 2]]
    names = ["poly1", "poly2", "poly3"]
    for n in range(len(polynomials)):
        polynomials[n] = validate_polynomial(polynomials[n], names[n])
        print("%s: %s" % (names[n], format_polynomial(polynomials[n])))

    product = multiply_polynomials(polynomials[0], polynomials[1])
    print("poly1 * poly2: %s" % format_polynomial(product))

    result = add_polynomials(product, polynomials[2])
    print("result: %s" % format_polynomial(result))
    return result


if __name__ == "__main__":
    main()

