def lcs_length(seq1, seq2):
    """Build the LCS dynamic programming table for two strings."""
    rows = len(seq1) + 1
    cols = len(seq2) + 1
    dp_table = []
    for i in range(rows):
        dp_table.append([0] * cols)
    for i in range(1, rows):
        for j in range(1, cols):
            if seq1[i - 1] == seq2[j - 1]:
                dp_table[i][j] = dp_table[i - 1][j - 1] + 1
            else:
                dp_table[i][j] = max(dp_table[i - 1][j], dp_table[i][j - 1])
    return dp_table


def reconstruct_lcs(seq1, seq2, dp_table):
    """Walk backwards through the table to recover one longest common subsequence."""
    i = len(seq1)
    j = len(seq2)
    collected = []
    while i > 0 and j > 0:
        if seq1[i - 1] == seq2[j - 1]:
            collected.append(seq1[i - 1])
            i -= 1
            j -= 1
        elif dp_table[i - 1][j] >= dp_table[i][j - 1]:
            i -= 1
        else:
            j -= 1
    result = ''
    for k in range(len(collected) - 1, -1, -1):
        result += collected[k]
    return result


def format_table(seq1, seq2, dp_table):
    """Render the DP table as a list of aligned text lines."""
    labels = [''] + list(seq2)
    lines = ['    ' + ''.join('%3s' % labels[j] for j in range(len(labels)))]
    for i in range(len(dp_table)):
        tag = '' if i == 0 else seq1[i - 1]
        cells = ''.join('%3d' % dp_table[i][j] for j in range(len(dp_table[i])))
        lines.append('%4s' % tag + cells)
    return lines


def main():
    seq1 = "AGGTAB"
    seq2 = "GXTXAYB"
    dp_table = lcs_length(seq1, seq2)
    lcs = reconstruct_lcs(seq1, seq2, dp_table)
    print("seq1 = %s" % seq1)
    print("seq2 = %s" % seq2)
    for n in format_table(seq1, seq2, dp_table):
        print(n)
    print("LCS length: %d" % dp_table[len(seq1)][len(seq2)])
    print("LCS string: %s" % lcs)
    return dp_table, lcs


if __name__ == "__main__":
    main()

