def generate_pascals_triangle(limit):
    """Build Pascal's triangle with `limit` levels as a list of lists."""
    if not isinstance(limit, int):
        raise TypeError("limit must be an integer")
    if limit < 0:
        raise ValueError("limit must be non-negative")
    triangle = []
    for i in range(limit):
        row = [1] * (i + 1)
        previous = triangle[i - 1] if i else []
        for j in range(1, i):
            row[j] = previous[j - 1] + previous[j]
        triangle.append(row)
    return triangle


def extract_diagonals(triangle):
    """Sum the shallow diagonals of the triangle (the Fibonacci numbers)."""
    diagonals = []
    for n in range(len(triangle)):
        total = 0
        for k in range(n // 2 + 1):
            total += triangle[n - k][k]
        diagonals.append(total)
    return diagonals


def format_triangle(triangle):
    """Render the triangle as a list of centred, column-aligned text lines."""
    cell = 1
    for i in range(len(triangle)):
        for j in range(len(triangle[i])):
            cell = max(cell, len(str(triangle[i][j])))
    width = cell + 1
    span = len(triangle) * width
    lines = []
    for i in range(len(triangle)):
        parts = []
        for j in range(len(triangle[i])):
            parts.append(str(triangle[i][j]).rjust(width))
        lines.append("".join(parts).center(span).rstrip())
    return lines


def format_diagonals(diagonals):
    """Render one 'diagonal number -> sum' line per diagonal."""
    label = len(str(len(diagonals) - 1)) if diagonals else 1
    lines = []
    for n in range(len(diagonals)):
        lines.append("diagonal {} -> {}".format(str(n).rjust(label), diagonals[n]))
    return lines


def main():
    triangle = generate_pascals_triangle(10)
    diagonals = extract_diagonals(triangle)
    print("Pascal's triangle (10 levels):")
    for line in format_triangle(triangle):
        print(line)
    print()
    print("Diagonal sums:")
    for line in format_diagonals(diagonals):
        print(line)
    return triangle, diagonals


if __name__ == "__main__":
    main()

