def build_dp_matrix(word1, word2):
    """Build the full Levenshtein DP table for word1 -> word2."""
    rows = len(word1) + 1
    cols = len(word2) + 1
    matrix = [[0] * cols for i in range(rows)]

    for i in range(rows):
        matrix[i][0] = i
    for j in range(cols):
        matrix[0][j] = j

    for i in range(1, rows):
        for j in range(1, cols):
            cost = 0 if word1[i - 1] == word2[j - 1] else 1
            deletion = matrix[i - 1][j] + 1
            insertion = matrix[i][j - 1] + 1
            substitution = matrix[i - 1][j - 1] + cost
            matrix[i][j] = min(deletion, insertion, substitution)

    return matrix


def compute_edit_distance(word1, word2):
    """Return the edit distance between word1 and word2 plus the DP matrix."""
    if not isinstance(word1, str) or not isinstance(word2, str):
        raise TypeError("compute_edit_distance expects two strings")

    matrix = build_dp_matrix(word1, word2)
    distance = matrix[len(word1)][len(word2)]
    return distance, matrix


def print_dp_matrix(matrix):
    """Format a 2D matrix of numbers as one padded string per row."""
    width = 1
    for row in matrix:
        for cell in row:
            n = len(str(cell))
            if n > width:
                width = n

    lines = []
    for i in range(len(matrix)):
        parts = []
        for j in range(len(matrix[i])):
            parts.append(str(matrix[i][j]).rjust(width))
        lines.append(" ".join(parts))
    return lines


def describe_edits(word1, word2, matrix):
    """Walk the matrix backwards and name the edits along an optimal path."""
    steps = []
    i, j = len(word1), len(word2)
    while i > 0 or j > 0:
        if i > 0 and j > 0 and matrix[i][j] == matrix[i - 1][j - 1] and word1[i - 1] == word2[j - 1]:
            steps.append("keep {}".format(word1[i - 1]))
            i, j = i - 1, j - 1
        elif i > 0 and j > 0 and matrix[i][j] == matrix[i - 1][j - 1] + 1:
            steps.append("replace {} with {}".format(word1[i - 1], word2[j - 1]))
            i, j = i - 1, j - 1
        elif i > 0 and matrix[i][j] == matrix[i - 1][j] + 1:
            steps.append("delete {}".format(word1[i - 1]))
            i -= 1
        else:
            steps.append("insert {}".format(word2[j - 1]))
            j -= 1
    steps.reverse()
    return steps


def main():
    word1, word2 = "kitten", "sitting"
    distance, matrix = compute_edit_distance(word1, word2)
    lines = print_dp_matrix(matrix)

    print("{} -> {}: distance {}".format(word1, word2, distance))
    for line in lines:
        print(line)
    for k, step in enumerate(describe_edits(word1, word2, matrix), start=1):
        print("{:>2}. {}".format(k, step))

    return {"distance": distance, "matrix": lines}


if __name__ == "__main__":
    main()

