def count_live_neighbors(grid, row_idx, col_idx):
    """Count the live neighbours of grid[row_idx][col_idx], clipping at the edges."""
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    total = 0
    for i in range(row_idx - 1, row_idx + 2):
        if i < 0 or i >= rows:
            continue
        for j in range(col_idx - 1, col_idx + 2):
            if j < 0 or j >= cols:
                continue
            if i == row_idx and j == col_idx:
                continue
            total += grid[i][j]
    return total


def next_generation(grid):
    """Return a new grid holding the state after one Game of Life step."""
    validate_grid(grid)
    new_grid = []
    for i in range(len(grid)):
        new_row = []
        for j in range(len(grid[i])):
            neighbors = count_live_neighbors(grid, i, j)
            if grid[i][j]:
                new_row.append(1 if neighbors in (2, 3) else 0)
            else:
                new_row.append(1 if neighbors == 3 else 0)
        new_grid.append(new_row)
    return new_grid


def validate_grid(grid):
    """Reject anything that is not a rectangular grid of 0/1 values."""
    if not grid or not grid[0]:
        raise ValueError("grid must contain at least one cell")
    width = len(grid[0])
    for n, row in enumerate(grid):
        if len(row) != width:
            raise ValueError("row %d has length %d, expected %d" % (n, len(row), width))
        for k in range(width):
            if row[k] not in (0, 1):
                raise ValueError("cell (%d, %d) is not 0 or 1" % (n, k))


def make_grid(size, live_cells):
    """Build a size x size grid with the given (row, col) cells set alive."""
    grid = [[0] * size for i in range(size)]
    for r, c in live_cells:
        grid[r][c] = 1
    return grid


def format_grid(grid):
    """Render a grid as text using '#' for live cells and '.' for dead ones."""
    lines = []
    for row in grid:
        lines.append("".join("#" if row[j] else "." for j in range(len(row))))
    return "\n".join(lines)


def main():
    glider = [(0, 1), (1, 2), (2, 0), (2, 1), (2, 2)]
    grid = make_grid(5, glider)
    print("Generation 0:")
    print(format_grid(grid))
    for n in range(1, 4):
        grid = next_generation(grid)
        print("Generation %d:" % n)
        print(format_grid(grid))
    return grid


if __name__ == "__main__":
    main()

