import math


def euclidean_distance(pt1, pt2):
    return math.sqrt((pt1[0] - pt2[0]) ** 2 + (pt1[1] - pt2[1]) ** 2)


def assign_clusters(points, centroids):
    assignments = []
    for i in range(len(points)):
        best_index = 0
        best_distance = euclidean_distance(points[i], centroids[0])
        for j in range(1, len(centroids)):
            d = euclidean_distance(points[i], centroids[j])
            if d < best_distance:
                best_distance = d
                best_index = j
        assignments.append(best_index)
    return assignments


def update_centroids(points, assignments, k_count):
    centroids = []
    for k in range(k_count):
        sum_x = 0.0
        sum_y = 0.0
        count = 0
        for i in range(len(points)):
            if assignments[i] == k:
                sum_x += points[i][0]
                sum_y += points[i][1]
                count += 1
        if count == 0:
            centroids.append(points[k % len(points)])
        else:
            centroids.append((sum_x / count, sum_y / count))
    return centroids


def inertia(points, assignments, centroids):
    total = 0.0
    for i in range(len(points)):
        total += euclidean_distance(points[i], centroids[assignments[i]]) ** 2
    return total


def format_centroids(centroids):
    parts = []
    for k in range(len(centroids)):
        parts.append("C%d=(%.3f, %.3f)" % (k, centroids[k][0], centroids[k][1]))
    return " | ".join(parts)


def main():
    points = [(1.0, 1.0), (1.5, 2.0), (0.5, 1.2),
              (8.0, 8.0), (9.0, 7.5), (8.5, 9.0)]
    centroids = [(0.0, 0.0), (10.0, 10.0)]
    k_count = len(centroids)

    for i in range(3):
        assignments = assign_clusters(points, centroids)
        centroids = update_centroids(points, assignments, k_count)
        print("iteration %d: %s  inertia=%.4f"
              % (i + 1, format_centroids(centroids),
                 inertia(points, assignments, centroids)))

    sizes = [0] * k_count
    for i in range(len(points)):
        sizes[assignments[i]] += 1
    for k in range(k_count):
        print("cluster %d holds %d point(s)" % (k, sizes[k]))

    return centroids


if __name__ == "__main__":
    print("final centroids:", format_centroids(main()))

