    print("rebuilt matrix (%d edges):" % count_edges(rebuilt))
    print(format_matrix(rebuilt))
    for index in range(len(matrix)):
        if matrix[index] != rebuilt[index]:
            print("row %d differs after round trip" % index)
    return adj_list, rebuilt


