def validate_input(arr):
    """Return the input as a list of ints, raising ValueError on bad entries."""
    if not isinstance(arr, (list, tuple)):
        raise TypeError("arr must be a list or tuple of integers")
    values = list(arr)
    for i in range(len(values)):
        if isinstance(values[i], bool) or not isinstance(values[i], int):
            raise ValueError("element at index %d is not an integer: %r"
                             % (i, values[i]))
    return values


def compute_lis_lengths(arr):
    """Return a table whose entry at each position holds the length of the
    longest strictly increasing subsequence finishing at that position."""
    values = validate_input(arr)
    lengths = [1] * len(values)
    for i in range(len(values)):
        for j in range(i):
            if values[j] < values[i] and lengths[j] + 1 > lengths[i]:
                lengths[i] = lengths[j] + 1
    return lengths


def reconstruct_lis(arr, lengths):
    """Walk the lengths table backwards to recover one optimal subsequence."""
    values = validate_input(arr)
    if len(values) != len(lengths):
        raise ValueError("arr and lengths must have the same size")
    if not values:
        return []

    best = 0
    for i in range(1, len(lengths)):
        if lengths[i] > lengths[best]:
            best = i

    result = [values[best]]
    wanted = lengths[best] - 1
    for k in range(best - 1, -1, -1):
        if lengths[k] == wanted and values[k] < result[-1]:
            result.append(values[k])
            wanted -= 1
            if wanted == 0:
                break
    result.reverse()
    return result


def format_table(arr, lengths):
    """Render the DP table as aligned text lines, one row per index."""
    lines = ["idx  value  lis_len"]
    for i in range(len(arr)):
        lines.append("%3d  %5d  %7d" % (i, arr[i], lengths[i]))
    return "\n".join(lines)


def main():
    data = [10, 22, 9, 33, 21, 50, 41, 60]
    lengths = compute_lis_lengths(data)
    subsequence = reconstruct_lis(data, lengths)

    print(format_table(data, lengths))
    print("LIS length: %d" % len(subsequence))
    print("LIS: " + " -> ".join(str(value) for value in subsequence))

    return len(subsequence), subsequence


if __name__ == "__main__":
    main()

