def validate_matrix(matrix):
    """Check that matrix is a list of equally sized rows."""
    if not isinstance(matrix, list):
        raise TypeError("matrix must be a list of lists")
    lengths = set()
    for i in range(len(matrix)):
        row = matrix[i]
        if not isinstance(row, list):
            raise TypeError("row %d is not a list" % i)
        lengths.add(len(row))
    if len(lengths) > 1:
        raise ValueError("all rows must have the same length")


def diagonal_groups(rows, cols):
    """Group cell indices by the value of index + column (anti-diagonals)."""
    groups = []
    for n in range(rows + cols - 1):
        cells = []
        for i in range(max(0, n - cols + 1), min(rows, n + 1)):
            cells.append((i, n - i))
        groups.append(cells)
    return groups


def zigzag_indices(rows, cols):
    """Return the (index, column) index pairs in diagonal zigzag order."""
    if rows == 0 or cols == 0:
        return []
    path = []
    groups = diagonal_groups(rows, cols)
    for n in range(len(groups)):
        cells = groups[n] if n % 2 else list(reversed(groups[n]))
        for i, j in cells:
            path.append((i, j))
    return path


def zigzag_traverse(matrix):
    """Return the matrix elements in diagonal zigzag order as a 1D list."""
    validate_matrix(matrix)
    rows = len(matrix)
    cols = len(matrix[0]) if rows else 0
    flat = []
    for i, j in zigzag_indices(rows, cols):
        flat.append(matrix[i][j])
    return flat


def format_matrix(matrix):
    """Render the matrix as aligned text lines."""
    width = 1
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            width = max(width, len(str(matrix[i][j])))
    lines = []
    for i in range(len(matrix)):
        cells = []
        for j in range(len(matrix[i])):
            cells.append(str(matrix[i][j]).rjust(width))
        lines.append(" ".join(cells))
    return lines


def format_path(path):
    """Render a list of index pairs as an arrow-separated string."""
    parts = []
    for i, j in path:
        parts.append("(%d,%d)" % (i, j))
    return " -> ".join(parts)


def main():
    matrix = []
    for i in range(3):
        row = []
        for j in range(3):
            row.append(i * 3 + j + 1)
        matrix.append(row)

    for line in format_matrix(matrix):
        print(line)
    print("path:", format_path(zigzag_indices(len(matrix), len(matrix[0]))))

    result = zigzag_traverse(matrix)
    print("zigzag:", result)
    return result


if __name__ == "__main__":
    main()

