def _validate(dimensions):
    """Reject inputs that cannot describe a chain of matrices."""
    if not isinstance(dimensions, (list, tuple)):
        raise TypeError("dimensions must be a list of integers")
    for n in dimensions:
        if isinstance(n, bool) or not isinstance(n, int):
            raise TypeError("every dimension must be an integer, got %r" % (n,))
        if n <= 0:
            raise ValueError("every dimension must be positive, got %d" % n)


def build_cost_tables(dimensions):
    """Return (cost, split) tables for the matrix chain described by dimensions."""
    _validate(dimensions)
    size = len(dimensions)
    cost = [[0] * size for i in range(size)]
    split = [[0] * size for i in range(size)]
    for j in range(2, size):
        for i in range(j - 1, 0, -1):
            best = None
            for k in range(i, j):
                trial = (cost[i][k] + cost[k + 1][j]
                         + dimensions[i - 1] * dimensions[k] * dimensions[j])
                if best is None or trial < best:
                    best = trial
                    split[i][j] = k
            cost[i][j] = best
    return cost, split


def min_multiplication_cost(dimensions):
    """Minimum number of scalar multiplications needed for the whole chain."""
    _validate(dimensions)
    if len(dimensions) < 3:
        return 0
    cost = build_cost_tables(dimensions)[0]
    return cost[1][len(dimensions) - 1]


def parenthesization(split, start, end):
    """Describe the optimal grouping of matrices start..end using the split table."""
    if start == end:
        return "A%d" % start
    mid = split[start][end]
    return "(%s x %s)" % (parenthesization(split, start, mid),
                          parenthesization(split, mid + 1, end))


def print_dp_table(table):
    """Format and print the final 2D cost array (rows/columns 1..size-1)."""
    size = len(table)
    width = 1
    for i in range(1, size):
        for j in range(1, size):
            width = max(width, len(str(table[i][j])))
    header = " " * (width + 2)
    for j in range(1, size):
        header += str(j).rjust(width) + " "
    print(header.rstrip())
    for i in range(1, size):
        row = str(i).rjust(width + 1) + " "
        for j in range(1, size):
            row += (str(table[i][j]) if j >= i else ".").rjust(width) + " "
        print(row.rstrip())


def main():
    chains = [[10, 30, 5, 60], [40, 20, 30, 10, 30], [5, 10, 3], [7, 2]]
    for i in range(len(chains)):
        dimensions = chains[i]
        print("Chain %d: %s" % (i + 1, dimensions))
        for j in range(1, len(dimensions)):
            print("  A%d has size %dx%d"
                  % (j, dimensions[j - 1], dimensions[j]))
        print("  minimum cost: %d" % min_multiplication_cost(dimensions))
        if len(dimensions) >= 3:
            cost, split = build_cost_tables(dimensions)
            print("  order: %s"
                  % parenthesization(split, 1, len(dimensions) - 1))
            print_dp_table(cost)
        print()


if __name__ == "__main__":
    main()

