def validate_sequences(seq1, seq2):
    """Check that both inputs are strings over the DNA alphabet."""
    alphabet = "ACGTN"
    for n, seq in enumerate((seq1, seq2), start=1):
        if not isinstance(seq, str):
            raise TypeError("sequence %d must be a string" % n)
        if not seq:
            raise ValueError("sequence %d must not be empty" % n)
        for i in range(len(seq)):
            if seq[i].upper() not in alphabet:
                raise ValueError("sequence %d has bad symbol %r at position %d"
                                 % (n, seq[i], i))
    return seq1.upper(), seq2.upper()


def build_matrix(seq1, seq2, match=2, mismatch=-1, gap=-1):
    """Fill the Smith-Waterman matrix; return it with the best score and cell."""
    rows, cols = len(seq1), len(seq2)
    matrix = [[0] * (cols + 1) for _ in range(rows + 1)]
    best, best_cell = 0, (0, 0)
    for i in range(1, rows + 1):
        for j in range(1, cols + 1):
            step = match if seq1[i - 1] == seq2[j - 1] else mismatch
            score = max(0,
                        matrix[i - 1][j - 1] + step,
                        matrix[i - 1][j] + gap,
                        matrix[i][j - 1] + gap)
            matrix[i][j] = score
            if score > best:
                best, best_cell = score, (i, j)
    return matrix, best, best_cell


def local_alignment_score(seq1, seq2, match=2, mismatch=-1, gap=-1):
    """Optimal local (Smith-Waterman) alignment score of two sequences."""
    a, b = validate_sequences(seq1, seq2)
    return build_matrix(a, b, match, mismatch, gap)[1]


def traceback(matrix, seq1, seq2, cell, match=2, mismatch=-1, gap=-1):
    """Recover the aligned substrings ending at the best-scoring cell."""
    i, j = cell
    top, bottom = [], []
    while i > 0 and j > 0 and matrix[i][j] > 0:
        step = match if seq1[i - 1] == seq2[j - 1] else mismatch
        if matrix[i][j] == matrix[i - 1][j - 1] + step:
            top.append(seq1[i - 1])
            bottom.append(seq2[j - 1])
            i, j = i - 1, j - 1
        elif matrix[i][j] == matrix[i - 1][j] + gap:
            top.append(seq1[i - 1])
            bottom.append("-")
            i -= 1
        else:
            top.append("-")
            bottom.append(seq2[j - 1])
            j -= 1
    return "".join(reversed(top)), "".join(reversed(bottom))


def alignment_report(seq1, seq2, match=2, mismatch=-1, gap=-1):
    """Three text lines showing the best local alignment of the two sequences."""
    a, b = validate_sequences(seq1, seq2)
    matrix, best, cell = build_matrix(a, b, match, mismatch, gap)
    top, bottom = traceback(matrix, a, b, cell, match, mismatch, gap)
    ruler = []
    for k in range(len(top)):
        ruler.append("|" if top[k] == bottom[k] else " ")
    return best, [top, "".join(ruler), bottom]


def main():
    pairs = [("TGTTACGG", "GGTTGACTA"),
             ("ACACACTA", "AGCACACA"),
             ("GATTACA", "GCATGCU")]
    for n, (left, right) in enumerate(pairs, start=1):
        score, lines = alignment_report(left, right)
        print("pair %d: %s vs %s -> score %d" % (n, left, right, score))
        for j in range(len(lines)):
            print("    " + lines[j])


if __name__ == "__main__":
    main()

