def validate_model(observations, states, start_prob, trans_prob, emit_prob):
    """Check that the model is well formed for the given observation sequence."""
    if not observations:
        raise ValueError("observations must not be empty")
    if not states:
        raise ValueError("states must not be empty")
    total = 0.0
    for i in range(len(states)):
        total += start_prob.get(states[i], 0.0)
    if abs(total - 1.0) > 1e-6:
        raise ValueError("start probabilities must sum to 1, got %.6f" % total)
    for i in range(len(states)):
        row = trans_prob.get(states[i])
        if row is None:
            raise ValueError("no transition row for state %r" % states[i])
        total = 0.0
        for j in range(len(states)):
            total += row.get(states[j], 0.0)
        if abs(total - 1.0) > 1e-6:
            raise ValueError("transitions from %r sum to %.6f" % (states[i], total))
        emits = emit_prob.get(states[i])
        if emits is None:
            raise ValueError("no emission row for state %r" % states[i])
        for k in range(len(observations)):
            if observations[k] not in emits:
                raise ValueError("state %r cannot emit %r" % (states[i], observations[k]))


def most_likely_sequence(observations, states, start_prob, trans_prob, emit_prob):
    """Viterbi decoding: return (probability, list of hidden states)."""
    validate_model(observations, states, start_prob, trans_prob, emit_prob)
    steps = len(observations)
    trellis = [{}]
    paths = {}
    for i in range(len(states)):
        cur = states[i]
        trellis[0][cur] = start_prob[cur] * emit_prob[cur][observations[0]]
        paths[cur] = [cur]
    for k in range(1, steps):
        trellis.append({})
        new_paths = {}
        for i in range(len(states)):
            cur = states[i]
            best_prob = -1.0
            best_prev = states[0]
            for j in range(len(states)):
                prev = states[j]
                prob = (trellis[k - 1][prev] * trans_prob[prev][cur]
                        * emit_prob[cur][observations[k]])
                if prob > best_prob:
                    best_prob = prob
                    best_prev = prev
            trellis[k][cur] = best_prob
            new_paths[cur] = paths[best_prev] + [cur]
        paths = new_paths
    best_prob = -1.0
    best_state = states[0]
    for i in range(len(states)):
        if trellis[steps - 1][states[i]] > best_prob:
            best_prob = trellis[steps - 1][states[i]]
            best_state = states[i]
    return best_prob, paths[best_state]


