def validate_grammar(grammar):
    """Check that every production is a terminal string or a pair of known non-terminals."""
    problems = []
    for lhs, productions in grammar.items():
        for i in range(len(productions)):
            rule = productions[i]
            if isinstance(rule, str):
                continue
            if not isinstance(rule, tuple) or len(rule) != 2:
                problems.append("%s -> rule %d is neither a terminal nor a pair" % (lhs, i))
                continue
            for j in range(2):
                if rule[j] not in grammar:
                    problems.append("%s -> %s uses unknown symbol %s" % (lhs, rule, rule[j]))
    return problems


def cyk_parse(words, grammar):
    """Return True if `words` is generated by the CNF `grammar` starting from 'S'."""
    n = len(words)
    if n == 0:
        return False
    table = build_table(words, grammar)
    return 'S' in table[n - 1][0]


def build_table(words, grammar):
    """Return the CYK grid: table[length - 1][start] holds the derivable non-terminals."""
    n = len(words)
    table = []
    for i in range(n):
        table.append([set() for j in range(n)])
    for i in range(n):
        for lhs, productions in grammar.items():
            for j in range(len(productions)):
                if productions[j] == words[i]:
                    table[0][i].add(lhs)
    for i in range(2, n + 1):
        for j in range(n - i + 1):
            cell = table[i - 1][j]
            for k in range(1, i):
                left = table[k - 1][j]
                right = table[i - k - 1][j + k]
                for lhs, productions in grammar.items():
                    for m in range(len(productions)):
                        rule = productions[m]
                        if isinstance(rule, tuple) and rule[0] in left and rule[1] in right:
                            cell.add(lhs)
    return table


def format_table(words, table):
    """Render the CYK grid as text, longest spans last."""
    lines = []
    n = len(words)
    for i in range(n):
        row = []
        for j in range(n - i):
            symbols = sorted(table[i][j])
            span = " ".join(words[j:j + i + 1])
            row.append("[%s: %s]" % (span, ",".join(symbols) if symbols else "-"))
        lines.append(" ".join(row))
    return "\n".join(lines)


def main():
    grammar = {
        'S': [('NP', 'VP')],
        'NP': [('DET', 'N'), 'astronomers', 'stars'],
        'VP': [('V', 'NP')],
        'DET': ['the'],
        'N': ['stars', 'telescopes', 'fish'],
        'V': ['saw', 'swim'],
    }
    problems = validate_grammar(grammar)
    for i in range(len(problems)):
        print("grammar warning %d: %s" % (i + 1, problems[i]))
    sentences = [
        ["astronomers", "saw", "stars"],
        ["astronomers", "saw", "the", "telescopes"],
        ["saw", "stars", "astronomers"],
        ["fish", "swim"],
    ]
    for i in range(len(sentences)):
        words = sentences[i]
        accepted = cyk_parse(words, grammar)
        print("%-40s %s" % (" ".join(words), "accepted" if accepted else "rejected"))
        print(format_table(words, build_table(words, grammar)))


if __name__ == '__main__':
    main()

