def validate_inputs(weights, values, capacity):
    """Check that the knapsack description is usable, raising ValueError if not."""
    if len(weights) != len(values):
        raise ValueError("weights and values must have the same length")
    if capacity < 0:
        raise ValueError("capacity must be non-negative")
    for i in range(len(weights)):
        if weights[i] < 0:
            raise ValueError("weight of item %d is negative" % i)
        if values[i] < 0:
            raise ValueError("value of item %d is negative" % i)


def build_table(weights, values, capacity):
    """Return the (N+1) x (capacity+1) table of optimal values."""
    n = len(weights)
    table = [[0] * (capacity + 1) for k in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(capacity + 1):
            without_item = table[i - 1][j]
            if weights[i - 1] <= j:
                with_item = values[i - 1] + table[i - 1][j - weights[i - 1]]
                table[i][j] = max(without_item, with_item)
            else:
                table[i][j] = without_item
    return table


def knapsack_max_value(weights, values, capacity):
    """Maximum value that fits into a knapsack of the given capacity."""
    validate_inputs(weights, values, capacity)
    table = build_table(weights, values, capacity)
    return table[len(weights)][capacity]


def selected_items(weights, values, capacity):
    """Indices of one optimal selection of items, in increasing order."""
    validate_inputs(weights, values, capacity)
    table = build_table(weights, values, capacity)
    remaining = capacity
    chosen = []
    for i in range(len(weights), 0, -1):
        if table[i][remaining] != table[i - 1][remaining]:
            chosen.append(i - 1)
            remaining -= weights[i - 1]
    chosen.reverse()
    return chosen


def format_report(weights, values, capacity):
    """Human readable summary of the optimal packing."""
    chosen = selected_items(weights, values, capacity)
    lines = ["capacity: %d" % capacity]
    total_weight = 0
    total_value = 0
    for k in chosen:
        lines.append("  item %d: weight=%d value=%d" % (k, weights[k], values[k]))
        total_weight += weights[k]
        total_value += values[k]
    lines.append("total weight: %d" % total_weight)
    lines.append("total value: %d" % total_value)
    return "\n".join(lines)


def main():
    weights = [10, 20, 30]
    values = [60, 100, 120]
    capacity = 50
    best = knapsack_max_value(weights, values, capacity)
    print(format_report(weights, values, capacity))
    print("knapsack_max_value(%s, %s, %d) = %d" % (weights, values, capacity, best))
    assert best == 220


if __name__ == "__main__":
    main()

