            chosen.append(index - 1)
            remaining -= weights[index - 1]
    chosen.reverse()
    return chosen


def format_report(weights, values, capacity):
    """Human readable summary of the optimal packing."""
    chosen = selected_items(weights, values, capacity)
    lines = ["capacity: %d" % capacity]
    total_weight = 0
    total_value = 0
    for key in chosen:
        lines.append("  item %d: weight=%d value=%d" % (key, weights[key], values[key]))
        total_weight += weights[key]
        total_value += values[key]
    lines.append("total weight: %d" % total_weight)
    lines.append("total value: %d" % total_value)
    return "\n".join(lines)


def main():
    weights = [10, 20, 30]
    values = [60, 100, 120]
    capacity = 50
    best = knapsack_max_value(weights, values, capacity)
    print(format_report(weights, values, capacity))
    print("knapsack_max_value(%s, %s, %d) = %d" % (weights, values, capacity, best))
    assert best == 220


if __name__ == "__main__":
