    if not dataset:
        raise ValueError("dataset must contain at least one variable")
    n = len(dataset[0])
    if n < 2:
        raise ValueError("each variable needs at least two observations")
    for i in range(len(dataset)):
        if len(dataset[i]) != n:
            raise ValueError("variable %d has %d observations, expected %d"
                             % (i, len(dataset[i]), n))
        for j in range(n):
            if not isinstance(dataset[i][j], (int, float)):
                raise TypeError("observation %d of variable %d is not numeric" % (j, i))
    return n


def mean(values):
    total = 0.0
    for i in range(len(values)):
        total += values[i]
    return total / len(values)


def pearson_r(x, y):
    """Pearson correlation coefficient of two equal-length sequences."""
    if len(x) != len(y):
        raise ValueError("sequences must have equal length")
    mx = mean(x)
    my = mean(y)
    cov = 0.0
    varx = 0.0
    vary = 0.0
    for i in range(len(x)):
        dx = x[i] - mx
        dy = y[i] - my
        cov += dx * dy
        varx += dx * dx
        vary += dy * dy
    denom = sqrt(varx) * sqrt(vary)
    if denom == 0.0:
        raise ValueError("a constant variable has no correlation")
    return cov / denom


def correlation_matrix(dataset):
    """Pairwise Pearson correlation matrix of the variables in dataset."""
    validate(dataset)
    m = len(dataset)
    matrix = [[0.0] * m for i in range(m)]
    for i in range(m):
        matrix[i][i] = 1.0
        for j in range(i + 1, m):
            r = round(pearson_r(dataset[i], dataset[j]), 4)
            matrix[i][j] = r
            matrix[j][i] = r
    return matrix


def format_matrix(matrix, labels):
    width = max(len(label) for label in labels)
    lines = [" " * width + "".join("%10s" % label for label in labels)]
    for i in range(len(matrix)):
        row = "%-*s" % (width, labels[i])
        for j in range(len(matrix[i])):
            row += "%10.4f" % matrix[i][j]
        lines.append(row)
    return "\n".join(lines)


