def median(values):
    ordered = sorted(values)
    n = len(ordered)
    if n == 0:
        raise ValueError("median of an empty sequence is undefined")
    middle = n // 2
    if n % 2 == 1:
        return float(ordered[middle])
    return (ordered[middle - 1] + ordered[middle]) / 2.0


def validate_table(table):
    if not table:
        raise ValueError("table must contain at least one row")
    width = len(table[0])
    if width == 0:
        raise ValueError("table rows must contain at least one value")
    for i in range(len(table)):
        if len(table[i]) != width:
            raise ValueError("row %d has %d values, expected %d" % (i, len(table[i]), width))
    return len(table), width


def median_polish(table, iterations):
    rows, cols = validate_table(table)
    residuals = []
    for i in range(rows):
        residuals.append([float(table[i][j]) for j in range(cols)])
    row_effects = [0.0] * rows
    col_effects = [0.0] * cols
    for k in range(iterations):
        for i in range(rows):
            row_median = median(residuals[i])
            row_effects[i] += row_median
            for j in range(cols):
                residuals[i][j] -= row_median
        for j in range(cols):
            col_median = median([residuals[i][j] for i in range(rows)])
            col_effects[j] += col_median
            for i in range(rows):
                residuals[i][j] -= col_median
    return {"table": residuals, "row_effects": row_effects, "col_effects": col_effects}


def format_report(result):
    residuals = result["table"]
    row_effects = result["row_effects"]
    col_effects = result["col_effects"]
    lines = ["residuals and effects:"]
    for i in range(len(residuals)):
        cells = " ".join("%7.2f" % residuals[i][j] for j in range(len(residuals[i])))
        lines.append("%s | %7.2f" % (cells, row_effects[i]))
    lines.append("-" * (8 * len(col_effects) + 10))
    lines.append(" ".join("%7.2f" % col_effects[j] for j in range(len(col_effects))))
    return "\n".join(lines)


def main():
    table = [[10.0, 12.0, 15.0],
             [20.0, 23.0, 25.0],
             [30.0, 31.0, 36.0]]
    result = median_polish(table, 2)
    print(format_report(result))
    spread = []
    for i in range(len(result["table"])):
        for j in range(len(result["table"][i])):
            spread.append(abs(result["table"][i][j]))
    print("max absolute residual: %.2f" % max(spread))


if __name__ == "__main__":
    main()

