def build_bad_char_table(pattern, alphabet):
    """Map every alphabet character to its Boyer-Moore bad-character shift."""
    length = len(pattern)
    shifts = {}
    for i in alphabet:
        shifts[i] = length
    for j in range(length - 1):
        shifts[pattern[j]] = length - 1 - j
    return shifts


def validate_sequence(sequence, alphabet):
    """Raise ValueError if the sequence contains a character outside the alphabet."""
    for i, base in enumerate(sequence):
        if base not in alphabet:
            raise ValueError("position %d: %r is not in alphabet %r" % (i, base, alphabet))
    return sequence


def base_counts(sequence, alphabet):
    """Count how often each alphabet character occurs in the sequence."""
    counts = {}
    for k in alphabet:
        counts[k] = 0
    for n in sequence:
        counts[n] += 1
    return counts


def boyer_moore_search(text, pattern, alphabet):
    """Return every start index where pattern occurs in text."""
    m = len(pattern)
    if m == 0 or m > len(text):
        return []
    shifts = build_bad_char_table(pattern, alphabet)
    matches = []
    i = 0
    while i <= len(text) - m:
        mismatch = -1
        for j in range(m - 1, -1, -1):
            if pattern[j] != text[i + j]:
                mismatch = j
                break
        if mismatch < 0:
            matches.append(i)
            i += 1
        else:
            i += max(1, shifts[text[i + mismatch]])
    return matches


def format_table(shifts, alphabet):
    """Render a shift table as 'A=4 C=1 ...' in alphabet order."""
    parts = []
    for k in alphabet:
        parts.append("%s=%d" % (k, shifts[k]))
    return " ".join(parts)


def main():
    alphabet = "ACGT"
    sequence = validate_sequence("GTTCGCAT", alphabet)
    print("sequence: %s (length %d)" % (sequence, len(sequence)))

    counts = base_counts(sequence, alphabet)
    for n in alphabet:
        print("  %s occurs %d time(s)" % (n, counts[n]))

    patterns = ["TCGC", "CG", "AT", "GG"]
    for i, pattern in enumerate(patterns, start=1):
        validate_sequence(pattern, alphabet)
        table = build_bad_char_table(pattern, alphabet)
        hits = boyer_moore_search(sequence, pattern, alphabet)
        print("%d. pattern %-4s table: %s" % (i, pattern, format_table(table, alphabet)))
        if hits:
            for j in hits:
                print("     match at index %d: %s" % (j, sequence[j:j + len(pattern)]))
        else:
            print("     no match")


if __name__ == "__main__":
    main()

