def tokenize(text):
    """Split raw text into a list of lower-case words, dropping punctuation."""
    raw = text.split()
    words = []
    for i in range(len(raw)):
        cleaned = raw[i].strip(".,;:!?\"'()").lower()
        if cleaned:
            words.append(cleaned)
    return words


def train_markov_chain(corpus, order):
    """Map every order-length window of `corpus` to its next-word frequencies."""
    if order < 1:
        raise ValueError("order must be at least 1")
    chain = {}
    for i in range(len(corpus) - order):
        state = tuple(corpus[i:i + order])
        nxt = corpus[i + order]
        followers = chain.setdefault(state, {})
        followers[nxt] = followers.get(nxt, 0) + 1
    return chain


def best_next(counts):
    """Return the most frequent follower, breaking ties alphabetically."""
    candidates = sorted(counts)
    best = candidates[0]
    for j in range(1, len(candidates)):
        if counts[candidates[j]] > counts[best]:
            best = candidates[j]
    return best


def generate_text(chain, start_tuple, length):
    """Greedily extend `start_tuple` by `length` words using the trained chain."""
    current = tuple(start_tuple)
    output = list(current)
    for n in range(length):
        if current not in chain:
            break
        word = best_next(chain[current])
        output.append(word)
        current = current[1:] + (word,)
    return output


def format_chain(chain):
    """Render the chain as sorted, human-readable lines."""
    states = sorted(chain)
    lines = []
    for i in range(len(states)):
        followers = chain[states[i]]
        names = sorted(followers, key=lambda w: (-followers[w], w))
        parts = []
        for j in range(len(names)):
            parts.append("%s=%d" % (names[j], followers[names[j]]))
        lines.append("%s -> %s" % (" ".join(states[i]), ", ".join(parts)))
    return lines


def main():
    corpus = tokenize("The dog barked and the dog slept. The dog barked again!")
    order = 2
    chain = train_markov_chain(corpus, order)
    for line in format_chain(chain):
        print(line)
    starts = [("the", "dog"), ("dog", "barked")]
    for i in range(len(starts)):
        produced = generate_text(chain, starts[i], 5)
        print("from %s: %s" % (" ".join(starts[i]), " ".join(produced)))


if __name__ == "__main__":
    main()

