def jaro_distance(s1, s2):
    """Jaro similarity between two strings, in the range 0.0 .. 1.0."""
    if not s1 or not s2:
        return 1.0 if s1 == s2 else 0.0
    n1, n2 = len(s1), len(s2)
    window = max(0, max(n1, n2) // 2 - 1)
    hit1 = [False] * n1
    hit2 = [False] * n2
    matches = 0
    for i in range(n1):
        low = max(0, i - window)
        high = min(i + window, n2 - 1)
        for j in range(low, high + 1):
            if not hit2[j] and s1[i] == s2[j]:
                hit1[i] = True
                hit2[j] = True
                matches += 1
                break
    if matches == 0:
        return 0.0
    seq1 = []
    for i in range(n1):
        if hit1[i]:
            seq1.append(s1[i])
    seq2 = []
    for j in range(n2):
        if hit2[j]:
            seq2.append(s2[j])
    transpositions = 0
    for k in range(matches):
        if seq1[k] != seq2[k]:
            transpositions += 1
    transpositions //= 2
    return (matches / n1 + matches / n2 + (matches - transpositions) / matches) / 3.0


def common_prefix_length(s1, s2, limit=4):
    """Length of the shared leading run of characters, capped at `limit`."""
    bound = min(limit, len(s1), len(s2))
    shared = 0
    for i in range(bound):
        if s1[i] != s2[i]:
            break
        shared += 1
    return shared


def jaro_winkler(s1, s2, scaling=0.1):
    """Jaro score boosted by the length of the common prefix."""
    base = jaro_distance(s1, s2)
    if base < 0.7:
        return base
    prefix = common_prefix_length(s1, s2)
    return base + prefix * scaling * (1.0 - base)


def best_match(target, candidates):
    """Return the (candidate, score) pair with the highest Jaro-Winkler score."""
    best, best_score = None, -1.0
    for n in range(len(candidates)):
        score = jaro_winkler(target, candidates[n])
        if score > best_score:
            best, best_score = candidates[n], score
    return best, best_score


def report_lines(pairs):
    """Build a printable table of Jaro and Jaro-Winkler scores for string pairs."""
    lines = ["%-12s %-12s %8s %8s" % ("first", "second", "jaro", "winkler")]
    for i in range(len(pairs)):
        a, b = pairs[i]
        lines.append("%-12s %-12s %8.3f %8.3f"
                     % (a, b, jaro_distance(a, b), jaro_winkler(a, b)))
    return lines


def main():
    pairs = [("MARTHA", "MARHTA"), ("DIXON", "DICKSONX"),
             ("JELLYFISH", "SMELLYFISH"), ("CRATE", "TRACE"),
