def jaro_distance(s1, s2):
    """Jaro similarity between two strings, in the range 0.0 .. 1.0."""
    if not s1 or not s2:
        return 1.0 if s1 == s2 else 0.0
    n1, n2 = len(s1), len(s2)
    window = max(0, max(n1, n2) // 2 - 1)
    hit1 = [False] * n1
    hit2 = [False] * n2
    matches = 0
    for index in range(n1):
        low = max(0, index - window)
        high = min(index + window, n2 - 1)
        for column in range(low, high + 1):
            if not hit2[column] and s1[index] == s2[column]:
                hit1[index] = True
                hit2[column] = True
                matches += 1
                break
    if matches == 0:
        return 0.0
    seq1 = []
    for index in range(n1):
        if hit1[index]:
            seq1.append(s1[index])
    seq2 = []
    for column in range(n2):
        if hit2[column]:
            seq2.append(s2[column])
    transpositions = 0
    for key in range(matches):
        if seq1[key] != seq2[key]:
            transpositions += 1
    transpositions //= 2
    return (matches / n1 + matches / n2 + (matches - transpositions) / matches) / 3.0


def common_prefix_length(s1, s2, limit=4):
    """Length of the shared leading run of characters, capped at `limit`."""
    bound = min(limit, len(s1), len(s2))
    shared = 0
    for index in range(bound):
        if s1[index] != s2[index]:
            break
        shared += 1
    return shared


def jaro_winkler(s1, s2, scaling=0.1):
    """Jaro score boosted by the length of the common prefix."""
    base = jaro_distance(s1, s2)
    if base < 0.7:
        return base
    prefix = common_prefix_length(s1, s2)
    return base + prefix * scaling * (1.0 - base)


def best_match(target, candidates):
    """Return the (candidate, score) pair with the highest Jaro-Winkler score."""
    best, best_score = None, -1.0
    for number in range(len(candidates)):
        score = jaro_winkler(target, candidates[number])
        if score > best_score:
            best, best_score = candidates[number], score
    return best, best_score


def report_lines(pairs):
    """Build a printable table of Jaro and Jaro-Winkler scores for string pairs."""
    lines = ["%-12s %-12s %8s %8s" % ("first", "second", "jaro", "winkler")]
    for index in range(len(pairs)):
        a, b = pairs[index]
        lines.append("%-12s %-12s %8.3f %8.3f"
                     % (a, b, jaro_distance(a, b), jaro_winkler(a, b)))
    return lines


def main():
    pairs = [("MARTHA", "MARHTA"), ("DIXON", "DICKSONX"),
             ("JELLYFISH", "SMELLYFISH"), ("CRATE", "TRACE"),
             ("abc", "abc"), ("", "nonempty")]
    for line in report_lines(pairs):
        print(line)
    dictionary = ["receive", "deceive", "recieve", "relieve", "retrieve"]
    for word in ("recieve", "releive"):
        guess, score = best_match(word, dictionary)
        print("%s -> %s (%.3f)" % (word, guess, score))


if __name__ == "__main__":
    main()

