import math


def dot_product(vec1, vec2, length):
    total = 0.0
    for i in range(length):
        total += vec1[i] * vec2[i]
    return total


def is_symmetric(matrix, tolerance=1e-9):
    n = len(matrix)
    for i in range(n):
        if len(matrix[i]) != n:
            return False
        for j in range(i):
            if abs(matrix[i][j] - matrix[j][i]) > tolerance:
                return False
    return True


def cholesky_decomposition(matrix):
    n = len(matrix)
    lower = [[0.0] * n for i in range(n)]
    for i in range(n):
        for j in range(i + 1):
            partial = dot_product(lower[i], lower[j], j)
            if i == j:
                lower[i][j] = math.sqrt(matrix[i][i] - partial)
            else:
                lower[i][j] = (matrix[i][j] - partial) / lower[j][j]
    return lower


def multiply_by_transpose(lower):
    n = len(lower)
    product = [[0.0] * n for i in range(n)]
    for i in range(n):
        for j in range(n):
            length = min(i, j) + 1
            product[i][j] = dot_product(lower[i], lower[j], length)
    return product


def max_deviation(first, second):
    worst = 0.0
    for i in range(len(first)):
        for j in range(len(first)):
            gap = abs(first[i][j] - second[i][j])
            if gap > worst:
                worst = gap
    return worst


def format_matrix(matrix, width=9, digits=4):
    lines = []
    for i in range(len(matrix)):
        cells = []
        for j in range(len(matrix[i])):
            cells.append(format(matrix[i][j], "%d.%df" % (width, digits)))
        lines.append(" ".join(cells))
    return "\n".join(lines)


def main():
    samples = [
        [[4, 12, -16], [12, 37, -43], [-16, -43, 98]],
        [[25, 15, -5], [15, 18, 0], [-5, 0, 11]],
        [[18, 22, 54, 42], [22, 70, 86, 62], [54, 86, 174, 134], [42, 62, 134, 106]],
    ]
    for k in range(len(samples)):
        matrix = samples[k]
        print("Matrix %d (%dx%d):" % (k + 1, len(matrix), len(matrix)))
        if not is_symmetric(matrix):
            print("  input is not symmetric; skipped")
            continue
        lower = cholesky_decomposition(matrix)
        print(format_matrix(lower))
        print("  reconstruction error: %.2e" % max_deviation(matrix, multiply_by_transpose(lower)))


if __name__ == "__main__":
    main()

