def validate(arr):
    """Reject anything that is not a sequence of integers."""
    if not isinstance(arr, (list, tuple)):
        raise TypeError("expected a list of integers")
    for i, value in enumerate(arr):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("element %d is not an integer: %r" % (i, value))


def increasing_lengths(arr):
    """Length of the longest increasing subsequence ending at each position."""
    n = len(arr)
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1
    return inc


def decreasing_lengths(arr):
    """Length of the longest decreasing subsequence starting at each position."""
    n = len(arr)
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if arr[j] < arr[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1
    return dec


def longest_bitonic_subsequence(arr):
    """Return the length of the longest bitonic (up then down) subsequence."""
    validate(arr)
    inc = increasing_lengths(arr)
    dec = decreasing_lengths(arr)
    best = 0
    for i in range(len(arr)):
        if inc[i] + dec[i] - 1 > best:
            best = inc[i] + dec[i] - 1
    return best


def bitonic_subsequence(arr):
    """Rebuild one longest bitonic subsequence from the DP tables."""
    validate(arr)
    if not arr:
        return []
    inc = increasing_lengths(arr)
    dec = decreasing_lengths(arr)
    n = len(arr)
    peak = 0
    for i in range(n):
        if inc[i] + dec[i] > inc[peak] + dec[peak]:
            peak = i
    left = [arr[peak]]
    cur = peak
    for j in range(peak - 1, -1, -1):
        if arr[j] < arr[cur] and inc[j] == inc[cur] - 1:
            left.append(arr[j])
            cur = j
    left.reverse()
    right = []
    cur = peak
    for j in range(peak + 1, n):
        if arr[j] < arr[cur] and dec[j] == dec[cur] - 1:
            right.append(arr[j])
            cur = j
    return left + right


def format_report(datasets):
    lines = []
    for i, data in enumerate(datasets, start=1):
        length = longest_bitonic_subsequence(data)
        chain = ", ".join(map(str, bitonic_subsequence(data)))
        lines.append("case %d: %s -> %d  [%s]" % (i, data, length, chain))
    return "\n".join(lines)


def main():
    samples = [
        [1, 11, 2, 10, 4, 5, 2, 1],
        [12, 11, 40, 5, 3, 1],
        [80, 60, 30, 40, 20, 10],
        [1, 2, 3, 4, 5],
        [7],
        [],
    ]
    print(format_report(samples))


if __name__ == "__main__":
    main()

