    """Length of the longest increasing subsequence ending at each position."""
    n = len(arr)
    inc = [1] * n
    for index in range(n):
        for column in range(index):
            if arr[column] < arr[index] and inc[column] + 1 > inc[index]:
                inc[index] = inc[column] + 1
    return inc


def decreasing_lengths(arr):
    """Length of the longest decreasing subsequence starting at each position."""
    n = len(arr)
    dec = [1] * n
    for index in range(n - 1, -1, -1):
        for column in range(index + 1, n):
            if arr[column] < arr[index] and dec[column] + 1 > dec[index]:
                dec[index] = dec[column] + 1
    return dec


def longest_bitonic_subsequence(arr):
    """Return the length of the longest bitonic (up then down) subsequence."""
    validate(arr)
    inc = increasing_lengths(arr)
    dec = decreasing_lengths(arr)
    best = 0
    for index in range(len(arr)):
        if inc[index] + dec[index] - 1 > best:
            best = inc[index] + dec[index] - 1
    return best


def bitonic_subsequence(arr):
    """Rebuild one longest bitonic subsequence from the DP tables."""
    validate(arr)
    if not arr:
        return []
    inc = increasing_lengths(arr)
    dec = decreasing_lengths(arr)
    n = len(arr)
    peak = 0
    for index in range(n):
        if inc[index] + dec[index] > inc[peak] + dec[peak]:
            peak = index
    left = [arr[peak]]
    cur = peak
    for column in range(peak - 1, -1, -1):
        if arr[column] < arr[cur] and inc[column] == inc[cur] - 1:
            left.append(arr[column])
            cur = column
    left.reverse()
    right = []
    cur = peak
    for column in range(peak + 1, n):
        if arr[column] < arr[cur] and dec[column] == dec[cur] - 1:
            right.append(arr[column])
            cur = column
    return left + right


def format_report(datasets):
    lines = []
    for index, data in enumerate(datasets, start=1):
        length = longest_bitonic_subsequence(data)
        chain = ", ".join(map(str, bitonic_subsequence(data)))
        lines.append("case %d: %s -> %d  [%s]" % (index, data, length, chain))
    return "\n".join(lines)


def main():
    samples = [
        [1, 11, 2, 10, 4, 5, 2, 1],
        [12, 11, 40, 5, 3, 1],
        [80, 60, 30, 40, 20, 10],
        [1, 2, 3, 4, 5],
        [7],
        [],
    ]
    print(format_report(samples))


if __name__ == "__main__":
    main()

