    """Return the Longest Proper Prefix which is also Suffix array of `pattern`."""
    n = len(pattern)
    lps = [0] * n
    length = 0
    for i in range(1, n):
        while length > 0 and pattern[i] != pattern[length]:
            length = lps[length - 1]
        if pattern[i] == pattern[length]:
            length += 1
        lps[i] = length
    return lps


def kmp_search(text, pattern):
    """Return the starting indices of every occurrence of `pattern` in `text`."""
    if not pattern or len(pattern) > len(text):
        return []
    lps = compute_lps_array(pattern)
    matches = []
    matched = 0
    for i in range(len(text)):
        while matched > 0 and text[i] != pattern[matched]:
            matched = lps[matched - 1]
        if text[i] == pattern[matched]:
            matched += 1
        if matched == len(pattern):
            matches.append(i - matched + 1)
            matched = lps[matched - 1]
    return matches


def format_lps_table(pattern, lps):
    """Render the pattern and its LPS values as three aligned rows."""
    index_row, char_row, lps_row = [], [], []
    for j in range(len(pattern)):
