def get_rotations(s):
    """Return every cyclic rotation of s, starting with s itself."""
    rotations = []
    for i in range(len(s)):
        rotations.append(s[i:] + s[:i])
    return rotations


def bwt_encode(s):
    """Burrows-Wheeler transform of s, using '$' as end-of-string marker."""
    if "$" in s:
        raise ValueError("the end-of-string marker '$' must not occur in the input")
    terminated = s + "$"
    last_column = []
    for k in sorted(get_rotations(terminated)):
        last_column.append(k[-1])
    return "".join(last_column)


def bwt_decode(encoded):
    """Recover the original string from its Burrows-Wheeler transform."""
    if encoded.count("$") != 1:
        raise ValueError("a BWT-encoded string must contain exactly one '$'")
    size = len(encoded)
    table = [""] * size
    for i in range(size):
        rows = []
        for j in range(size):
            rows.append(encoded[j] + table[j])
        table = sorted(rows)
    for i in range(size):
        if table[i].endswith("$"):
            return table[i][:-1]
    raise ValueError("no row of the reconstructed matrix ends with '$'")


def format_matrix(s):
    """Build report lines showing the sorted rotation matrix of s + '$'."""
    rotations = sorted(get_rotations(s + "$"))
    lines = ["index | rotation | last"]
    for i in range(len(rotations)):
        lines.append("%5d | %-8s | %s" % (i, rotations[i], rotations[i][-1]))
    return lines


def main():
    words = ["banana", "mississippi", "abracadabra", ""]
    for n in words:
        encoded = bwt_encode(n)
        decoded = bwt_decode(encoded)
        print("input:   %r" % n)
        print("encoded: %r" % encoded)
        print("decoded: %r (round trip ok: %s)" % (decoded, decoded == n))
        print()

    for k in format_matrix("banana"):
        print(k)


if __name__ == "__main__":
    main()

