RULE_NUMBER = 30


def validate_state(state):
    """Check that the state is a non-empty list of 0s and 1s."""
    if not isinstance(state, list) or len(state) == 0:
        raise ValueError("initial_state must be a non-empty list")
    for i in range(len(state)):
        if state[i] not in (0, 1):
            raise ValueError("cell %d is not 0 or 1: %r" % (i, state[i]))


def build_rule_table(number):
    """Expand a Wolfram rule number into a {(left, centre, right): value} table."""
    table = {}
    for i in range(8):
        bits = []
        for k in (2, 1, 0):
            bits.append((i >> k) & 1)
        table[tuple(bits)] = (number >> i) & 1
    return table


def simulate_rule_30(initial_state, steps):
    """Return the state of the automaton at every time step, initial state first."""
    validate_state(initial_state)
    if not isinstance(steps, int) or steps < 0:
        raise ValueError("steps must be a non-negative integer")
    table = build_rule_table(RULE_NUMBER)
    n = len(initial_state)
    history = [list(initial_state)]
    for i in range(steps):
        current = history[i]
        nxt = [0] * n
        for j in range(n):
            nxt[j] = table[(current[j - 1], current[j], current[(j + 1) % n])]
        history.append(nxt)
    return history


def format_history(history, on="#", off="."):
    """Render the history as one labelled text line per time step."""
    lines = []
    for i in range(len(history)):
        row = history[i]
        cells = []
        for k in range(len(row)):
            cells.append(on if row[k] else off)
        lines.append("%3d: %s" % (i, "".join(cells)))
    return lines


def density_profile(history):
    """Fraction of live cells at each time step."""
    profile = []
    for row in history:
        live = 0
        for k in range(len(row)):
            live += row[k]
        profile.append(live / len(row))
    return profile


def column_activity(history):
    """How many times each cell position was alive over the whole run."""
    n = len(history[0])
    totals = [0] * n
    for i in range(len(history)):
        for j in range(n):
            totals[j] += history[i][j]
    return totals


def main():
    width, steps = 31, 15
    start = [0] * width
    start[width // 2] = 1
    history = simulate_rule_30(start, steps)
    for line in format_history(history):
        print(line)
    profile = density_profile(history)
    print("\ndensity per step:")
    for i in range(len(profile)):
        print("%3d: %.3f" % (i, profile[i]))
    totals = column_activity(history)
    busiest = 0
    for j in range(len(totals)):
        if totals[j] > totals[busiest]:
            busiest = j
    print("\nbusiest column: %d (alive %d of %d steps)"
          % (busiest, totals[busiest], len(history)))
    print("simulate_rule_30([0, 1, 0], 1) ->", simulate_rule_30([0, 1, 0], 1))


if __name__ == "__main__":
    main()

