def validate_integers(values):
    """Return a list copy of values, raising TypeError on non-integer entries."""
    checked = []
    for i, value in enumerate(values):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("element %d is not an integer: %r" % (i, value))
        checked.append(value)
    return checked


def odd_even_sort(arr):
    """Sort arr in-place with the odd-even transposition sort and return it."""
    n = len(arr)
    sorted_flag = False
    while not sorted_flag:
        sorted_flag = True
        for i in range(1, n - 1, 2):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
                sorted_flag = False
        for j in range(0, n - 1, 2):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                sorted_flag = False
    return arr


def is_sorted(arr):
    """True when every neighbouring pair is in non-decreasing order."""
    for k in range(len(arr) - 1):
        if arr[k] > arr[k + 1]:
            return False
    return True


def inversion_count(arr):
    """Number of out-of-order pairs, used to describe how messy the input was."""
    total = 0
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            if arr[i] > arr[j]:
                total += 1
    return total


def format_row(label, values):
    """Render one aligned report line such as 'random  : [   1,   2,   3]'."""
    cells = []
    for k in range(len(values)):
        cells.append("%4d" % values[k])
    return "%-12s: [%s]" % (label, ",".join(cells))


def main():
    datasets = {
        "random": [5, 1, 4, 2, 8, 0, 2],
        "reversed": [9, 7, 5, 3, 1],
        "sorted": [1, 2, 3, 4, 5],
        "single": [42],
        "empty": [],
    }
    for label in sorted(datasets):
        original = validate_integers(datasets[label])
        messiness = inversion_count(original)
        result = odd_even_sort(list(original))
        print(format_row(label + " in", original))
        print(format_row(label + " out", result))
        print("%-12s  inversions=%d sorted=%s" % ("", messiness, is_sorted(result)))


if __name__ == "__main__":
    main()

