import math

def dot(a, b):
    total = 0.0
    for i in range(len(a)):
        total += a[i] * b[i]
    return total

def project(u, v):
    denom = dot(u, u)
    if denom == 0.0:
        return [0.0] * len(u)
    scale = dot(u, v) / denom
    return [scale * u[i] for i in range(len(u))]

def validate(vectors):
    if not vectors:
        raise ValueError("no vectors given")
    width = len(vectors[0])
    for j in range(len(vectors)):
        if len(vectors[j]) != width:
            raise ValueError("vector %d has length %d, expected %d"
                             % (j, len(vectors[j]), width))
        for k in range(width):
            if not isinstance(vectors[j][k], (int, float)):
                raise TypeError("component %d of vector %d is not numeric" % (k, j))
    return width

def gram_schmidt(vectors):
    width = validate(vectors)
    basis = []
    for i in range(len(vectors)):
        current = [float(vectors[i][n]) for n in range(width)]
        for j in range(len(basis)):
            p = project(basis[j], current)
            for k in range(width):
                current[k] -= p[k]
        basis.append(current)
    return basis

def norm(v):
    total = 0.0
    for i in range(len(v)):
        total += v[i] * v[i]
    return math.sqrt(total)

def normalize(vectors):
    unit = []
    for i in range(len(vectors)):
        length = norm(vectors[i])
        if length == 0.0:
            unit.append([0.0] * len(vectors[i]))
        else:
            unit.append([vectors[i][n] / length for n in range(len(vectors[i]))])
    return unit

def format_vector(v, digits=4):
    parts = []
    for i in range(len(v)):
        parts.append("%.*f" % (digits, v[i]))
    return "[" + ", ".join(parts) + "]"

def orthogonality_report(basis):
    lines = []
    for i in range(len(basis)):
