import math

def dot(a, b):
    total = 0.0
    for index in range(len(a)):
        total += a[index] * b[index]
    return total

def project(u, v):
    denom = dot(u, u)
    if denom == 0.0:
        return [0.0] * len(u)
    scale = dot(u, v) / denom
    return [scale * u[index] for index in range(len(u))]

def validate(vectors):
    if not vectors:
        raise ValueError("no vectors given")
    width = len(vectors[0])
    for column in range(len(vectors)):
        if len(vectors[column]) != width:
            raise ValueError("vector %d has length %d, expected %d"
                             % (column, len(vectors[column]), width))
        for key in range(width):
            if not isinstance(vectors[column][key], (int, float)):
                raise TypeError("component %d of vector %d is not numeric" % (key, column))
    return width

def gram_schmidt(vectors):
    width = validate(vectors)
    basis = []
    for index in range(len(vectors)):
        current = [float(vectors[index][number]) for number in range(width)]
        for column in range(len(basis)):
            p = project(basis[column], current)
            for key in range(width):
                current[key] -= p[key]
        basis.append(current)
    return basis

def norm(v):
    total = 0.0
    for index in range(len(v)):
        total += v[index] * v[index]
    return math.sqrt(total)

def normalize(vectors):
    unit = []
    for index in range(len(vectors)):
        length = norm(vectors[index])
        if length == 0.0:
            unit.append([0.0] * len(vectors[index]))
        else:
            unit.append([vectors[index][number] / length for number in range(len(vectors[index]))])
    return unit

def format_vector(v, digits=4):
    parts = []
    for index in range(len(v)):
        parts.append("%.*f" % (digits, v[index]))
    return "[" + ", ".join(parts) + "]"

def orthogonality_report(basis):
    lines = []
    for index in range(len(basis)):
        for column in range(index + 1, len(basis)):
            lines.append("  <v%d, v%d> = %.6f" % (index, column, dot(basis[index], basis[column])))
    return lines

def main():
    samples = [
        [[3.0, 1.0], [2.0, 2.0]],
        [[1.0, 1.0, 0.0], [1.0, 0.0, 1.0], [0.0, 1.0, 1.0]],
    ]
    for number in range(len(samples)):
        basis = gram_schmidt(samples[number])
        print("input set %d:" % number)
        for index in range(len(samples[number])):
            print("  %s -> %s" % (format_vector(samples[number][index]), format_vector(basis[index])))
        units = normalize(basis)
        for index in range(len(units)):
            print("  unit %d: %s" % (index, format_vector(units[index])))
        for line in orthogonality_report(basis):
            print(line)

