        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("list must contain only integers, found %r" % (value,))
    return arr


def gap_sequence(length):
    """The gaps shell_sort will visit for a list of the given length."""
    gaps = []
    gap = length // 2
    while gap > 0:
        gaps.append(gap)
        gap //= 2
    return gaps


def shell_sort(arr):
    """Sort a list of integers in place with the classic halving-gap shell sort."""
    validate(arr)
    gap = len(arr) // 2
    while gap > 0:
        for i in range(gap, len(arr)):
            current = arr[i]
            j = i
            while j >= gap and arr[j - gap] > current:
                arr[j] = arr[j - gap]
                j -= gap
            arr[j] = current
        gap //= 2
    return arr


def is_sorted(arr):
    """True when every neighbouring pair is in non-decreasing order."""
    for i in range(1, len(arr)):
        if arr[i - 1] > arr[i]:
            return False
    return True


def count_inversions(arr):
    """Number of out-of-order pairs, a measure of how unsorted a list is."""
    total = 0
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            if arr[i] > arr[j]:
                total += 1
    return total


