import math


def validate(arr):
    if not isinstance(arr, (list, tuple)):
        raise TypeError("arr must be a list or tuple")
    for i in range(len(arr)):
        if not isinstance(arr[i], int) or isinstance(arr[i], bool):
            raise TypeError("element at index %d is not an integer" % i)
        if arr[i] < 0:
            raise ValueError("element at index %d is negative" % i)
    return list(arr)


def min_jumps(arr):
    arr = validate(arr)
    n = len(arr)
    if n <= 1:
        return 0
    jumps = [math.inf] * n
    jumps[0] = 0
    for i in range(1, n):
        for j in range(i):
            if jumps[j] + 1 < jumps[i] and j + arr[j] >= i:
                jumps[i] = jumps[j] + 1
    if jumps[n - 1] == math.inf:
        return -1
    return jumps[n - 1]


def jump_table(arr):
    arr = validate(arr)
    n = len(arr)
    table = [math.inf] * n
    if n:
        table[0] = 0
    for i in range(1, n):
        for j in range(i):
            if table[j] + 1 < table[i] and j + arr[j] >= i:
                table[i] = table[j] + 1
    return table


def reconstruct_path(arr):
    table = jump_table(arr)
    n = len(arr)
    if n == 0 or table[n - 1] == math.inf:
        return []
    path = [n - 1]
    k = n - 1
    while k > 0:
        for j in range(k):
            if table[j] + 1 == table[k] and j + arr[j] >= k:
                path.append(j)
                k = j
                break
    path.reverse()
    return path


def format_report(arr):
    total = min_jumps(arr)
    lines = ["array: %s" % (list(arr),)]
    if total == -1:
        lines.append("end unreachable")
        return "\n".join(lines)
    path = reconstruct_path(arr)
    lines.append("minimum jumps: %d" % total)
    for k in range(1, len(path)):
        lines.append("  step %d: index %d -> index %d (max %d)"
                     % (k, path[k - 1], path[k], arr[path[k - 1]]))
    return "\n".join(lines)


def main():
    cases = [
        [2, 3, 1, 1, 2, 4, 2, 0, 1, 1],
        [1, 1, 1, 1],
        [3, 2, 1, 0, 4],
        [0],
    ]
    for i in range(len(cases)):
        print("case %d" % (i + 1))
        print(format_report(cases[i]))
        print()


if __name__ == "__main__":
    main()

