import random


def transpose(A):
    rows, cols = len(A), len(A[0])
    T = [[0.0] * rows for _ in range(cols)]
    for i in range(rows):
        for j in range(cols):
            T[j][i] = A[i][j]
    return T


def dot(u, v):
    total = 0.0
    for i in range(len(u)):
        total += u[i] * v[i]
    return total


def matmul(A, B):
    Bt = transpose(B)
    C = [[0.0] * len(Bt) for _ in range(len(A))]
    for i in range(len(A)):
        for j in range(len(Bt)):
            C[i][j] = dot(A[i], Bt[j])
    return C


def elementwise_divide(A, B, eps=1e-10):
    Q = [[0.0] * len(A[0]) for _ in range(len(A))]
    for i in range(len(A)):
        for j in range(len(A[0])):
            Q[i][j] = A[i][j] / (B[i][j] + eps)
    return Q


def elementwise_multiply_inplace(A, B):
    for i in range(len(A)):
        for j in range(len(A[0])):
            A[i][j] *= B[i][j]


def random_matrix(rows, cols):
    M = [[0.0] * cols for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            M[i][j] = random.uniform(0.01, 0.1)
    return M


def frobenius_error(V, W, H):
    R = matmul(W, H)
    total = 0.0
    for i in range(len(V)):
        for j in range(len(V[0])):
            diff = V[i][j] - R[i][j]
            total += diff * diff
    return total ** 0.5


def nmf_factorize(V, k, iterations):
    rows, cols = len(V), len(V[0])
    W = random_matrix(rows, k)
    H = random_matrix(k, cols)
    for _ in range(iterations):
        Wt = transpose(W)
        elementwise_multiply_inplace(
            H, elementwise_divide(matmul(Wt, V), matmul(matmul(Wt, W), H)))
        Ht = transpose(H)
        elementwise_multiply_inplace(
            W, elementwise_divide(matmul(V, Ht), matmul(W, matmul(H, Ht))))
    return W, H


def format_matrix(M, name):
    lines = [name + ":"]
    for i in range(len(M)):
        lines.append("  " + "  ".join("%7.3f" % M[i][j] for j in range(len(M[0]))))
    return "\n".join(lines)


def main():
    random.seed(7)
    V = [[5.0, 3.0, 0.0, 1.0],
         [4.0, 0.0, 0.0, 1.0],
         [1.0, 1.0, 0.0, 5.0],
         [1.0, 0.0, 0.0, 4.0],
         [0.0, 1.0, 5.0, 4.0]]
    W, H = nmf_factorize(V, 2, 300)
    print(format_matrix(W, "W"))
    print(format_matrix(H, "H"))
    print(format_matrix(matmul(W, H), "W*H"))
    print("error: %.6f" % frobenius_error(V, W, H))


if __name__ == "__main__":
    main()

