ALPHABET_SIZE = 26


def normalize_key(key):
    """Return the key reduced to lowercase letters, raising if it has none."""
    letters = []
    for i in range(len(key)):
        if key[i].isalpha():
            letters.append(key[i].lower())
    if not letters:
        raise ValueError("key must contain at least one alphabetic character")
    return "".join(letters)


def _shift_char(ch, amount):
    base = ord("A") if ch.isupper() else ord("a")
    return chr(base + (ord(ch) - base + amount) % ALPHABET_SIZE)


def _transform(text, key, sign):
    key_letters = normalize_key(key)
    out = []
    key_index = 0
    for i in range(len(text)):
        ch = text[i]
        if ch.isalpha():
            amount = ord(key_letters[key_index % len(key_letters)]) - ord("a")
            out.append(_shift_char(ch, sign * amount))
            key_index += 1
        else:
            out.append(ch)
    return "".join(out)


def vigenere_encrypt(plaintext, key):
    return _transform(plaintext, key, 1)


def vigenere_decrypt(ciphertext, key):
    return _transform(ciphertext, key, -1)


def key_alignment(text, key):
    """Show which key letter is used under each alphabetic character."""
    key_letters = normalize_key(key)
    row = []
    key_index = 0
    for i in range(len(text)):
        if text[i].isalpha():
            row.append(key_letters[key_index % len(key_letters)])
            key_index += 1
        else:
            row.append(" ")
    return "".join(row)


def strip_non_alpha(text):
    kept = []
    for i in range(len(text)):
        if text[i].isalpha():
            kept.append(text[i])
    return "".join(kept)


def format_blocks(text, n=5):
    blocks = []
    for i in range(0, len(text), n):
        blocks.append(text[i:i + n])
    return " ".join(blocks)


def main():
    samples = [
        ("Hello, World!", "key"),
        ("Attack at dawn.", "LEMON"),
        ("The quick brown fox jumps!", "Cipher-42"),
    ]
    for j in range(len(samples)):
        plaintext, key = samples[j]
        cipher = vigenere_encrypt(plaintext, key)
        recovered = vigenere_decrypt(cipher, key)
        print("case {0} (key={1!r})".format(j + 1, key))
        print("  plain : " + plaintext)
        print("  keyrow: " + key_alignment(plaintext, key))
        print("  cipher: " + cipher)
        print("  groups: " + format_blocks(strip_non_alpha(cipher)))
        print("  round-trip ok: {0}".format(recovered == plaintext))


if __name__ == "__main__":
    main()

