import copy


def validate_square(matrix):
    n = len(matrix)
    if n == 0:
        raise ValueError("matrix must not be empty")
    for i in range(n):
        if len(matrix[i]) != n:
            raise ValueError("row %d has length %d, expected %d" % (i, len(matrix[i]), n))
        for j in range(n):
            if not isinstance(matrix[i][j], int):
                raise TypeError("entry (%d, %d) is not an integer" % (i, j))
    return n


def identity(n):
    result = []
    for i in range(n):
        row = [0] * n
        row[i] = 1
        result.append(row)
    return result


def matrix_multiply(A, B):
    n = len(A)
    m = len(B[0])
    inner = len(B)
    product = []
    for i in range(n):
        row = [0] * m
        for j in range(m):
            total = 0
            for k in range(inner):
                total += A[i][k] * B[k][j]
            row[j] = total
        product.append(row)
    return product


def matrix_power(matrix, p):
    n = validate_square(matrix)
    if p < 0:
        raise ValueError("exponent must be non-negative")
    result = identity(n)
    base = copy.deepcopy(matrix)
    while p > 0:
        if p & 1:
            result = matrix_multiply(result, base)
        base = matrix_multiply(base, base)
        p >>= 1
    return result


def format_matrix(matrix):
    width = 0
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            width = max(width, len(str(matrix[i][j])))
    lines = []
    for i in range(len(matrix)):
        cells = []
        for j in range(len(matrix[i])):
            cells.append(str(matrix[i][j]).rjust(width))
        lines.append("[ " + "  ".join(cells) + " ]")
    return "\n".join(lines)


def main():
    fib = [[1, 1], [1, 0]]
    for k in range(1, 6):
        powered = matrix_power(fib, k)
        print("fib matrix ^ %d  ->  F(%d) = %d" % (k, k, powered[0][1]))
        print(format_matrix(powered))

    magic = [[2, 0, 1], [1, 3, 0], [0, 1, 2]]
    for k in (0, 2, 5):
        print("magic ^ %d" % k)
        print(format_matrix(matrix_power(magic, k)))


if __name__ == "__main__":
    main()

