def validate_input(arr, target_sum):
    if not isinstance(arr, (list, tuple)):
        raise TypeError("arr must be a list or tuple of integers")
    for i in range(len(arr)):
        if not isinstance(arr[i], int) or isinstance(arr[i], bool):
            raise TypeError("arr[%d] is not an integer: %r" % (i, arr[i]))
        if arr[i] < 0:
            raise ValueError("arr[%d] is negative: %d" % (i, arr[i]))
    if not isinstance(target_sum, int) or isinstance(target_sum, bool):
        raise TypeError("target_sum must be an integer")
    if target_sum < 0:
        raise ValueError("target_sum must be non-negative")


def build_table(arr, target_sum):
    n = len(arr)
    table = [[False] * (target_sum + 1) for i in range(n + 1)]
    for i in range(n + 1):
        table[i][0] = True
    for i in range(1, n + 1):
        for j in range(1, target_sum + 1):
            table[i][j] = table[i - 1][j]
            if arr[i - 1] <= j and table[i - 1][j - arr[i - 1]]:
                table[i][j] = True
    return table


def can_form_subset_sum(arr, target_sum):
    validate_input(arr, target_sum)
    table = build_table(arr, target_sum)
    return table[len(arr)][target_sum]


def find_subset(arr, target_sum):
    validate_input(arr, target_sum)
    table = build_table(arr, target_sum)
    if not table[len(arr)][target_sum]:
        return None
    chosen = []
    remaining = target_sum
    for i in range(len(arr), 0, -1):
        if table[i - 1][remaining]:
            continue
        chosen.append(arr[i - 1])
        remaining -= arr[i - 1]
    chosen.reverse()
    return chosen


def format_table(arr, target_sum):
    table = build_table(arr, target_sum)
    header = "     " + "".join("%3d" % j for j in range(target_sum + 1))
    lines = [header, "     " + "---" * (target_sum + 1)]
    for i in range(len(table)):
        label = "  -" if i == 0 else "%3d" % arr[i - 1]
        cells = "".join("  T" if table[i][j] else "  ." for j in range(target_sum + 1))
        lines.append(label + " |" + cells)
    return "\n".join(lines)


def main():
    cases = [([3, 34, 4, 12, 5, 2], 9), ([1, 2, 5], 4), ([7], 7), ([], 0)]
    for k in range(len(cases)):
        arr, target_sum = cases[k]
        print("Case %d: arr=%s target=%d" % (k + 1, arr, target_sum))
        print("  reachable: %s" % can_form_subset_sum(arr, target_sum))
        subset = find_subset(arr, target_sum)
        print("  subset: %s" % ("none" if subset is None else subset))
        if target_sum <= 12 and len(arr) <= 8:
            print(format_table(arr, target_sum))
        print()


if __name__ == "__main__":
    main()

