def validate_sequence(arr):
    """Return a list copy of arr, rejecting anything that is not a numeric sequence."""
    if not isinstance(arr, (list, tuple)):
        raise TypeError("expected a list or tuple of numbers")
    for i in range(len(arr)):
        if isinstance(arr[i], bool) or not isinstance(arr[i], (int, float)):
            raise TypeError("element at index %d is not a number: %r" % (i, arr[i]))
    return list(arr)


def longest_alternating_subsequence(arr):
    """Length of the longest zigzag (alternating) subsequence of arr."""
    values = validate_sequence(arr)
    n = len(values)
    if n == 0:
        return 0
    up = [1] * n
    down = [1] * n
    for i in range(1, n):
        for j in range(i):
            if values[i] > values[j]:
                up[i] = max(up[i], down[j] + 1)
            elif values[i] < values[j]:
                down[i] = max(down[i], up[j] + 1)
    best = 1
    for k in range(n):
        best = max(best, up[k], down[k])
    return best


def extract_alternating_subsequence(arr):
    """Build one concrete longest alternating subsequence, greedily keeping extremes."""
    values = validate_sequence(arr)
    if not values:
        return []
    picked = [values[0]]
    direction = 0
    for i in range(1, len(values)):
        delta = values[i] - picked[-1]
        if delta > 0:
            if direction == 1:
                picked[-1] = values[i]
            else:
                picked.append(values[i])
                direction = 1
        elif delta < 0:
            if direction == -1:
                picked[-1] = values[i]
            else:
                picked.append(values[i])
                direction = -1
    return picked


def format_report(label, arr):
    """Describe the alternating subsequence result for one input sequence."""
    length = longest_alternating_subsequence(arr)
    witness = extract_alternating_subsequence(arr)
    signs = []
    for j in range(1, len(witness)):
        signs.append("+" if witness[j] > witness[j - 1] else "-")
    return "\n".join([
        "%s: %s" % (label, list(arr)),
        "  length  = %d" % length,
        "  witness = %s" % witness,
        "  pattern = %s" % ("".join(signs) or "(none)"),
    ])


def main():
    datasets = [
        ("mixed", [1, 5, 4, 3, 2, 6, 7]),
        ("strictly increasing", [1, 2, 3, 4, 5]),
        ("with plateaus", [3, 3, 3, 7, 7, 2, 2, 9]),
        ("single value", [42]),
        ("empty", []),
    ]
    for i, (label, data) in enumerate(datasets, start=1):
        print(format_report("%d. %s" % (i, label), data))


if __name__ == "__main__":
    main()

