def matrix_size(M, name):
    n = len(M)
    for i in range(n):
        if len(M[i]) != n:
            raise ValueError("%s is not square: row %d has %d entries" % (name, i, len(M[i])))
    return n


def sequential_matrix(n, start=1):
    M = []
    for i in range(n):
        row = []
        for j in range(n):
            row.append(start + i * n + j)
        M.append(row)
    return M


def format_matrix(M):
    width = 0
    for row in M:
        for value in row:
            width = max(width, len("%g" % value))
    lines = []
    for i in range(len(M)):
        cells = []
        for j in range(len(M[i])):
            cells.append("%*g" % (width, M[i][j]))
        lines.append("[ " + "  ".join(cells) + " ]")
    return "\n".join(lines)


def accumulate_tile(C, A, B, row_start, row_stop, col_start, col_stop, dep_start, dep_stop):
    for i in range(row_start, row_stop):
        for j in range(col_start, col_stop):
            total = C[i][j]
            for k in range(dep_start, dep_stop):
                total += A[i][k] * B[k][j]
            C[i][j] = total


def block_matmul(A, B, block_size):
    n = matrix_size(A, "A")
    if matrix_size(B, "B") != n:
        raise ValueError("A and B must have the same size")
    if block_size <= 0:
        raise ValueError("block_size must be positive")

    C = []
    for i in range(n):
        row = []
        for j in range(n):
            row.append(0.0)
        C.append(row)

    for i in range(0, n, block_size):
        for j in range(0, n, block_size):
            for k in range(0, n, block_size):
                accumulate_tile(C, A, B,
                                i, min(i + block_size, n),
                                j, min(j + block_size, n),
                                k, min(k + block_size, n))

    for i in range(n):
        for j in range(n):
            C[i][j] = C[i][j] * 1.0
    return C


def main():
    n = 4
    A = sequential_matrix(n, 1)
    B = sequential_matrix(n, n * n + 1)
    C = block_matmul(A, B, 2)
