INF = float("inf")


def validate(eggs, floors):
    """Reject non-integral or non-positive puzzle parameters."""
    for n in (eggs, floors):
        if isinstance(n, bool) or not isinstance(n, int):
            raise TypeError("eggs and floors must be integers")
        if n < 1:
            raise ValueError("eggs and floors must be at least 1")


def build_table(eggs, floors):
    """Return the DP table indexed by egg budget and floor count, holding the
    worst-case number of trials needed for that state."""
    table = [[INF] * (floors + 1) for _ in range(eggs + 1)]

    for i in range(1, eggs + 1):
        table[i][0] = 0
        table[i][1] = 1
    for j in range(1, floors + 1):
        table[1][j] = j

    for i in range(2, eggs + 1):
        for j in range(2, floors + 1):
            best = INF
            for k in range(1, j + 1):
                worst = 1 + max(table[i - 1][k - 1], table[i][j - k])
                if worst < best:
                    best = worst
            table[i][j] = best

    return table


def print_summary(table, eggs, floors):
    """Print worst-case trials per floor count, for the given egg budget."""
    print("floors  trials")
    for n in range(1, floors + 1):
        print("{:6d}  {:6d}".format(n, table[eggs][n]))


def min_egg_drops(eggs, floors):
    """Minimum number of trials needed in the worst case."""
    validate(eggs, floors)
    table = build_table(eggs, floors)
    print_summary(table, eggs, floors)
    return table[eggs][floors]


def critical_floors(table, eggs, floors):
    """For each trial count reachable within the limit, the highest floor
    count still solvable in that many trials."""
    reach = {}
    for n in range(1, floors + 1):
        reach[table[eggs][n]] = n
    return [(trials, reach[trials]) for trials in sorted(reach)]


def main():
    eggs, floors = 2, 36
    answer = min_egg_drops(eggs, floors)
    print("\nWith {} eggs and {} floors: {} trials".format(eggs, floors, answer))

    table = build_table(eggs, floors)
    print("\ntrials  highest solvable building")
    for trials, height in critical_floors(table, eggs, floors):
        print("{:6d}  {:6d}".format(trials, height))


if __name__ == "__main__":
    main()

