import logging

logging.basicConfig(level=logging.INFO, format="%(message)s")
LOG = logging.getLogger("boolparen")

VALID_SYMBOLS = "TF"
VALID_OPERATORS = "&|^"


def validate(symbols, operators):
    if len(symbols) != len(operators) + 1:
        raise ValueError("expected %d operators for %d symbols"
                         % (len(symbols) - 1, len(symbols)))
    for i in range(len(symbols)):
        if symbols[i] not in VALID_SYMBOLS:
            raise ValueError("bad symbol %r at position %d" % (symbols[i], i))
    for i in range(len(operators)):
        if operators[i] not in VALID_OPERATORS:
            raise ValueError("bad operator %r at position %d" % (operators[i], i))


def combine(op, left_true, left_false, right_true, right_false):
    total = (left_true + left_false) * (right_true + right_false)
    if op == "&":
        true_ways = left_true * right_true
    elif op == "|":
        true_ways = total - left_false * right_false
    else:
        true_ways = left_true * right_false + left_false * right_true
    return true_ways, total - true_ways


def count_eval_true(symbols, operators):
    validate(symbols, operators)
    size = len(symbols)
    true_dp = [[0] * size for _ in range(size)]
    false_dp = [[0] * size for _ in range(size)]
    for i in range(size):
        true_dp[i][i] = 1 if symbols[i] == "T" else 0
        false_dp[i][i] = 1 - true_dp[i][i]
    for length in range(2, size + 1):
        for i in range(size - length + 1):
            end = i + length - 1
            for k in range(i, end):
                true_ways, false_ways = combine(
                    operators[k], true_dp[i][k], false_dp[i][k],
                    true_dp[k + 1][end], false_dp[k + 1][end])
                true_dp[i][end] += true_ways
                false_dp[i][end] += false_ways
    for j in range(size):
        LOG.debug("prefix %s -> true=%d false=%d",
                  symbols[:j + 1], true_dp[0][j], false_dp[0][j])
    return true_dp[0][size - 1]


def build_expression(symbols, operators):
    parts = []
    for i in range(len(operators)):
        parts.append(symbols[i])
        parts.append(operators[i])
    parts.append(symbols[-1])
    return "".join(parts)


def main():
    cases = [("TTFT", "|&^"), ("T", ""), ("TFT", "^&"), ("FFTTT", "|^&|")]
    for i in range(len(cases)):
        symbols, operators = cases[i]
