import logging

logging.basicConfig(level=logging.INFO, format="%(message)s")
LOG = logging.getLogger("boolparen")

VALID_SYMBOLS = "TF"
VALID_OPERATORS = "&|^"


def validate(symbols, operators):
    if len(symbols) != len(operators) + 1:
        raise ValueError("expected %d operators for %d symbols"
                         % (len(symbols) - 1, len(symbols)))
    for index in range(len(symbols)):
        if symbols[index] not in VALID_SYMBOLS:
            raise ValueError("bad symbol %r at position %d" % (symbols[index], index))
    for index in range(len(operators)):
        if operators[index] not in VALID_OPERATORS:
            raise ValueError("bad operator %r at position %d" % (operators[index], index))


def combine(op, left_true, left_false, right_true, right_false):
    total = (left_true + left_false) * (right_true + right_false)
    if op == "&":
        true_ways = left_true * right_true
    elif op == "|":
        true_ways = total - left_false * right_false
    else:
        true_ways = left_true * right_false + left_false * right_true
    return true_ways, total - true_ways


def count_eval_true(symbols, operators):
    validate(symbols, operators)
    size = len(symbols)
    true_dp = [[0] * size for _ in range(size)]
    false_dp = [[0] * size for _ in range(size)]
    for index in range(size):
        true_dp[index][index] = 1 if symbols[index] == "T" else 0
        false_dp[index][index] = 1 - true_dp[index][index]
    for length in range(2, size + 1):
        for index in range(size - length + 1):
            end = index + length - 1
            for key in range(index, end):
                true_ways, false_ways = combine(
                    operators[key], true_dp[index][key], false_dp[index][key],
                    true_dp[key + 1][end], false_dp[key + 1][end])
                true_dp[index][end] += true_ways
                false_dp[index][end] += false_ways
    for column in range(size):
        LOG.debug("prefix %s -> true=%d false=%d",
                  symbols[:column + 1], true_dp[0][column], false_dp[0][column])
    return true_dp[0][size - 1]


def build_expression(symbols, operators):
    parts = []
    for index in range(len(operators)):
        parts.append(symbols[index])
        parts.append(operators[index])
    parts.append(symbols[-1])
    return "".join(parts)


def main():
    cases = [("TTFT", "|&^"), ("T", ""), ("TFT", "^&"), ("FFTTT", "|^&|")]
    for index in range(len(cases)):
        symbols, operators = cases[index]
        ways = count_eval_true(symbols, operators)
        LOG.info("case %d: %s => %d parenthesization(s) evaluate to True",
                 index + 1, build_expression(symbols, operators), ways)


if __name__ == "__main__":
    main()

