    grid = []
    for i in range(len(matrix)):
        row = []
        for j in range(len(matrix[i])):
            cell = matrix[i][j]
            if isinstance(cell, str):
                text = cell.strip()
                if text not in ("0", "1"):
                    raise ValueError("bad cell %r at (%d, %d)" % (cell, i, j))
                row.append(int(text))
            elif isinstance(cell, bool):
                row.append(1 if cell else 0)
            else:
                if cell not in (0, 1):
                    raise ValueError("bad cell %r at (%d, %d)" % (cell, i, j))
                row.append(int(cell))
        grid.append(row)
    for i in range(1, len(grid)):
        if len(grid[i]) != len(grid[0]):
            raise ValueError("row %d has inconsistent width" % i)
    return grid


def largest_histogram_area(heights):
    """Largest rectangle under a histogram, using a stack of increasing bars."""
    stack = []
    best = 0
    for i in range(len(heights) + 1):
        current = heights[i] if i < len(heights) else 0
        while stack and heights[stack[-1]] >= current:
            top = stack.pop()
            left = stack[-1] + 1 if stack else 0
            best = max(best, heights[top] * (i - left))
        stack.append(i)
    return best


def maximal_rectangle(matrix):
    grid = normalize(matrix)
    if not grid or not grid[0]:
        return 0
    width = len(grid[0])
    heights = [0] * width
    snapshots = []
    best = 0
    for i in range(len(grid)):
        for j in range(width):
            heights[j] = heights[j] + 1 if grid[i][j] else 0
        snapshots.append(list(heights))
        best = max(best, largest_histogram_area(heights))
    for i in range(len(snapshots)):
        print("row %d heights: %s" % (i, snapshots[i]))
    return best


