def make_board(size):
    """Build a size x size matrix of zeros representing an empty board."""
    board = []
    for i in range(size):
        row = []
        for j in range(size):
            row.append(0)
        board.append(row)
    return board


def is_safe(board, row, col, size):
    """Check the column above and both upper diagonals for an attacking queen."""
    for i in range(row):
        if board[i][col]:
            return False
    for k in range(1, row + 1):
        left = col - k
        right = col + k
        if left >= 0 and board[row - k][left]:
            return False
        if right < size and board[row - k][right]:
            return False
    return True


def solve_util(board, row, size):
    """Place queens row by row, backtracking whenever a branch fails."""
    if row == size:
        return True
    for j in range(size):
        if is_safe(board, row, j, size):
            board[row][j] = 1
            if solve_util(board, row + 1, size):
                return True
            board[row][j] = 0
    return False


def format_board(board):
    """Turn the numeric board into one string per row."""
    lines = []
    for i in range(len(board)):
        cells = []
        for j in range(len(board[i])):
            cells.append("Q" if board[i][j] else ".")
        lines.append("".join(cells))
    return lines


def solve_n_queens(size):
    """Return one valid placement as a list of row strings, or None if impossible."""
    if not isinstance(size, int) or size < 1:
        raise ValueError("board size must be a positive integer")
    board = make_board(size)
    if not solve_util(board, 0, size):
        return None
    return format_board(board)


def main():
    for n in (1, 2, 4, 6, 8):
        print("N = %d" % n)
        solution = solve_n_queens(n)
        if solution is None:
            print("  no solution exists")
        else:
            for i in range(len(solution)):
                print("  %2d %s" % (i + 1, solution[i]))
        print()


if __name__ == "__main__":
    main()

