def is_strictly_diagonally_dominant(A):
    n = len(A)
    for i in range(n):
        off = 0.0
        for j in range(n):
            if j != i:
                off += abs(A[i][j])
        if abs(A[i][i]) <= off:
            return False
    return True


def matrix_vector_product(A, x):
    result = []
    for i in range(len(A)):
        total = 0.0
        for j in range(len(x)):
            total += A[i][j] * x[j]
        result.append(total)
    return result


def residuals(A, b, x):
    Ax = matrix_vector_product(A, x)
    errors = []
    for i in range(len(b)):
        errors.append(Ax[i] - b[i])
    return errors


def jacobi_solve(A, b, iterations):
    n = len(A)
    for i in range(n):
        if len(A[i]) != n:
            raise ValueError("A must be square")
    if len(b) != n:
        raise ValueError("b must have the same length as A")
    if not is_strictly_diagonally_dominant(A):
        raise ValueError("A is not strictly diagonally dominant")

    x = [0.0] * n
    for _ in range(iterations):
        new_x = [0.0] * n
        for i in range(n):
            total = b[i]
            for j in range(n):
                if j != i:
                    total -= A[i][j] * x[j]
            new_x[i] = total / A[i][i]
        x = new_x
    print("Completed %d Jacobi iterations." % iterations)

    errors = residuals(A, b, x)
    for i in range(n):
        print("Equation %d: residual = %+.3e" % (i + 1, errors[i]))
