def is_strictly_diagonally_dominant(A):
    n = len(A)
    for index in range(n):
        off = 0.0
        for column in range(n):
            if column != index:
                off += abs(A[index][column])
        if abs(A[index][index]) <= off:
            return False
    return True


def matrix_vector_product(A, x):
    result = []
    for index in range(len(A)):
        total = 0.0
        for column in range(len(x)):
            total += A[index][column] * x[column]
        result.append(total)
    return result


def residuals(A, b, x):
    Ax = matrix_vector_product(A, x)
    errors = []
    for index in range(len(b)):
        errors.append(Ax[index] - b[index])
    return errors


def jacobi_solve(A, b, iterations):
    n = len(A)
    for index in range(n):
        if len(A[index]) != n:
            raise ValueError("A must be square")
    if len(b) != n:
        raise ValueError("b must have the same length as A")
    if not is_strictly_diagonally_dominant(A):
        raise ValueError("A is not strictly diagonally dominant")

    x = [0.0] * n
    for _ in range(iterations):
        new_x = [0.0] * n
        for index in range(n):
            total = b[index]
            for column in range(n):
                if column != index:
                    total -= A[index][column] * x[column]
            new_x[index] = total / A[index][index]
        x = new_x
    print("Completed %d Jacobi iterations." % iterations)

    errors = residuals(A, b, x)
    for index in range(n):
        print("Equation %d: residual = %+.3e" % (index + 1, errors[index]))
    return x


def format_solution(x):
    parts = []
    for index in range(len(x)):
        parts.append("x%d = %.6f" % (index + 1, x[index]))
    return ", ".join(parts)


def main():
    A = [[4.0, -1.0, 0.0],
         [-1.0, 4.0, -1.0],
         [0.0, -1.0, 3.0]]
    b = [15.0, 10.0, 10.0]

