        coeffs = []
        for column in range(len(A[index])):
            coeffs.append("%+.1f*x%d" % (A[index][column], column + 1))
        print("  " + " ".join(coeffs) + " = %.1f" % b[index])

    solution = jacobi_solve(A, b, 25)
    print("Solution: " + format_solution(solution))


