def validate_pairs(pairs):
    """Check that every element is a 2-tuple of integers with first < second."""
    for i in range(len(pairs)):
        pair = pairs[i]
        if len(pair) != 2:
            raise ValueError("pair %d must have exactly two elements" % i)
        first, second = pair
        if not isinstance(first, int) or not isinstance(second, int):
            raise TypeError("pair %d must contain integers" % i)
        if first >= second:
            raise ValueError("pair %d must satisfy first < second" % i)


def sort_pairs(pairs):
    """Return the pairs ordered by their first element (insertion sort)."""
    ordered = list(pairs)
    for i in range(1, len(ordered)):
        current = ordered[i]
        j = i - 1
        while j >= 0 and ordered[j][0] > current[0]:
            ordered[j + 1] = ordered[j]
            j -= 1
        ordered[j + 1] = current
    return ordered


def max_chain_length(pairs):
    """Length of the longest chain where prev[1] < next[0]."""
    if not pairs:
        return 0
    validate_pairs(pairs)
    ordered = sort_pairs(pairs)
    total = len(ordered)
    dp = [1] * total
    for i in range(1, total):
        for j in range(i):
            if ordered[j][1] < ordered[i][0] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
    best = dp[0]
    for k in range(1, total):
        if dp[k] > best:
            best = dp[k]
    return best


def build_chain(pairs):
    """Recover one longest chain, using the same DP with parent links."""
    if not pairs:
        return []
    validate_pairs(pairs)
    ordered = sort_pairs(pairs)
    total = len(ordered)
    dp = [1] * total
    parent = [-1] * total
    for i in range(1, total):
        for j in range(i):
            if ordered[j][1] < ordered[i][0] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
                parent[i] = j
    end = 0
    for k in range(1, total):
        if dp[k] > dp[end]:
            end = k
    chain = []
    while end != -1:
        chain.append(ordered[end])
        end = parent[end]
    chain.reverse()
    return chain


def format_chain(chain):
    parts = []
    for n in range(len(chain)):
        parts.append("(%d, %d)" % chain[n])
    return " -> ".join(parts)


def main():
    datasets = [
        [(5, 24), (39, 60), (15, 28), (27, 40), (50, 90)],
        [(11, 20), (10, 40), (45, 60), (39, 40)],
    ]
    for n in range(len(datasets)):
        pairs = datasets[n]
        length = max_chain_length(pairs)
        chain = build_chain(pairs)
        print("dataset %d: %d pairs, max chain length %d" % (n, len(pairs), length))
        print("  chain: %s" % format_chain(chain))


if __name__ == "__main__":
    main()

