import math
import re


def tokenize(text):
    return re.findall(r"[a-z0-9']+", text.lower())


def build_vocabulary(tokenized_docs):
    terms = set()
    for i in range(len(tokenized_docs)):
        terms.update(tokenized_docs[i])
    return sorted(terms)


def document_frequencies(tokenized_docs, vocabulary):
    df = {}
    for j in range(len(vocabulary)):
        df[vocabulary[j]] = 0
    for i in range(len(tokenized_docs)):
        seen = set(tokenized_docs[i])
        for term in vocabulary:
            if term in seen:
                df[term] += 1
    return df


def term_counts(tokenized_docs):
    counts = []
    for i in range(len(tokenized_docs)):
        row = {}
        for token in tokenized_docs[i]:
            row[token] = row.get(token, 0) + 1
        counts.append(row)
    return counts


def compute_tfidf(documents):
    tokenized = [tokenize(doc) for doc in documents]
    vocabulary = build_vocabulary(tokenized)
    df = document_frequencies(tokenized, vocabulary)
    counts = term_counts(tokenized)
    d = len(documents)
    v = len(vocabulary)

    matrix = []
    for i in range(d):
        row = []
        for j in range(v):
            row.append(0.0)
        matrix.append(row)

    for i in range(d):
        length = len(tokenized[i]) or 1
        for j in range(v):
            term = vocabulary[j]
            tf = counts[i].get(term, 0) / length
            idf = math.log((1 + d) / (1 + df[term])) + 1.0
            matrix[i][j] = tf * idf

    for i in range(d):
        total = 0.0
        for k in range(v):
            total += matrix[i][k] ** 2
        norm = math.sqrt(total)
        if norm > 0.0:
            for k in range(v):
                matrix[i][k] /= norm

    return matrix


def report(documents):
    matrix = compute_tfidf(documents)
    vocabulary = build_vocabulary([tokenize(doc) for doc in documents])
    for i in range(len(matrix)):
        pairs = []
        for j in range(len(vocabulary)):
            if matrix[i][j] > 0.0:
                pairs.append((matrix[i][j], vocabulary[j]))
        pairs.sort(reverse=True)
        top = ", ".join("%s=%.3f" % (term, weight) for weight, term in pairs[:3])
        print("doc %d: %s" % (i, top))


if __name__ == "__main__":
    corpus = [
        "the cat sat on the mat",
        "the dog sat on the log",
        "cats and dogs are friends",
    ]
    report(corpus)

