def validate(art, horizontal, vertical):
    if not isinstance(art, list):
        raise TypeError("art must be a list of strings")
    for n, row in enumerate(art):
        if not isinstance(row, str):
            raise TypeError("row %d is not a string" % n)
    if horizontal < 1 or vertical < 1:
        raise ValueError("scaling factors must be at least 1")


def normalize(art):
    width = 0
    for row in art:
        if len(row) > width:
            width = len(row)
    rows = []
    for i in range(len(art)):
        rows.append(art[i].ljust(width))
    return rows


def scale(art, horizontal, vertical):
    validate(art, horizontal, vertical)
    result = []
    for row in art:
        stretched = []
        for j in range(len(row)):
            stretched.append(row[j] * horizontal)
        line = "".join(stretched)
        for k in range(vertical):
            result.append(line)
    return result


def frame(rows, corner="+", horizontal_edge="-", vertical_edge="|"):
    padded = normalize(rows)
    width = len(padded[0]) if padded else 0
    border = corner + horizontal_edge * width + corner
    framed = [border]
    for row in padded:
        framed.append(vertical_edge + row + vertical_edge)
    framed.append(border)
    return framed


def ink_report(rows, blank=" "):
    counts = []
    for i, row in enumerate(rows):
