def validate(documents, length):
    if not isinstance(length, int) or length < 1:
        raise ValueError("length must be a positive integer")
    for i, doc in enumerate(documents):
        if not isinstance(doc, list):
            raise TypeError("document %d is not a list of words" % i)
        for j, word in enumerate(doc):
            if not isinstance(word, str):
                raise TypeError("word %d of document %d is not a string" % (j, i))


def shingles(words, length):
    """Return the set of contiguous word sequences of the given length."""
    result = set()
    for i in range(len(words) - length + 1):
        result.add(tuple(words[i:i + length]))
    return result


def jaccard(left, right):
    union = left | right
    if not union:
        return 0.0
    return len(left & right) / len(union)


def plagiarism(documents, length):
    validate(documents, length)
    sets = [shingles(doc, length) for doc in documents]
    pairs = []
    for i in range(len(sets)):
        for j in range(i + 1, len(sets)):
            pairs.append((i, j, jaccard(sets[i], sets[j])))
    return pairs


def report(pairs, threshold=0.0):
    """Build human readable lines for pairs scoring at or above threshold."""
    lines = []
    for i, j, score in sorted(pairs, key=lambda p: (-p[2], p[0], p[1])):
        if score >= threshold:
            lines.append("doc %d vs doc %d : %.3f" % (i, j, score))
    if not lines:
        lines.append("no pairs above threshold %.3f" % threshold)
    return lines


def main():
    documents = [
