import sys


def dimension(square):
    """Return the side length of a well-formed square grid, or 0 otherwise."""
    n = len(square)
    for i in range(n):
        if len(square[i]) != n:
            return 0
    return n


def has_exact_numbers(square, n):
    """True when 1..n*n each appear exactly once in the grid."""
    seen = [False] * (n * n)
    for i in range(n):
        for j in range(n):
            value = square[i][j]
            if value < 1 or value > n * n or seen[value - 1]:
                return False
            seen[value - 1] = True
    return True


def row_sums(square, n):
    sums = []
    for i in range(n):
        total = 0
        for j in range(n):
            total += square[i][j]
        sums.append(total)
    return sums


def column_sums(square, n):
    sums = []
    for j in range(n):
        total = 0
        for i in range(n):
            total += square[i][j]
        sums.append(total)
    return sums


def diagonal_sums(square, n):
    main = 0
    anti = 0
    for i in range(n):
        main += square[i][i]
        anti += square[i][n - 1 - i]
    return [main, anti]


def verify(square):
    n = dimension(square)
    if n == 0 or not has_exact_numbers(square, n):
        return False
    target = sum(square[0])
    for total in row_sums(square, n) + column_sums(square, n) + diagonal_sums(square, n):
        if total != target:
            return False
    return True


def format_square(square):
    width = 1
    for row in square:
        for value in row:
            width = max(width, len(str(value)))
    lines = []
    for i in range(len(square)):
        cells = []
        for j in range(len(square[i])):
            cells.append(str(square[i][j]).rjust(width))
        lines.append(" ".join(cells))
    return "\n".join(lines)


def parse_squares(text):
    """Split blank-line separated blocks of whitespace-delimited integers."""
    squares = []
    for block in text.split("\n\n"):
        grid = []
        for line in block.splitlines():
            if line.strip():
                grid.append([int(token) for token in line.split()])
        if grid:
            squares.append(grid)
    return squares


