import sys


def parse_grid(text):
    """Turn whitespace-separated rows of '0'/'1' characters into a grid of ints."""
    rows = text.split()
    grid = []
    for i in range(len(rows)):
        row = []
        for j in range(len(rows[i])):
            c = rows[i][j]
            if c not in "01":
                raise ValueError("invalid character %r in row %d" % (c, i))
            row.append(int(c))
        grid.append(row)
    return grid


def validate_grid(grid):
    """Check that the grid is a non-empty rectangle holding only 0 and 1."""
    if not grid or not grid[0]:
        raise ValueError("grid must contain at least one cell")
    width = len(grid[0])
    for i in range(len(grid)):
        if len(grid[i]) != width:
            raise ValueError("row %d has length %d, expected %d" % (i, len(grid[i]), width))
        for j in range(width):
            if grid[i][j] not in (0, 1):
                raise ValueError("cell (%d, %d) is not 0 or 1" % (i, j))


def obstacle_positions(grid):
    """Collect the coordinates of every cell marked as an obstacle."""
    spots = []
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == 1:
                spots.append((i, j))
    return spots


def field(grid):
    """Return a grid of Manhattan distances from each cell to the nearest obstacle."""
    validate_grid(grid)
    spots = obstacle_positions(grid)
    if not spots:
        raise ValueError("grid contains no obstacles")
    distances = []
    for i in range(len(grid)):
        row = []
        for j in range(len(grid[i])):
            if grid[i][j] == 1:
                row.append(0)
                continue
            best = None
            for k in range(len(spots)):
                d = abs(i - spots[k][0]) + abs(j - spots[k][1])
                if best is None or d < best:
                    best = d
            row.append(best)
        distances.append(row)
    return distances


def format_field(distances):
    """Render a distance grid as right-aligned columns of equal width."""
    width = 1
    for i in range(len(distances)):
        for j in range(len(distances[i])):
            width = max(width, len(str(distances[i][j])))
    lines = []
    for i in range(len(distances)):
        cells = []
        for j in range(len(distances[i])):
            cells.append(str(distances[i][j]).rjust(width))
        lines.append(" ".join(cells))
    return "\n".join(lines)


def main():
    text = sys.stdin.read()
    if not text.strip():
        print("usage: pipe rows of 0/1 digits, one row per line", file=sys.stderr)
        return 1
    print(format_field(field(parse_grid(text))))
    return 0


if __name__ == "__main__":
    sys.exit(main())

