        if len(words[i]) > width:
            raise ValueError("word %r is longer than width %d" % (words[i], width))


def build_lines(words, width):
    """Greedily group words into lines that fit inside width."""
    lines = []
    current = []
    used = 0
    for i in range(len(words)):
        word = words[i]
        needed = len(word) if not current else used + 1 + len(word)
        if current and needed > width:
            lines.append(current)
            current = [word]
            used = len(word)
        else:
            current.append(word)
            used = needed
    if current:
        lines.append(current)
