def euclidean(a, b):
    """Euclidean distance between two equally sized coordinate vectors."""
    total = 0.0
    for i in range(len(a)):
        diff = a[i] - b[i]
        total += diff * diff
    return total ** 0.5


def validate(points, indices):
    """Check that the points share one dimension and the indices are usable."""
    if not points:
        raise ValueError("no data points given")
    dim = len(points[0])
    for n in range(len(points)):
        if len(points[n]) != dim:
            raise ValueError("point %d has %d coordinates, expected %d"
                             % (n, len(points[n]), dim))
    if not indices:
        raise ValueError("no medoid indices given")
    for k in indices:
        if k < 0 or k >= len(points):
            raise ValueError("medoid index %d out of range" % k)


def assign_clusters(points, indices):
    """Group every point index by the nearest medoid in `indices`."""
    clusters = [[] for k in indices]
    for i in range(len(points)):
        best = 0
        best_dist = euclidean(points[i], points[indices[0]])
        for j in range(1, len(indices)):
            d = euclidean(points[i], points[indices[j]])
            if d < best_dist:
                best_dist = d
                best = j
        clusters[best].append(i)
    return clusters


def best_member(points, members):
    """Index of the cluster member with the smallest sum of intra-cluster distances."""
    best = members[0]
    best_sum = None
    for i in members:
        total = 0.0
        for j in members:
            total += euclidean(points[i], points[j])
        if best_sum is None or total < best_sum:
            best_sum = total
            best = i
    return best


def medoids(points, indices):
    """One medoid-update step: reassign points, then re-centre each cluster."""
    validate(points, indices)
    clusters = assign_clusters(points, indices)
    updated = []
    for k in range(len(clusters)):
        if clusters[k]:
            updated.append(best_member(points, clusters[k]))
        else:
            updated.append(indices[k])
    return updated


def run(points, indices, max_steps=20):
    """Repeat the update step until the medoid set stops changing."""
    for n in range(max_steps):
        nxt = medoids(points, indices)
        if nxt == indices:
            return indices, n
        indices = nxt
    return indices, max_steps


def main():
    data = [[1.0, 1.0], [1.5, 2.0], [0.5, 0.8], [8.0, 8.0],
            [8.5, 7.5], [9.0, 8.2], [4.5, 4.4]]
    final, steps = run(data, [0, 3])
    print("converged after %d step(s)" % steps)
    clusters = assign_clusters(data, final)
    for k in range(len(final)):
        coords = ", ".join("%.2f" % v for v in data[final[k]])
        print("medoid %d -> point %d (%s)" % (k, final[k], coords))
        for i in clusters[k]:
            print("    point %d at distance %.3f"
                  % (i, euclidean(data[i], data[final[k]])))


if __name__ == "__main__":
    main()

