def validate_rectangles(rectangles):
    """Check that every entry is a 4-tuple of integers with min <= max."""
    for i in range(len(rectangles)):
        rect = rectangles[i]
        if len(rect) != 4:
            raise ValueError("rectangle %d must have four values" % i)
        for n in rect:
            if not isinstance(n, int):
                raise TypeError("rectangle %d contains a non-integer: %r" % (i, n))
        min_x, min_y, max_x, max_y = rect
        if max_x < min_x or max_y < min_y:
            raise ValueError("rectangle %d has inverted bounds" % i)


def bounds(rectangles):
    """Overall maximum x and maximum y across all rectangles."""
    max_x = 0
    max_y = 0
    for i in range(len(rectangles)):
        if rectangles[i][2] > max_x:
            max_x = rectangles[i][2]
        if rectangles[i][3] > max_y:
            max_y = rectangles[i][3]
    return max_x, max_y


def build_grid(rectangles):
    """Boolean grid from (0, 0) to the overall bounds, true where covered."""
    max_x, max_y = bounds(rectangles)
    grid = [[False] * max_x for j in range(max_y)]
    for min_x, min_y, top_x, top_y in rectangles:
        for j in range(min_y, top_y):
            for i in range(min_x, top_x):
                grid[j][i] = True
    return grid


def area(rectangles):
    """Total number of unit cells covered by the union of the rectangles."""
    validate_rectangles(rectangles)
    grid = build_grid(rectangles)
    total = 0
    for j in range(len(grid)):
        for i in range(len(grid[j])):
            if grid[j][i]:
                total += 1
    return total


def render(grid):
    """Text picture of the grid, topmost row first."""
    lines = []
    for j in range(len(grid) - 1, -1, -1):
        cells = []
        for i in range(len(grid[j])):
            cells.append('#' if grid[j][i] else '.')
        lines.append(''.join(cells))
    return lines


def main():
    datasets = [
        [(0, 0, 2, 2)],
        [(0, 0, 3, 2), (2, 1, 5, 4)],
        [(1, 1, 4, 3), (0, 0, 2, 2), (3, 0, 6, 1)],
    ]
    for k in range(len(datasets)):
        rectangles = datasets[k]
        print("dataset %d: %s" % (k + 1, rectangles))
        print("covered area: %d" % area(rectangles))
        lines = render(build_grid(rectangles))
        for n in range(len(lines)):
            print("  " + lines[n])


if __name__ == "__main__":
    main()

