import sys


def validate_image(image):
    """Check that the image is a non-empty rectangular grid of numbers."""
    if not image or not image[0]:
        raise ValueError("image must contain at least one pixel")
    width = len(image[0])
    for i in range(len(image)):
        row = image[i]
        if len(row) != width:
            raise ValueError("row %d has length %d, expected %d" % (i, len(row), width))
        for j in range(width):
            if not isinstance(row[j], (int, float)) or isinstance(row[j], bool):
                raise ValueError("pixel (%d, %d) is not a number" % (i, j))
    return len(image), width


def block_max(image, top, left, size):
    """Maximum value of the size x size block anchored at (top, left)."""
    best = image[top][left]
    for i in range(top, top + size):
        for j in range(left, left + size):
            if image[i][j] > best:
                best = image[i][j]
    return best


def pool(image, size):
    """Max-pool the image with non-overlapping size x size blocks."""
    height, width = validate_image(image)
    if not isinstance(size, int) or size < 1:
        raise ValueError("size must be a positive integer")
    pooled = []
    for i in range(height // size):
        row = []
        for j in range(width // size):
            row.append(float(block_max(image, i * size, j * size, size)))
        pooled.append(row)
    return pooled


def parse_image(text):
    """Read a whitespace-separated grid of numbers, ignoring blank lines."""
    image = []
    lines = text.splitlines()
    for i in range(len(lines)):
        fields = lines[i].split()
        if not fields:
            continue
        row = []
        for j in range(len(fields)):
            try:
                row.append(float(fields[j]))
            except ValueError:
                raise ValueError("line %d, field %d is not a number" % (i + 1, j + 1))
        image.append(row)
    return image


def format_image(image, digits=2):
    """Render a grid as aligned text lines."""
    cells = []
    widest = 0
    for i in range(len(image)):
        row = []
        for j in range(len(image[i])):
            text = "%.*f" % (digits, image[i][j])
            if len(text) > widest:
                widest = len(text)
            row.append(text)
        cells.append(row)
    lines = []
    for i in range(len(cells)):
        lines.append(" ".join(text.rjust(widest) for text in cells[i]))
    return "\n".join(lines)


def main(argv):
    size = int(argv[1]) if len(argv) > 1 else 2
    image = parse_image(sys.stdin.read())
    pooled = pool(image, size)
    print("pooled with size %d -> %dx%d:" % (size, len(pooled), len(pooled[0])))
    print(format_image(pooled))


if __name__ == "__main__":
    main(sys.argv)

