def parse_grid(lines):
    """Turn a list of equal-length strings into a two-dimensional list of characters."""
    grid = []
    for i in range(len(lines)):
        row = list(lines[i])
        if len(row) != len(lines[0]):
            raise ValueError("row %d has length %d, expected %d"
                             % (i, len(row), len(lines[0])))
        grid.append(row)
    return grid


def count_mismatches(text, pattern, row, col):
    """Number of characters of the pattern that differ from the text at (row, col)."""
    mismatches = 0
    for i in range(len(pattern)):
        for j in range(len(pattern[i])):
            if pattern[i][j] != text[row + i][col + j]:
                mismatches += 1
    return mismatches


def match(text, pattern, tolerance):
    """All (row, col) positions where the pattern fits with at most `tolerance` differences."""
    if not pattern or not pattern[0]:
        return []
    height = len(pattern)
    width = len(pattern[0])
    matches = []
    for i in range(len(text) - height + 1):
        for j in range(len(text[i]) - width + 1):
            if count_mismatches(text, pattern, i, j) <= tolerance:
                matches.append((i, j))
    return matches


def render_matches(text, pattern, matches):
    """Copy of the text grid with matched regions upper-cased."""
    marked = []
    for i in range(len(text)):
        marked.append([c.lower() for c in text[i]])
    for row, col in matches:
        for i in range(len(pattern)):
            for j in range(len(pattern[i])):
                marked[row + i][col + j] = marked[row + i][col + j].upper()
    return ["".join(row) for row in marked]


def main():
    text = parse_grid([
        "abcdefgh",
        "ijklmnop",
        "qrstuvwx",
        "abcdefgh",
        "ijklmnop",
    ])
    pattern = parse_grid([
        "bcd",
        "jkl",
    ])

    for n in range(3):
        found = match(text, pattern, n)
        print("tolerance %d -> %d match(es)" % (n, len(found)))
        for k in range(len(found)):
            print("  #%d at row %d, column %d" % (k + 1, found[k][0], found[k][1]))
        for line in render_matches(text, pattern, found):
            print("  " + line)


if __name__ == "__main__":
    main()

