from collections import deque


def validate(matrix):
    n = len(matrix)
    for i in range(n):
        if len(matrix[i]) != n:
            raise ValueError("row %d has %d entries, expected %d" % (i, len(matrix[i]), n))
    for i in range(n):
        for j in range(i + 1, n):
            if matrix[i][j] != matrix[j][i]:
                raise ValueError("matrix is not symmetric at (%d, %d)" % (i, j))
    return n


def components(matrix):
    n = validate(matrix)
    explored = [False] * n
    result = []
    for i in range(n):
        if explored[i]:
            continue
        explored[i] = True
        queue = deque([i])
        component = []
        while queue:
            node = queue.popleft()
            component.append(node)
            for j in range(n):
                if matrix[node][j] and not explored[j]:
                    explored[j] = True
                    queue.append(j)
        result.append(sorted(component))
    return result


def degrees(matrix):
    n = len(matrix)
    counts = []
    for i in range(n):
        total = 0
        for j in range(n):
            total += matrix[i][j]
        counts.append(total)
    return counts


def report(matrix, title, labels=None):
    comps = components(matrix)
    deg = degrees(matrix)
    lines = ["%s: %d node(s), %d component(s)" % (title, len(matrix), len(comps))]
    for i in range(len(comps)):
        names = []
        for k in comps[i]:
            name = labels[k] if labels else str(k)
            names.append("%s(deg %d)" % (name, deg[k]))
        lines.append("  component %d: %s" % (i + 1, ", ".join(names)))
    return "\n".join(lines)


