def _is_hole(row, col, order):
    """Return True when the cell at (row, col) lies in a removed sub-square."""
    for k in range(order):
        if row % 3 == 1 and col % 3 == 1:
            return True
        row //= 3
        col //= 3
    return False


def carpet(order):
    """Build a Sierpinski carpet of the given order as a list of strings."""
    if not isinstance(order, int) or isinstance(order, bool):
        raise TypeError("order must be an integer")
    if order < 0:
        raise ValueError("order must be non-negative")
    size = 3 ** order
    grid = []
    for i in range(size):
        row = ['#'] * size
        for j in range(size):
            if _is_hole(i, j, order):
                row[j] = ' '
        grid.append(''.join(row))
    return grid


def count_filled(rows):
    """Count the hash symbols in the carpet."""
    total = 0
    for i in range(len(rows)):
        for j in range(len(rows[i])):
            if rows[i][j] == '#':
                total += 1
    return total


def column_profile(rows):
    """Number of filled cells in each column, left to right."""
    width = len(rows[0]) if rows else 0
    profile = [0] * width
    for j in range(width):
        for i in range(len(rows)):
            if rows[i][j] == '#':
                profile[j] += 1
    return profile


def framed(rows):
    """Wrap the carpet in an ASCII frame for display."""
    width = len(rows[0]) if rows else 0
    edge = '+' + '-' * width + '+'
    out = [edge]
    for n in range(len(rows)):
        out.append('|' + rows[n] + '|')
    out.append(edge)
    return out


def main():
    for n in range(4):
        rows = carpet(n)
        print("order {0} ({1}x{1})".format(n, len(rows)))
        for line in framed(rows):
            print(line)
        profile = column_profile(rows)
        widest = 0
        for j in range(len(profile)):
            if profile[j] > profile[widest]:
                widest = j
        print("filled cells: %d, densest column: %d (%d cells)"
              % (count_filled(rows), widest, profile[widest]))
        print()


if __name__ == '__main__':
    main()

