UNREVEALED = -1
MINE = -2
SAFE = -3


def validate(board):
    if not board:
        raise ValueError("board must contain at least one row")
    width = len(board[0])
    for i in range(len(board)):
        if len(board[i]) != width:
            raise ValueError("row %d has inconsistent width" % i)
        for j in range(width):
            value = board[i][j]
            if value < SAFE or value > 8:
                raise ValueError("cell (%d,%d) holds invalid value %d" % (i, j, value))
    return width


def neighbors(board, row, col):
    cells = []
    for i in range(row - 1, row + 2):
        if not 0 <= i < len(board):
            continue
        for j in range(col - 1, col + 2):
            if i == row and j == col:
                continue
            if 0 <= j < len(board[i]):
                cells.append((i, j))
    return cells


def unrevealed_neighbors(board, row, col):
    hidden = []
    for nrow, ncol in neighbors(board, row, col):
        if board[nrow][ncol] == UNREVEALED:
            hidden.append((nrow, ncol))
    return hidden


def count_flagged(board, row, col):
    total = 0
    for nrow, ncol in neighbors(board, row, col):
        if board[nrow][ncol] == MINE:
            total += 1
    return total


def deduce(board):
    changed = True
    while changed:
        changed = False
        for i in range(len(board)):
            for j in range(len(board[i])):
                number = board[i][j]
                if number < 0:
                    continue
                hidden = unrevealed_neighbors(board, i, j)
                if not hidden:
                    continue
                flagged = count_flagged(board, i, j)
                if len(hidden) == number - flagged:
                    for nrow, ncol in hidden:
                        board[nrow][ncol] = MINE
                    changed = True
                elif number == flagged:
                    for nrow, ncol in hidden:
                        board[nrow][ncol] = SAFE
                    changed = True
    return board


def render(board):
    symbols = {MINE: "*", SAFE: ".", UNREVEALED: "?"}
    lines = []
    for i in range(len(board)):
        cells = []
        for j in range(len(board[i])):
            value = board[i][j]
            cells.append(symbols.get(value, str(value)))
        lines.append(" ".join(cells))
    return "\n".join(lines)


def tally(board):
    counts = {"mines": 0, "safe": 0, "unknown": 0}
    labels = {MINE: "mines", SAFE: "safe", UNREVEALED: "unknown"}
    for i in range(len(board)):
        for j in range(len(board[i])):
            label = labels.get(board[i][j])
            if label:
                counts[label] += 1
    return counts


def main():
    board = [
        [1, -1, -1, -1],
        [1, 2, 2, 1],
        [0, 0, -1, -1],
        [0, 1, -1, -1],
    ]
    validate(board)
    print("before:")
    print(render(board))
    deduce(board)
    print("after:")
    print(render(board))
    counts = tally(board)
    print("mines=%d safe=%d unknown=%d" % (counts["mines"], counts["safe"], counts["unknown"]))


if __name__ == "__main__":
    main()

