def validate_boxes(boxes):
    if not boxes:
        raise ValueError("at least one bounding box is required")
    for i, box in enumerate(boxes):
        if len(box) != 4:
            raise ValueError("box %d must have four numbers" % i)
        for j in range(4):
            if not isinstance(box[j], (int, float)):
                raise TypeError("box %d contains a non numeric value" % i)
        if box[2] < 0 or box[3] < 0:
            raise ValueError("box %d has negative width or height" % i)


def intersection_area(a, b):
    left = max(a[0], b[0])
    top = max(a[1], b[1])
    right = min(a[0] + a[2], b[0] + b[2])
    bottom = min(a[1] + a[3], b[1] + b[3])
    if right <= left or bottom <= top:
        return 0.0
    return float((right - left) * (bottom - top))


def iou(a, b):
    inter = intersection_area(a, b)
    union = float(a[2] * a[3] + b[2] * b[3]) - inter
    if union <= 0.0:
        return 0.0
    return inter / union


def build_iou_grid(boxes):
    count = len(boxes)
    grid = [[0.0] * count for _ in range(count)]
    for i in range(count):
        grid[i][i] = 1.0
        for j in range(i + 1, count):
            ratio = iou(boxes[i], boxes[j])
            grid[i][j] = ratio
            grid[j][i] = ratio
    return grid


def max_overlaps(boxes):
    validate_boxes(boxes)
    grid = build_iou_grid(boxes)
    count = len(grid)
    result = []
    for i in range(count):
        best = 0.0
        for j in range(count):
            if j != i and grid[i][j] > best:
                best = grid[i][j]
        result.append(round(best, 6))
    return result


def report_lines(boxes, ratios):
    lines = []
    for i, box in enumerate(boxes):
        coords = " ".join("%g" % box[k] for k in range(4))
        lines.append("box %d [%s] -> %.6f" % (i, coords, ratios[i]))
    return lines


def main():
    samples = [
        [[0, 0, 10, 10], [5, 5, 10, 10]],
        [[0, 0, 4, 4], [10, 10, 2, 2], [1, 1, 4, 4], [3, 3, 8, 8]],
    ]
    for n, boxes in enumerate(samples):
        ratios = max_overlaps(boxes)
        print("sample %d: %s" % (n, ratios))
        for line in report_lines(boxes, ratios):
            print(line)


if __name__ == "__main__":
    main()

