import sys
from string import ascii_uppercase


def normalize_key(key):
    """Return the unique letters of *key* in order, with J folded onto I."""
    letters = []
    for i in range(len(key)):
        c = key[i]
        if c not in ascii_uppercase:
            raise ValueError("key must contain only uppercase letters, got %r" % c)
        if c == "J":
            c = "I"
        if c not in letters:
            letters.append(c)
    return letters


def playfair_square(key):
    """Build the 5x5 Playfair square for *key* as a list of five strings."""
    letters = normalize_key(key)
    for letter in ascii_uppercase:
        if letter == "J":
            continue
        if letter not in letters:
            letters.append(letter)

    grid = [[""] * 5 for _ in range(5)]
    for i in range(5):
        for j in range(5):
            grid[i][j] = letters[i * 5 + j]

    rows = []
    for i in range(5):
        rows.append("".join(grid[i]))
    return rows


def locate(square, letter):
    """Return the (row, column) of *letter* inside *square*."""
    if letter == "J":
        letter = "I"
    for i in range(5):
        for j in range(5):
            if square[i][j] == letter:
                return i, j
    raise ValueError("letter %r is not part of the square" % letter)


def format_square(square):
    """Render the square as printable lines with spaced-out letters."""
    lines = []
    for i in range(5):
        lines.append(" ".join(square[i]))
    return lines


def main(argv):
    if len(argv) != 2:
        print("usage: %s KEY" % argv[0])
        return 1

    key = argv[1]
    square = playfair_square(key)
    for line in format_square(square):
        print(line)

    print()
    print("positions of the key letters:")
    for letter in key:
        row, col = locate(square, letter)
        print("  %s -> row %d, column %d" % (letter, row + 1, col + 1))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

