def center_of_mass(grid):
    """Return [depth, row, col] averages of all cells holding mass."""
    depth_sum = 0
    row_sum = 0
    col_sum = 0
    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            for k in range(len(grid[i][j])):
                if grid[i][j][k] == 1:
                    depth_sum += i
                    row_sum += j
                    col_sum += k
                    count += 1
    if count == 0:
