def quantize(value):
    """Map a grayscale value to the nearest of the two available tones."""
    return 0 if value < 128 else 255


def validate_image(image):
    """Check that the image is a non-empty rectangular grid of 0..255 integers."""
    if not isinstance(image, list) or not image:
        raise ValueError("image must be a non-empty list of rows")
    for i in range(len(image)):
        row = image[i]
        if not isinstance(row, list) or not row:
            raise ValueError("row %d must be a non-empty list" % i)
        if len(row) != len(image[0]):
            raise ValueError("row %d has inconsistent width" % i)
        for j in range(len(row)):
            pixel = row[j]
            if not isinstance(pixel, int) or isinstance(pixel, bool):
                raise ValueError("pixel (%d, %d) is not an integer" % (i, j))
            if pixel < 0 or pixel > 255:
                raise ValueError("pixel (%d, %d) is out of range" % (i, j))
    return len(image), len(image[0])


def dither(image):
    """Apply simplified error diffusion dithering in place and return the image."""
    height, width = validate_image(image)
    for i in range(height):
        for j in range(width):
            original = image[i][j]
            new_value = quantize(original)
            image[i][j] = new_value
            half = (original - new_value) // 2
            if j + 1 < width:
                image[i][j + 1] += half
            if i + 1 < height:
                image[i + 1][j] += half
    return image


def format_image(image):
    """Render the grid as right-aligned columns of numbers."""
    lines = []
    for i in range(len(image)):
        cells = []
        for j in range(len(image[i])):
            cells.append("%4d" % image[i][j])
        lines.append("".join(cells))
    return "\n".join(lines)


def main():
    samples = [
        [[130, 50], [60, 200]],
        [[10, 240, 130], [200, 120, 35], [90, 160, 250]],
        [[128]],
    ]
    for k in range(len(samples)):
        source = samples[k]
        print("image %d, before:" % k)
        print(format_image(source))
        print("image %d, after:" % k)
        print(format_image(dither(source)))
        print()


if __name__ == "__main__":
    main()

