def validate_image(image):
    if not image:
        raise ValueError("image must contain at least one row")
    width = len(image[0])
    for i in range(len(image)):
        row = image[i]
        if len(row) != width:
            raise ValueError("row %d has length %d, expected %d" % (i, len(row), width))
        for j in range(width):
            if not isinstance(row[j], int) or isinstance(row[j], bool):
                raise TypeError("pixel (%d, %d) is not an integer" % (i, j))
    if len(image) % 2 or width % 2:
        raise ValueError("image dimensions must be even to form 2x2 blocks")
    return len(image), width


def bin_index(angle):
    return (angle % 360) // 90


def block_histogram(image, row, col):
    bins = [0, 0, 0, 0]
    for k in range(2):
        for n in range(2):
            bins[bin_index(image[row + k][col + n])] += 1
    return bins


def histogram_blocks(image):
    height, width = validate_image(image)
    blocks = []
    for i in range(0, height, 2):
        block_row = []
        for j in range(0, width, 2):
            block_row.append(block_histogram(image, i, j))
        blocks.append(block_row)
    return blocks


def dominant_bin(bins):
    best = 0
    for k in range(1, len(bins)):
        if bins[k] > bins[best]:
            best = k
    return best


def format_report(blocks):
    labels = ["0-89", "90-179", "180-269", "270-359"]
    lines = []
    for i in range(len(blocks)):
        for j in range(len(blocks[i])):
            bins = blocks[i][j]
            counts = " ".join("%s=%d" % (labels[k], bins[k]) for k in range(len(bins)))
            lines.append("block (%d,%d): %s -> dominant %s"
                         % (i, j, counts, labels[dominant_bin(bins)]))
    return lines


def main():
