EMPTY, BLACK, WHITE = 0, 1, 2
SIZE = 8
SYMBOLS = {EMPTY: ".", BLACK: "B", WHITE: "W"}


def build_directions():
    dirs = []
    for i in (-1, 0, 1):
        for j in (-1, 0, 1):
            if i != 0 or j != 0:
                dirs.append((i, j))
    return dirs


DIRECTIONS = build_directions()


def validate_board(board):
    if len(board) != SIZE:
        raise ValueError("board must have %d rows" % SIZE)
    for i in range(SIZE):
        if len(board[i]) != SIZE:
            raise ValueError("row %d must have %d columns" % (i, SIZE))
        for j in range(SIZE):
            if board[i][j] not in SYMBOLS:
                raise ValueError("bad value %r at %d,%d" % (board[i][j], i, j))


def captures_in_direction(board, row, col, delta_row, delta_col, player):
    opponent = WHITE if player == BLACK else BLACK
    captured = []
    step_row, step_col = row + delta_row, col + delta_col
    while 0 <= step_row < SIZE and 0 <= step_col < SIZE and board[step_row][step_col] == opponent:
        captured.append((step_row, step_col))
        step_row += delta_row
        step_col += delta_col
    inside = 0 <= step_row < SIZE and 0 <= step_col < SIZE
    if captured and inside and board[step_row][step_col] == player:
        return captured
    return []


def captured_by_move(board, row, col, player=BLACK):
    if board[row][col] != EMPTY:
        return []
    captured = []
    for delta_row, delta_col in DIRECTIONS:
        captured.extend(captures_in_direction(board, row, col, delta_row, delta_col, player))
    return captured


def find_valid_moves(board, player=BLACK):
    validate_board(board)
    moves = []
    for i in range(SIZE):
        for j in range(SIZE):
            if captured_by_move(board, i, j, player):
                moves.append([i, j])
    return moves


def apply_move(board, move, player=BLACK):
    row, col = move
    captured = captured_by_move(board, row, col, player)
    if not captured:
        raise ValueError("invalid move %r" % (move,))
    new_board = [list(row_values) for row_values in board]
    new_board[row][col] = player
    for flip_row, flip_col in captured:
        new_board[flip_row][flip_col] = player
    return new_board


def format_board(board):
    lines = []
    for i in range(SIZE):
        cells = []
        for j in range(SIZE):
            cells.append(SYMBOLS[board[i][j]])
        lines.append("%d %s" % (i, " ".join(cells)))
    return "\n".join(lines)


def count_pieces(board):
    counts = {EMPTY: 0, BLACK: 0, WHITE: 0}
    for i in range(SIZE):
        for j in range(SIZE):
            counts[board[i][j]] += 1
    return counts


def main():
    board = []
    for i in range(SIZE):
        board.append([EMPTY] * SIZE)
    board[3][3] = WHITE
    board[3][4] = BLACK
    board[4][3] = BLACK
    board[4][4] = WHITE

    moves = find_valid_moves(board, BLACK)
    print(format_board(board))
    print("valid black moves:", moves)
    for number, move in enumerate(moves, 1):
        print("  %d) row %d, col %d" % (number, move[0], move[1]))

    played = apply_move(board, moves[0], BLACK)
    counts = count_pieces(played)
    print("after playing %r:" % (moves[0],))
    print(format_board(played))
    print("black %d, white %d, empty %d" % (counts[BLACK], counts[WHITE], counts[EMPTY]))


if __name__ == "__main__":
    main()

