def validate_grid(grid):
    """Check that grid is a square matrix whose dimension is a multiple of two."""
    size = len(grid)
    if size == 0 or size % 2 != 0:
        raise ValueError("grid dimension must be a positive multiple of two")
    for i in range(size):
        if len(grid[i]) != size:
            raise ValueError("row %d has length %d, expected %d" % (i, len(grid[i]), size))
    return size


def block_transpose(grid):
    """Return a new grid with its two by two blocks transposed."""
    size = validate_grid(grid)
    result = [[0] * size for i in range(size)]
    for i in range(0, size, 2):
        for j in range(0, size, 2):
            for k in range(2):
                for n in range(2):
                    result[j + k][i + n] = grid[i + k][j + n]
    return result


def cell_width(grid):
    """Width of the widest rendered entry in the grid."""
    width = 0
    for row in grid:
        for value in row:
            text = str(value)
            if len(text) > width:
                width = len(text)
    return width


def format_grid(grid, title):
    """Render a grid as a list of text lines, gapping the two by two blocks."""
    width = cell_width(grid)
    lines = [title]
    for i in range(len(grid)):
        parts = []
        for j in range(len(grid[i])):
            if j > 0 and j % 2 == 0:
                parts.append("  ")
            parts.append(str(grid[i][j]).rjust(width))
        lines.append(" ".join(parts))
        if i % 2 == 1 and i + 1 < len(grid):
            lines.append("")
    return lines


def build_sequential_grid(size):
    """Build a size by size grid filled with 1..size*size in reading order."""
    grid = []
    for i in range(size):
        row = []
        for j in range(size):
            row.append(i * size + j + 1)
        grid.append(row)
    return grid


def main():
    for n in (4, 6):
        original = build_sequential_grid(n)
        transposed = block_transpose(original)
        report = format_grid(original, "original %dx%d:" % (n, n))
        report.append("")
        report.extend(format_grid(transposed, "block transposed:"))
        report.append("")
