def validate_image(image):
    """Check that the image is a rectangular, non-empty grid of integers."""
    if not image:
        raise ValueError("image must contain at least one row")
    width = len(image[0])
    if width == 0:
        raise ValueError("image rows must not be empty")
    for i in range(len(image)):
        row = image[i]
        if len(row) != width:
            raise ValueError("row %d has length %d, expected %d" % (i, len(row), width))
        for j in range(width):
            if not isinstance(row[j], int) or isinstance(row[j], bool):
                raise ValueError("pixel at (%d, %d) is not an integer" % (i, j))
    return len(image), width


def extract_patches(args):
    """Return all non-overlapping patch_height x patch_width patches of an image."""
    image, patch_height, patch_width = args
    rows, cols = validate_image(image)
    if patch_height <= 0 or patch_width <= 0:
        raise ValueError("patch dimensions must be positive")
    patches = []
    for i in range(0, rows, patch_height):
        for j in range(0, cols, patch_width):
            if i + patch_height > rows or j + patch_width > cols:
                continue
            patch = []
            for k in range(patch_height):
                line = []
                for n in range(patch_width):
                    line.append(image[i + k][j + n])
                patch.append(line)
            patches.append(patch)
    return patches


def patch_sums(patches):
    """Return the sum of the pixel values of each patch."""
    sums = []
    for i in range(len(patches)):
        total = 0
        for row in patches[i]:
            for j in range(len(row)):
                total += row[j]
        sums.append(total)
    return sums


def format_patch(patch):
    """Render a patch as aligned text lines."""
    widest = 0
    for row in patch:
        for k in range(len(row)):
            widest = max(widest, len(str(row[k])))
    lines = []
    for n in range(len(patch)):
        cells = [str(value).rjust(widest) for value in patch[n]]
        lines.append("| " + " ".join(cells) + " |")
    return lines


def report(args):
    """Print every extracted patch together with its index and pixel sum."""
    patches = extract_patches(args)
    sums = patch_sums(patches)
    print("extracted %d patch(es)" % len(patches))
    for i in range(len(patches)):
        print("patch %d (sum=%d)" % (i, sums[i]))
        for line in format_patch(patches[i]):
            print("  " + line)
    return patches


def main():
    print(extract_patches([[[1, 2, 3], [4, 5, 6], [7, 8, 9]], 2, 2]))
    big = [[i * 10 + j for j in range(6)] for i in range(4)]
    report([big, 2, 3])


if __name__ == "__main__":
    main()

