import sys


def parse_signal(text):
    """Turn a whitespace- or comma-separated string into a list of floats."""
    tokens = text.replace(",", " ").split()
    signal = []
    for i in range(len(tokens)):
        try:
            signal.append(float(tokens[i]))
        except ValueError:
            raise ValueError("token %d is not a number: %r" % (i, tokens[i]))
    if not signal:
        raise ValueError("signal is empty")
    return signal


def raw_autocorrelation(signal):
    """Unnormalized autocorrelation for lags 0 .. len(signal)-1."""
    n = len(signal)
    result = []
    for i in range(n):
        total = 0.0
        for j in range(n - i):
            total += signal[j] * signal[j + i]
        result.append(total)
    return result


def normalize(values):
    """Divide every element by the zero-lag element."""
    zero_lag = values[0]
    if zero_lag == 0.0:
        raise ZeroDivisionError("zero-lag autocorrelation is 0; signal is all zeros")
    for i in range(len(values)):
        values[i] = values[i] / zero_lag
    return values


def autocorrelation(signal):
    """Normalized autocorrelation sequence of a 1-D signal."""
    return normalize(raw_autocorrelation(signal))


def dominant_lags(values, threshold):
    """Lags (excluding zero) whose normalized correlation reaches threshold."""
    lags = []
    for k in range(1, len(values)):
        if values[k] >= threshold:
            lags.append(k)
    return lags


def format_report(signal, values):
    lines = ["signal length: %d" % len(signal)]
    for i in range(len(values)):
        bar = ("#" if values[i] >= 0.0 else "-") * int(round(abs(values[i]) * 30))
        lines.append("lag %3d  %9.6f  %s" % (i, values[i], bar))
    peaks = dominant_lags(values, 0.5)
    if peaks:
        lines.append("strong lags: " + ", ".join(str(k) for k in peaks))
    return "\n".join(lines)


def main():
    if len(sys.argv) > 1:
        text = " ".join(sys.argv[1:])
    else:
        text = sys.stdin.read()
    signal = parse_signal(text)
    print(format_report(signal, autocorrelation(signal)))


if __name__ == "__main__":
    main()

