def unique_characters(sequences):
    """Return the sorted list of distinct uppercase letters in all sequences."""
    seen = set()
    for i in range(len(sequences)):
        for j in range(len(sequences[i])):
            seen.add(sequences[i][j])
    return sorted(seen)


def validate(sequences):
    """Reject anything that is not a sequence of uppercase letters."""
    for i in range(len(sequences)):
        item = sequences[i]
        if not isinstance(item, str):
            raise TypeError("sequence %d is not a string" % i)
        for j in range(len(item)):
            if not ("A" <= item[j] <= "Z"):
                raise ValueError("sequence %d contains %r" % (i, item[j]))


def transition_matrix(sequences):
    """Build [sorted unique characters, matrix of character-pair counts]."""
    validate(sequences)
    letters = unique_characters(sequences)
    size = len(letters)
    matrix = []
    for i in range(size):
        matrix.append([0] * size)
    for i in range(len(sequences)):
        seq = sequences[i]
        for j in range(len(seq) - 1):
            row = letters.index(seq[j])
            col = letters.index(seq[j + 1])
            matrix[row][col] += 1
    return [letters, matrix]


def format_matrix(letters, matrix):
    """Render the matrix as a labelled text table."""
    width = 1
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            width = max(width, len(str(matrix[i][j])))
    header = "   "
    for j in range(len(letters)):
        header += " " + letters[j].rjust(width)
    lines = [header]
    for i in range(len(matrix)):
        line = letters[i].ljust(3)
        for j in range(len(matrix[i])):
            line += " " + str(matrix[i][j]).rjust(width)
        lines.append(line)
    return "\n".join(lines)


def row_totals(matrix):
    """Total number of transitions leaving each character."""
    totals = []
    for i in range(len(matrix)):
        total = 0
        for k in range(len(matrix[i])):
            total += matrix[i][k]
        totals.append(total)
    return totals


def main():
    datasets = [["ABA", "BCA"], ["AAB", "BBA", "CAB"]]
    for k in range(len(datasets)):
        letters, matrix = transition_matrix(datasets[k])
        print("input %d: %s" % (k, datasets[k]))
        print([letters, matrix])
        print(format_matrix(letters, matrix))
        totals = row_totals(matrix)
        for i in range(len(letters)):
            print("%s -> %d transitions" % (letters[i], totals[i]))
        print()


if __name__ == "__main__":
    main()

