import sys

THRESHOLD = 2.0


def parse_points(text):
    """Parse one point per line, coordinates separated by spaces or commas."""
    points = []
    for line in text.splitlines():
        fields = line.replace(",", " ").split()
        if not fields:
            continue
        coords = []
        for k in range(len(fields)):
            coords.append(float(fields[k]))
        points.append(coords)
    return points


def validate_points(points):
    """Return the points as floats, raising ValueError on malformed input."""
    cleaned = []
    for i in range(len(points)):
        point = points[i]
        if len(point) != 2:
            raise ValueError("point %d must have exactly two coordinates" % i)
        cleaned.append([float(point[0]), float(point[1])])
    return cleaned


def build_adjacency_matrix(points):
    """Square boolean matrix: True where two points are within THRESHOLD."""
    limit = THRESHOLD * THRESHOLD
    n = len(points)
    matrix = []
    for i in range(n):
        row = []
        for j in range(n):
            dx = points[i][0] - points[j][0]
            dy = points[i][1] - points[j][1]
            row.append(dx * dx + dy * dy <= limit)
        matrix.append(row)
    return matrix


def compute_degrees(matrix):
    """Count the True entries of every row of the matrix."""
    degrees = []
    for i in range(len(matrix)):
        degree = 0
        for j in range(len(matrix[i])):
            if matrix[i][j]:
                degree += 1
        degrees.append(degree)
    return degrees


def adjacency(points):
    """Return [boolean adjacency matrix, list of degrees] for the points."""
    cleaned = validate_points(points)
    matrix = build_adjacency_matrix(cleaned)
    return [matrix, compute_degrees(matrix)]


def format_report(points, matrix, degrees):
    """Human readable summary of the network, one line per point."""
    lines = []
    for i in range(len(points)):
        neighbours = []
        for j in range(len(matrix[i])):
            if matrix[i][j] and j != i:
                neighbours.append(str(j))
        lines.append(
            "%d (%.1f, %.1f) degree=%d neighbours: %s"
            % (i, points[i][0], points[i][1], degrees[i], ", ".join(neighbours) or "none")
        )
    return "\n".join(lines)


def main():
    points = parse_points(sys.stdin.read())
    matrix, degrees = adjacency(points)
    print(format_report(points, matrix, degrees))
    print([matrix, degrees])


if __name__ == "__main__":
    main()

