        if len(point) != 2:
            raise ValueError("point %d must have exactly two coordinates" % index)
        cleaned.append([float(point[0]), float(point[1])])
    return cleaned


def build_adjacency_matrix(points):
    """Square boolean matrix: True where two points are within THRESHOLD."""
    limit = THRESHOLD * THRESHOLD
    n = len(points)
    matrix = []
    for index in range(n):
        row = []
        for column in range(n):
            dx = points[index][0] - points[column][0]
            dy = points[index][1] - points[column][1]
            row.append(dx * dx + dy * dy <= limit)
        matrix.append(row)
    return matrix


def compute_degrees(matrix):
    """Count the True entries of every row of the matrix."""
    degrees = []
    for index in range(len(matrix)):
        degree = 0
        for column in range(len(matrix[index])):
            if matrix[index][column]:
                degree += 1
        degrees.append(degree)
    return degrees


def adjacency(points):
    """Return [boolean adjacency matrix, list of degrees] for the points."""
    cleaned = validate_points(points)
    matrix = build_adjacency_matrix(cleaned)
    return [matrix, compute_degrees(matrix)]


def format_report(points, matrix, degrees):
    """Human readable summary of the network, one line per point."""
    lines = []
    for index in range(len(points)):
        neighbours = []
        for column in range(len(matrix[index])):
            if matrix[index][column] and column != index:
                neighbours.append(str(column))
        lines.append(
            "%d (%.1f, %.1f) degree=%d neighbours: %s"
            % (index, points[index][0], points[index][1], degrees[index], ", ".join(neighbours) or "none")
        )
    return "\n".join(lines)


def main():
    points = parse_points(sys.stdin.read())
    matrix, degrees = adjacency(points)
    print(format_report(points, matrix, degrees))
    print([matrix, degrees])


if __name__ == "__main__":
    main()

