def plot(canvas, row, col, ch):
    if 0 <= row < len(canvas) and 0 <= col < len(canvas[row]):
        canvas[row][col] = ch


def make_canvas(width, height):
    canvas = []
    for i in range(height):
        row = []
        for j in range(width):
            row.append(' ')
        canvas.append(row)
    return canvas


def validate_commands(commands):
    for k in range(len(commands)):
        command = commands[k]
        if len(command) != 5:
            raise ValueError("command %d must have 5 fields" % k)
        row, col, width, height, ch = command
        if width <= 0 or height <= 0:
            raise ValueError("command %d has non-positive extent" % k)
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError("command %d needs a single character" % k)
        if not isinstance(row, int) or not isinstance(col, int):
            raise ValueError("command %d needs integer coordinates" % k)


def draw_rectangle(canvas, row, col, width, height, ch):
    bottom = row + height - 1
    right = col + width - 1
    for j in range(col, right + 1):
        plot(canvas, row, j, ch)
        plot(canvas, bottom, j, ch)
    for i in range(row + 1, bottom):
        plot(canvas, i, col, ch)
        plot(canvas, i, right, ch)


def render(commands, dimensions):
    width, height = dimensions
    if width < 0 or height < 0:
        raise ValueError("dimensions must be non-negative")
    validate_commands(commands)
    canvas = make_canvas(width, height)
    for k in range(len(commands)):
        row, col, w, h, ch = commands[k]
        draw_rectangle(canvas, row, col, w, h, ch)
    lines = []
    for n in range(height):
        lines.append(''.join(canvas[n]))
    return lines


def describe_commands(commands):
    descriptions = []
    for k in range(len(commands)):
        row, col, w, h, ch = commands[k]
        descriptions.append("'%s' at (%d,%d) size %dx%d" % (ch, row, col, w, h))
    return descriptions


def main():
    dimensions = (24, 10)
    commands = [
        (1, 1, 12, 6, '#'),
        (4, 7, 14, 5, '*'),
        (0, 0, 24, 10, '.'),
    ]
    for text in describe_commands(commands):
        print(text)
    lines = render(commands, dimensions)
    for n in range(len(lines)):
        print("%2d |%s|" % (n, lines[n]))


if __name__ == '__main__':
    main()

