def score_pair(secret, guess):
    """Return the (bulls, cows) tuple for a single guess against a single secret."""
    n = len(secret)
    bulls = 0
    rest_secret = []
    rest_guess = []
    for i in range(n):
        if secret[i] == guess[i]:
            bulls += 1
        else:
            rest_secret.append(secret[i])
            rest_guess.append(guess[i])
    cows = 0
    for k in rest_guess:
        if k in rest_secret:
            rest_secret.remove(k)
            cows += 1
    return (bulls, cows)


def validate(secrets, guesses):
    """Check that the batch is well formed before any scoring happens."""
    if len(secrets) != len(guesses):
        raise ValueError("there must be exactly one guess list per secret")
    for i in range(len(secrets)):
        n = len(secrets[i])
        if n == 0:
            raise ValueError("secret for game %d is empty" % (i + 1))
        for j in range(len(guesses[i])):
            if len(guesses[i][j]) != n:
                raise ValueError(
                    "game %d guess %d has length %d, expected %d"
                    % (i + 1, j + 1, len(guesses[i][j]), n)
                )


def score(secrets, guesses):
    """Score every guess of every game, returning a list of lists of tuples."""
    validate(secrets, guesses)
    results = []
    for i in range(len(secrets)):
        game = []
        for j in range(len(guesses[i])):
            game.append(score_pair(secrets[i], guesses[i][j]))
        results.append(game)
    return results


def format_report(secrets, guesses, results):
    """Turn the scored batch into printable report lines."""
    lines = []
    for i in range(len(results)):
        lines.append("Game %d (secret %s)" % (i + 1, secrets[i]))
        for j in range(len(results[i])):
            bulls, cows = results[i][j]
            suffix = "  <- solved" if bulls == len(secrets[i]) else ""
            lines.append(
                "  guess %d %s: %d bulls, %d cows%s"
                % (j + 1, guesses[i][j], bulls, cows, suffix)
            )
    return lines


def main():
    secrets = ["1243", "ABBA", "9999"]
    guesses = [
        ["1234", "1243", "4321"],
        ["BABA", "ABBA", "AAAA"],
        ["1234", "9899", "9999"],
    ]
    results = score(secrets, guesses)
    for line in format_report(secrets, guesses, results):
        print(line)
    solved = 0
    for i in range(len(results)):
        for j in range(len(results[i])):
            if results[i][j][0] == len(secrets[i]):
                solved += 1
                break
    print("solved %d of %d games" % (solved, len(results)))


if __name__ == "__main__":
    main()

