def _check_size(name, value):
    if not isinstance(value, int) or isinstance(value, bool):
        raise TypeError(name + " must be an integer")
    if value < 1:
        raise ValueError(name + " must be at least 1")


def find_longest_match(data, pos, window, lookahead):
    """Return (offset, length) of the longest history match for data[pos:]."""
    end = min(pos + lookahead, len(data))
    start = max(0, pos - window)
    best_offset = 0
    best_length = 0
    for i in range(start, pos):
        length = 0
        for j in range(end - pos):
            if data[i + j] != data[pos + j]:
                break
            length = j + 1
        if length > best_length:
            best_offset = pos - i
            best_length = length
    return best_offset, best_length


def compress(data, window, lookahead):
    """Sliding window (LZ77) compression into (offset, length, char) tuples."""
    if not isinstance(data, str):
        raise TypeError("data must be a string")
    _check_size("window", window)
    _check_size("lookahead", lookahead)
    tokens = []
    pos = 0
    while pos < len(data):
        offset, length = find_longest_match(data, pos, window, lookahead)
        if pos + length < len(data):
            tokens.append((offset, length, data[pos + length]))
        else:
            tokens.append((offset, length, ""))
        pos += length + 1
    return tokens


def decompress(tokens):
    """Rebuild the original string from the tuples produced by compress."""
    out = []
    for offset, length, char in tokens:
        base = len(out) - offset
        for k in range(length):
            out.append(out[base + k])
        if char:
            out.append(char)
    return "".join(out)


def format_tokens(tokens):
    """Return one human readable report line per token."""
    lines = []
    for n, (offset, length, char) in enumerate(tokens):
        shown = repr(char) if char else "<eof>"
        lines.append("%3d: offset=%-3d length=%-3d next=%s" % (n, offset, length, shown))
    return lines


def main():
    cases = [("abracadabra", 5, 3), ("aaaaaaaaab", 4, 4), ("mississippi", 8, 5)]
    for i, (text, window, lookahead) in enumerate(cases, 1):
        tokens = compress(text, window, lookahead)
        print("case %d: %r window=%d lookahead=%d" % (i, text, window, lookahead))
        for line in format_tokens(tokens):
            print(line)
        print("tuples: %s" % (tokens,))
        restored = decompress(tokens)
        print("restored: %r (ok=%s)" % (restored, restored == text))
        print("")


if __name__ == "__main__":
    main()

