import random
import sys

OFFSETS = ((1, 0), (-1, 0), (0, 1), (0, -1))


def make_grid(width, height):
    """Build a (2*height+1) x (2*width+1) character grid filled with walls."""
    rows = []
    for column in range(2 * height + 1):
        rows.append(['#'] * (2 * width + 1))
    return rows


def cell_neighbors(x, y, width, height):
    """The orthogonal cell neighbours of (x, y) that lie inside the grid."""
    found = []
    for key in range(4):
        dx, dy = OFFSETS[key]
        nx, ny = x + dx, y + dy
        if 0 <= nx < width and 0 <= ny < height:
            found.append((nx, ny))
    return found


def carve(grid, x, y, width, height, rng):
    """Recursive backtracker: open (x, y), then recurse into shuffled neighbours."""
    grid[2 * y + 1][2 * x + 1] = ' '
    candidates = cell_neighbors(x, y, width, height)
    rng.shuffle(candidates)
    for number in range(len(candidates)):
        nx, ny = candidates[number]
        if grid[2 * ny + 1][2 * nx + 1] == '#':
            grid[y + ny + 1][x + nx + 1] = ' '
            carve(grid, nx, ny, width, height, rng)


def to_strings(grid):
    lines = []
    for column in range(len(grid)):
        lines.append(''.join(grid[column]))
    return lines


def generate(width, height):
    if width < 1 or height < 1:
        raise ValueError("maze dimensions must be at least 1x1")
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 4 * width * height + 100))
    rng = random.Random()
    grid = make_grid(width, height)
    carve(grid, rng.randrange(width), rng.randrange(height), width, height, rng)
    return to_strings(grid)


def count_passages(lines):
    total = 0
    for column in range(len(lines)):
        for index in range(len(lines[column])):
            if lines[column][index] == ' ':
                total += 1
    return total


def count_reachable(lines):
    """Flood fill from the first passage cell to measure connectivity."""
    start = None
    for column in range(len(lines)):
        for index in range(len(lines[column])):
            if lines[column][index] == ' ':
                start = (index, column)
                break
        if start is not None:
            break
    seen = {start}
    stack = [start]
    while stack:
        x, y = stack.pop()
        for key in range(4):
            dx, dy = OFFSETS[key]
            nx, ny = x + dx, y + dy
            if 0 <= ny < len(lines) and 0 <= nx < len(lines[ny]):
                if lines[ny][nx] == ' ' and (nx, ny) not in seen:
                    seen.add((nx, ny))
                    stack.append((nx, ny))
    return len(seen)


def main():
    for number in (3, 6, 10):
        maze = generate(number, number)
        for column in range(len(maze)):
            print(maze[column])
        print("%dx%d maze: %d passage cells, %d reachable from the first one"
              % (number, number, count_passages(maze), count_reachable(maze)))
        print()


if __name__ == '__main__':
    main()

