class TrieNode:
    __slots__ = ("children", "is_word")

    def __init__(self):
        self.children = {}
        self.is_word = False


def insert(root, word):
    """Add a single vocabulary word to the prefix tree."""
    node = root
    for i in range(len(word)):
        c = word[i]
        if c not in node.children:
            node.children[c] = TrieNode()
        node = node.children[c]
    node.is_word = True


def clean_vocabulary(vocabulary):
    """Reject non-string entries and drop empty ones, keeping the original order."""
    words = []
    for i in range(len(vocabulary)):
        word = vocabulary[i]
        if not isinstance(word, str):
            raise TypeError("vocabulary entry %d is not a string: %r" % (i, word))
        if word:
            words.append(word)
    return words


def build_trie(vocabulary):
    root = TrieNode()
    words = clean_vocabulary(vocabulary)
    for i in range(len(words)):
        insert(root, words[i])
    return root


def find_node(root, prefix):
    """Return the node reached by following prefix, or None if absent."""
    node = root
    for i in range(len(prefix)):
        c = prefix[i]
        if c not in node.children:
            return None
        node = node.children[c]
    return node


def collect_words(node, prefix):
    """Depth first search collecting every complete word below node."""
    found = []
    stack = [(node, prefix)]
    while stack:
        current, text = stack.pop()
        if current.is_word:
            found.append(text)
        for k in reversed(list(current.children)):
            stack.append((current.children[k], text + k))
    return found


def autocomplete(vocabulary, prefixes):
    root = build_trie(vocabulary)
    results = []
    for i in range(len(prefixes)):
        prefix = prefixes[i]
        if not isinstance(prefix, str):
            raise TypeError("prefix %d is not a string: %r" % (i, prefix))
        node = find_node(root, prefix)
        if node is None:
            results.append([])
        else:
            results.append(collect_words(node, prefix))
    return results


