ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"


def to_bit_string(text):
    """Return the concatenated eight bit patterns of every byte in text."""
    pieces = []
    for n in text.encode("utf-8"):
        bits = []
        for j in range(7, -1, -1):
            bits.append("1" if (n >> j) & 1 else "0")
        pieces.append("".join(bits))
    return "".join(pieces)


def pad_to_multiple(bits, size):
    """Append zero bits until the length of bits is a multiple of size."""
    missing = (-len(bits)) % size
    return bits + "0" * missing


def chunk_bits(bits, size):
    """Split a bit string into consecutive groups of the given size."""
    groups = []
    for i in range(0, len(bits), size):
        groups.append(bits[i:i + size])
    return groups


def bits_to_int(group):
    """Interpret a string of '0'/'1' characters as an unsigned integer."""
    value = 0
    for k in group:
        value = value * 2 + (1 if k == "1" else 0)
    return value


def encode(text):
    """Convert an ordinary string into its base sixty four representation."""
    if not isinstance(text, str):
        raise TypeError("encode expects a string, got %s" % type(text).__name__)
    groups = chunk_bits(pad_to_multiple(to_bit_string(text), 6), 6)
    out = []
    for i in range(len(groups)):
        out.append(ALPHABET[bits_to_int(groups[i])])
    while len(out) % 4:
        out.append("=")
    return "".join(out)


def wrap(encoded, width=24):
    """Break an encoded string into lines of at most width characters."""
    lines = []
    for n in range(0, len(encoded), width):
        lines.append(encoded[n:n + width])
    return lines


def main():
    samples = ["cat", "a", "ab", "Hello, World!", "caffè"]
    for i, sample in enumerate(samples, 1):
        print("%d. %-15r -> %s" % (i, sample, encode(sample)))

    message = "Base sixty four turns bytes into printable characters."
    print("\nWrapped encoding of a longer message:")
    for j, line in enumerate(wrap(encode(message)), 1):
        print("  line %d: %s" % (j, line))


if __name__ == "__main__":
    main()

