WORD_LENGTH = 5
FEEDBACK_CHARS = "GYX"


def _validate(guesses):
    for k in range(len(guesses)):
        guess, feedback = guesses[k]
        if len(guess) != WORD_LENGTH or len(feedback) != WORD_LENGTH:
            raise ValueError("guess %d must have %d letters" % (k + 1, WORD_LENGTH))
        for j in range(WORD_LENGTH):
            if not guess[j].isalpha():
                raise ValueError("guess %d contains a non-letter" % (k + 1))
            if feedback[j].upper() not in FEEDBACK_CHARS:
                raise ValueError("feedback %d contains %r" % (k + 1, feedback[j]))


def _letter_counts(word):
    counts = {}
    for i in range(len(word)):
        counts[word[i]] = counts.get(word[i], 0) + 1
    return counts


def _letter_bounds(guess, feedback):
    minimum = {}
    exact = {}
    for i in range(WORD_LENGTH):
        if feedback[i] in "GY":
            minimum[guess[i]] = minimum.get(guess[i], 0) + 1
    for i in range(WORD_LENGTH):
        if feedback[i] == "X":
            exact[guess[i]] = minimum.get(guess[i], 0)
    return minimum, exact


def _matches(word, guess, feedback):
    for i in range(WORD_LENGTH):
        if feedback[i] == "G" and word[i] != guess[i]:
            return False
        if feedback[i] == "Y" and word[i] == guess[i]:
            return False
    counts = _letter_counts(word)
    minimum, exact = _letter_bounds(guess, feedback)
    for letter, need in minimum.items():
        if counts.get(letter, 0) < need:
            return False
    for letter, cap in exact.items():
        if counts.get(letter, 0) != cap:
            return False
    return True


def filter(dictionary, guesses):
    _validate(guesses)
    survivors = []
    for i in range(len(dictionary)):
        word = dictionary[i].lower()
        if len(word) != WORD_LENGTH:
            continue
        keep = True
        for k in range(len(guesses)):
            guess, feedback = guesses[k]
            if not _matches(word, guess.lower(), feedback.upper()):
                keep = False
                break
        if keep:
            survivors.append(dictionary[i])
    return survivors


def format_report(words, per_line=6):
    lines = []
    for i in range(0, len(words), per_line):
        chunk = words[i:i + per_line]
        lines.append("  ".join(entry.lower() for entry in chunk))
    return "\n".join(lines)


def main():
    dictionary = ["crane", "crate", "slate", "plate", "trace", "price",
                  "brine", "irate", "cigar", "rebut", "sissy", "humph",
                  "adieu", "grate", "orate", "elate"]
    guesses = [("crane", "XYYXG"), ("irate", "YGYXG")]
    candidates = filter(dictionary, guesses)
    for k in range(len(guesses)):
        print("guess %d: %s -> %s" % (k + 1, guesses[k][0], guesses[k][1]))
    print("%d candidate(s) remain:" % len(candidates))
    print(format_report(candidates))


if __name__ == "__main__":
    main()

