def minimum_length(clues):
    """Smallest row length that can hold the given blocks with single gaps."""
    total = 0
    for n in clues:
        total += n + 1
    return total - 1 if clues else 0


def validate(clues, length):
    if not isinstance(length, int) or length < 0:
        raise ValueError("length must be a non-negative integer")
    for k in clues:
        if not isinstance(k, int) or k <= 0:
            raise ValueError("block sizes must be positive integers")
    needed = minimum_length(clues)
    if needed > length:
        raise ValueError("clues %r do not fit in a row of length %d" % (clues, length))


def _expand(clues, length):
    if not clues:
        return [[False] * length]
    head, rest = clues[0], clues[1:]
    gap = 1 if rest else 0
    last_start = length - head - gap - minimum_length(rest)
    layouts = []
    for i in range(last_start + 1):
        prefix = [False] * i + [True] * head
        if rest:
            prefix.append(False)
            for tail in _expand(rest, length - len(prefix)):
                layouts.append(prefix + tail)
        else:
            layouts.append(prefix + [False] * (length - len(prefix)))
    return layouts


def permutations(clues, length):
    """All valid boolean layouts of a nonogram row described by clues."""
    validate(clues, length)
    return _expand(list(clues), length)


def blocks_of(pattern):
    """Recover the clue list implied by a boolean layout."""
    runs = []
    run = 0
    for j in range(len(pattern)):
        if pattern[j]:
            run += 1
        elif run:
            runs.append(run)
            run = 0
    if run:
        runs.append(run)
    return runs


def render(pattern):
    cells = []
    for k in range(len(pattern)):
        cells.append('#' if pattern[k] else '.')
    return ''.join(cells)


def main():
    puzzles = [([2, 1], 5), ([1, 1], 4), ([3], 5), ([], 3)]
    for clues, length in puzzles:
        layouts = permutations(clues, length)
        print("clues %r in length %d -> %d layout(s)" % (clues, length, len(layouts)))
        for n in range(len(layouts)):
            print("  %2d %s  %r" % (n + 1, render(layouts[n]), blocks_of(layouts[n])))


if __name__ == "__main__":
