def shape(grid):
    """Return (depth, height, width) of a rectangular 3D grid, validating it."""
    if not grid or not grid[0] or not grid[0][0]:
        raise ValueError("grid must be non-empty in all three dimensions")
    depth = len(grid)
    height = len(grid[0])
    width = len(grid[0][0])
    for i in range(depth):
        if len(grid[i]) != height:
            raise ValueError("layer %d has an inconsistent height" % i)
        for j in range(height):
            if len(grid[i][j]) != width:
                raise ValueError("row %d of layer %d has an inconsistent width" % (j, i))
    return depth, height, width


def zeros(depth, height, width):
