def normalize(inputs):
    """Scale the input vector by its largest absolute component."""
    peak = 0.0
    for i in range(len(inputs)):
        if abs(inputs[i]) > peak:
            peak = abs(inputs[i])
    if peak == 0.0:
        return [0.0 for i in range(len(inputs))]
    scaled = []
    for i in range(len(inputs)):
        scaled.append(inputs[i] / peak)
    return scaled


def check_shapes(weights, biases, inputs):
    """Verify that every layer matrix agrees with its bias vector and neighbours."""
    if len(weights) != len(biases):
        raise ValueError("each layer needs exactly one bias vector")
    width = len(inputs)
    for n in range(len(weights)):
        layer = weights[n]
        if len(layer) != len(biases[n]):
            raise ValueError("layer %d bias length mismatch" % n)
        for i in range(len(layer)):
            if len(layer[i]) != width:
                raise ValueError("layer %d row %d expects %d inputs" % (n, i, width))
        width = len(layer)


def activate(value):
    return value if value > 0.0 else 0.0


def forward_layer(matrix, bias, signal):
    """Compute one layer: dot product per output node, bias, then threshold."""
    output = []
    for i in range(len(matrix)):
        total = bias[i]
        for j in range(len(signal)):
            total += matrix[i][j] * signal[j]
        output.append(activate(total))
    return output


def backward_layer(matrix, gradient):
    """Multiply the transpose of the layer matrix by the incoming gradient."""
    width = len(matrix[0])
    lower = []
    for j in range(width):
        total = 0.0
        for i in range(len(matrix)):
            total += matrix[i][j] * gradient[i]
        lower.append(total)
    return lower


def evaluate(weights, biases, inputs):
    check_shapes(weights, biases, inputs)
    signal = normalize(inputs)
    for n in range(len(weights)):
        signal = forward_layer(weights[n], biases[n], signal)
    gradient = [1.0 for i in range(len(signal))]
    for n in range(len(weights) - 1, -1, -1):
        gradient = backward_layer(weights[n], gradient)
    return signal, gradient


def format_vector(name, vector):
    parts = []
    for k in range(len(vector)):
        parts.append("%s[%d]=%.4f" % (name, k, vector[k]))
    return "  ".join(parts)


def main():
    weights = [
        [[0.5, -0.2, 0.8], [1.0, 0.3, -0.6]],
        [[0.7, -1.1], [0.4, 0.9], [-0.3, 0.2]],
    ]
    biases = [[0.1, -0.05], [0.0, 0.2, -0.1]]
    samples = [[3.0, 6.0, -2.0], [1.0, 0.0, 0.5], [-4.0, 4.0, 4.0]]
    for k in range(len(samples)):
        output, gradient = evaluate(weights, biases, samples[k])
        print("sample %d" % k)
        print(format_vector("out", output))
        print(format_vector("grad", gradient))


if __name__ == "__main__":
    main()

