MARKER = "*"

ALPHABET = "ACGT"


def reverse_fragment(fragment):
    """Return the characters of ``fragment`` in reverse order."""
    chars = []
    for i in range(len(fragment) - 1, -1, -1):
        chars.append(fragment[i])
    return "".join(chars)


def normalize_fragments(fragments):
    """Drop the trailing marker and reverse every fragment that carries one."""
    normalized = []
    for i in range(len(fragments)):
        fragment = fragments[i]
        if fragment.endswith(MARKER):
            normalized.append(reverse_fragment(fragment[:-1]))
        else:
            normalized.append(fragment)
    return normalized


def validate_inputs(genome, fragments):
    for j in range(len(genome)):
        if genome[j] not in ALPHABET:
            raise ValueError("illegal genome symbol %r at %d" % (genome[j], j))
    for k in range(len(fragments)):
        if not fragments[k]:
            raise ValueError("fragment %d is empty" % k)
        if len(fragments[k]) > len(genome):
            raise ValueError("fragment %d is longer than the genome" % k)


def match_score(genome, fragment, start):
    """Count how many characters of ``fragment`` agree with the genome."""
    score = 0
    for j in range(len(fragment)):
        if genome[start + j] == fragment[j]:
            score += 1
    return score


def best_position(genome, fragment):
    """Slide ``fragment`` over the genome and return the highest scoring start."""
    best_start = 0
    best = -1
    for k in range(len(genome) - len(fragment) + 1):
        score = match_score(genome, fragment, k)
        if score > best:
            best = score
            best_start = k
    return best_start


def build_profile(length, fragments, positions):
    profile = [0] * length
    for i in range(len(fragments)):
        start = positions[i]
        for j in range(len(fragments[i])):
            profile[start + j] += 1
    return profile


def align(genome, fragments):
    cleaned = normalize_fragments(fragments)
    validate_inputs(genome, cleaned)
    positions = []
    for i in range(len(cleaned)):
        positions.append(best_position(genome, cleaned[i]))
    profile = build_profile(len(genome), cleaned, positions)
    maximum = 0
    for n in range(len(profile)):
        if profile[n] > maximum:
            maximum = profile[n]
    return maximum


def report(genome, fragments):
    cleaned = normalize_fragments(fragments)
    validate_inputs(genome, cleaned)
    for i in range(len(cleaned)):
        start = best_position(genome, cleaned[i])
        score = match_score(genome, cleaned[i], start)
        print("%-12s -> pos %3d  score %d/%d" % (cleaned[i], start, score, len(cleaned[i])))
    print("maximum overlap: %d" % align(genome, fragments))


if __name__ == "__main__":
    reference = "ACGTTGCATGTCGCATGATGCATGAGAGCT"
    reads = ["GCATGA", "TGTCGC", "ATGCAT", "TCGACT*", "AGAGCT"]
    report(reference, reads)

