import random
import string

DIRECTIONS = [(0, 1), (1, 0), (1, 1), (-1, 1)]
MAX_ATTEMPTS = 200


def fits(grid, word, row, col, drow, dcol):
    size = len(grid)
    for k, ch in enumerate(word):
        r = row + drow * k
        c = col + dcol * k
        if r < 0 or r >= size or c < 0 or c >= size:
            return False
        if grid[r][c] != " " and grid[r][c] != ch:
            return False
    return True


def place(grid, word, row, col, drow, dcol):
    for k, ch in enumerate(word):
        grid[row + drow * k][col + dcol * k] = ch


def normalize(words):
    cleaned = []
    for n, word in enumerate(words):
        text = "".join(word.split()).upper()
        if not text.isalpha():
            raise ValueError("word %d is not alphabetic: %r" % (n, word))
        cleaned.append(text)
    return cleaned


def generate(words, size):
    grid = []
    for i in range(size):
        row = []
        for j in range(size):
            row.append(" ")
        grid.append(row)

    placed = []
    for word in normalize(words):
        if len(word) > size:
            continue
        for n in range(MAX_ATTEMPTS):
            drow, dcol = random.choice(DIRECTIONS)
            row = random.randrange(size)
            col = random.randrange(size)
            if fits(grid, word, row, col, drow, dcol):
                place(grid, word, row, col, drow, dcol)
                placed.append(word)
                break

    for i in range(size):
        for j in range(size):
            if grid[i][j] == " ":
                grid[i][j] = random.choice(string.ascii_uppercase)

    for i in range(size):
        grid[i] = "".join(grid[i])

    return grid, placed


def main():
    words = ["python", "loop", "random", "grid", "puzzle", "search", "letter"]
    grid, placed = generate(words, 12)
    for i, row in enumerate(grid):
        print("%2d  %s" % (i, " ".join(row)))
    print()
    print("Hidden words (%d of %d):" % (len(placed), len(words)))
    for n, word in enumerate(sorted(placed), start=1):
        print("%2d. %s" % (n, word))


if __name__ == "__main__":
    main()

