def validate_edges(edges):
    """Reject entries that are not two-endpoint pairs."""
    for i in range(len(edges)):
        if len(edges[i]) != 2:
            raise ValueError("edge %d is not a pair: %r" % (i, edges[i]))

def primary_vertices(edges):
    """Unique first-set vertices, sorted."""
    primary = []
    for i in range(len(edges)):
        if edges[i][0] not in primary:
            primary.append(edges[i][0])
    primary.sort()
    return primary

def secondary_vertices(edges):
    """Unique second-set vertices, sorted."""
    secondary = []
    for i in range(len(edges)):
        if edges[i][1] not in secondary:
            secondary.append(edges[i][1])
    secondary.sort()
    return secondary

def neighbor_lists(edges, primary):
    """For each primary vertex, the secondary vertices it is linked to."""
    neighbors = []
    for i in range(len(primary)):
        linked = []
        for j in range(len(edges)):
            if edges[j][0] == primary[i] and edges[j][1] not in linked:
                linked.append(edges[j][1])
        neighbors.append(linked)
    return neighbors

def project(edges):
    validate_edges(edges)
    primary = primary_vertices(edges)
    neighbors = neighbor_lists(edges, primary)
    matrix = []
    for i in range(len(primary)):
        row = []
        for j in range(len(primary)):
            row.append(0)
        matrix.append(row)
    for i in range(len(primary)):
        for j in range(len(primary)):
            if i != j:
                shared = 0
                for k in range(len(neighbors[i])):
                    for n in range(len(neighbors[j])):
                        if neighbors[i][k] == neighbors[j][n]:
                            shared += 1
                matrix[i][j] = shared
    return matrix

def main():
    edges = [("ann", "chess"), ("ann", "choir"), ("bob", "chess"),
             ("bob", "choir"), ("bob", "judo"), ("cid", "judo"),
             ("dee", "chess"), ("dee", "judo"), ("dee", "choir")]
    people = primary_vertices(edges)
    clubs = secondary_vertices(edges)
    matrix = project(edges)
    print("clubs: " + ", ".join(clubs))
    for i in range(len(people)):
        cells = []
        for j in range(len(matrix[i])):
            cells.append(str(matrix[i][j]))
        print(people[i].ljust(4) + " " + " ".join(cells))
    pairs = 0
    print("shared memberships:")
    for i in range(len(people)):
        for j in range(i + 1, len(people)):
