def validate_edges(edges):
    """Reject entries that are not two-endpoint pairs."""
    for index in range(len(edges)):
        if len(edges[index]) != 2:
            raise ValueError("edge %d is not a pair: %r" % (index, edges[index]))

def primary_vertices(edges):
    """Unique first-set vertices, sorted."""
    primary = []
    for index in range(len(edges)):
        if edges[index][0] not in primary:
            primary.append(edges[index][0])
    primary.sort()
    return primary

def secondary_vertices(edges):
    """Unique second-set vertices, sorted."""
    secondary = []
    for index in range(len(edges)):
        if edges[index][1] not in secondary:
            secondary.append(edges[index][1])
    secondary.sort()
    return secondary

def neighbor_lists(edges, primary):
    """For each primary vertex, the secondary vertices it is linked to."""
    neighbors = []
    for index in range(len(primary)):
        linked = []
        for column in range(len(edges)):
            if edges[column][0] == primary[index] and edges[column][1] not in linked:
                linked.append(edges[column][1])
        neighbors.append(linked)
    return neighbors

def project(edges):
    validate_edges(edges)
    primary = primary_vertices(edges)
    neighbors = neighbor_lists(edges, primary)
    matrix = []
    for index in range(len(primary)):
        row = []
        for column in range(len(primary)):
            row.append(0)
        matrix.append(row)
    for index in range(len(primary)):
        for column in range(len(primary)):
            if index != column:
                shared = 0
                for key in range(len(neighbors[index])):
                    for number in range(len(neighbors[column])):
                        if neighbors[index][key] == neighbors[column][number]:
                            shared += 1
                matrix[index][column] = shared
    return matrix

def main():
    edges = [("ann", "chess"), ("ann", "choir"), ("bob", "chess"),
             ("bob", "choir"), ("bob", "judo"), ("cid", "judo"),
