def reverse_string(text):
    """Return text with its characters in reverse order."""
    letters = []
    for i in range(len(text) - 1, -1, -1):
        letters.append(text[i])
    return "".join(letters)


def reverse_targets(targets):
    """Build the list of reversed target substrings."""
    reversed_list = []
    for j in range(len(targets)):
        reversed_list.append(reverse_string(targets[j]))
    return reversed_list


def substitute(sequence, targets, reversed_list):
    """Replace every occurrence of each target with its reversed form."""
    result = sequence
    for k in range(len(targets)):
        if targets[k] in result:
            result = result.replace(targets[k], reversed_list[k])
    return result


def code_sum(sequence):
    """Sum the numerical character codes of a sequence."""
    total = 0
    for n in sequence:
        total += ord(n)
    return total


def validate(sequences, targets):
    for i in sequences:
        if not isinstance(i, str):
            raise TypeError("every sequence must be a string, got %r" % (i,))
    for j in targets:
        if not isinstance(j, str) or j == "":
            raise ValueError("every target must be a non-empty string, got %r" % (j,))


def mutate(sequences, targets):
    validate(sequences, targets)
    reversed_list = reverse_targets(targets)
    modified = []
    for i in sequences:
        modified.append(substitute(i, targets, reversed_list))
    sums = []
    for j in modified:
        sums.append(code_sum(j))
    maximum = 0
    for k in sums:
        if abs(k) > maximum:
            maximum = abs(k)
    return modified, maximum


def format_report(original, modified, maximum):
    width = 0
    for i in original:
        if len(i) > width:
            width = len(i)
    lines = []
    for j in range(len(original)):
        lines.append("%-*s -> %-*s  (%d)" % (width, original[j], width,
                                             modified[j], code_sum(modified[j])))
    lines.append("maximum absolute character-code sum: %d" % maximum)
    return lines


def main():
    sequences = ["GATTACA", "ACGTACGT", "TTTGGGCCC", "cathouse"]
    targets = ["ACA", "ACGT", "GGG", "house"]
    modified, maximum = mutate(sequences, targets)
    for n in format_report(sequences, modified, maximum):
        print(n)


