def validate(samples, delays, decays):
    if len(delays) != len(decays):
        raise ValueError("each delay needs exactly one decay factor")
    for i in range(len(delays)):
        if delays[i] < 0 or int(delays[i]) != delays[i]:
            raise ValueError("delay %r must be a non-negative integer" % (delays[i],))
        if not 0.0 <= decays[i] <= 1.0:
            raise ValueError("decay %r must lie between 0 and 1" % (decays[i],))
    for j in range(len(samples)):
        if not isinstance(samples[j], (int, float)):
            raise TypeError("sample %d is not numeric" % j)


def blend(samples, delays, decays):
    max_delay = 0
    for i in range(len(delays)):
        if delays[i] > max_delay:
            max_delay = delays[i]

    total = len(samples) + max_delay
    output = []
    for j in range(total):
        output.append(0.0)

    for k in range(len(samples)):
        output[k] = float(samples[k])

    for i in range(len(samples)):
        for n in range(len(delays)):
            output[i + delays[n]] += samples[i] * decays[n]

    return output


def peak(signal):
    highest = 0.0
    for i in range(len(signal)):
        magnitude = signal[i] if signal[i] >= 0 else -signal[i]
        if magnitude > highest:
            highest = magnitude
    return highest


def normalize(signal, ceiling=1.0):
    highest = peak(signal)
    if highest == 0.0:
        return list(signal)
    factor = ceiling / highest
    scaled = []
    for i in range(len(signal)):
        scaled.append(signal[i] * factor)
    return scaled


def render(signal, width=40):
    lines = []
    for i in range(len(signal)):
        bars = int(round(abs(signal[i]) * width))
        marks = ""
        for j in range(bars):
            marks += "#" if j % 5 else "|"
        lines.append("%4d %+7.3f %s" % (i, signal[i], marks))
    return lines


def main():
    samples = [0.0, 0.8, 0.4, -0.6, -0.2, 0.1]
    delays = [2, 5]
    decays = [0.5, 0.25]

    validate(samples, delays, decays)
    wet = blend(samples, delays, decays)
    print("peak before normalizing: %.3f" % peak(wet))
    for line in render(normalize(wet)):
        print(line)

    for n in range(1, 4):
        echo = blend(samples, [n * 2], [1.0 / (n + 1)])
        print("delay %2d taps -> %d samples, peak %.3f" % (n * 2, len(echo), peak(echo)))


if __name__ == "__main__":
    main()

