OPERATORS = "+-*/"


def simple_calculator(num1, operator, num2):
    """Perform a basic arithmetic operation on two numbers."""
    if operator == '+':
        return num1 + num2
    if operator == '-':
        return num1 - num2
    if operator == '*':
        return num1 * num2
    if operator == '/':
        if num2 == 0:
            return 'Error'
        return num1 / num2
    raise ValueError("unsupported operator: %r" % (operator,))


def to_number(token):
    """Convert a numeric token into an int or a float."""
    if not token:
        raise ValueError("missing operand")
    body = token[1:] if token[0] in "+-" else token
    dots = 0
    for j in range(len(body)):
        if body[j] == '.':
            dots += 1
        elif not body[j].isdigit():
            raise ValueError("bad operand: %r" % (token,))
    if dots > 1 or not body:
        raise ValueError("bad operand: %r" % (token,))
    return float(token) if dots else int(token)


def parse_expression(text):
    """Split '10 / 0' into (10, '/', 0)."""
    s = text.replace(" ", "")
    for i in range(1, len(s)):
        if s[i] in OPERATORS:
            return to_number(s[:i]), s[i], to_number(s[i + 1:])
    raise ValueError("no operator found in %r" % (text,))


def evaluate_all(expressions):
    """Parse and evaluate each expression, returning (text, result) rows."""
    rows = []
    for k in range(len(expressions)):
        text = expressions[k]
        num1, operator, num2 = parse_expression(text)
        rows.append((text.strip(), simple_calculator(num1, operator, num2)))
    return rows


def format_table(rows):
    """Render rows as an aligned '#  expression  result' table."""
    cells = [["#", "expression", "result"]]
    for k in range(len(rows)):
        cells.append([str(k + 1), rows[k][0], str(rows[k][1])])
    widths = [0, 0, 0]
    for i in range(len(cells)):
        for j in range(3):
            if len(cells[i][j]) > widths[j]:
                widths[j] = len(cells[i][j])
    lines = []
    for i in range(len(cells)):
        parts = []
        for j in range(3):
            parts.append(cells[i][j].ljust(widths[j]))
        lines.append("  ".join(parts).rstrip())
    return "\n".join(lines)


def main():
    expressions = ["10 + 5", "10 - 5", "10 * 5", "10 / 5", "10 / 0", "-7.5 + 2"]
    rows = evaluate_all(expressions)
    print(format_table(rows))
    errors = 0
    for k in range(len(rows)):
        if rows[k][1] == 'Error':
            errors += 1
    print("%d expression(s) evaluated, %d error(s)" % (len(rows), errors))


if __name__ == "__main__":
    main()

