def list_intersection(list1, list2):
    """Return the common elements of two lists, without duplicates."""
    result = []
    for i in range(len(list1)):
        item = list1[i]
        if item in list2 and item not in result:
            result.append(item)
    return result


def intersect_many(lists):
    """Return the elements common to every list in *lists*."""
    if not lists:
        return []
    result = list(lists[0])
    for k in range(1, len(lists)):
        result = list_intersection(result, lists[k])
    return result


def count_containing(lists, value):
    """Return how many of the given lists contain *value*."""
    total = 0
    for k in range(len(lists)):
        if value in lists[k]:
            total += 1
    return total


def common_to_at_least(lists, threshold):
    """Return elements that occur in at least *threshold* of the lists."""
    found = []
    for i in range(len(lists)):
        for j in range(len(lists[i])):
            value = lists[i][j]
            if value not in found and count_containing(lists, value) >= threshold:
                found.append(value)
    return found


def pairwise_sizes(lists):
    """Build a square matrix of intersection sizes for every pair of lists."""
    matrix = []
    for i in range(len(lists)):
        row = []
        for j in range(len(lists)):
            row.append(len(list_intersection(lists[i], lists[j])))
        matrix.append(row)
    return matrix


def format_matrix(names, matrix):
    """Render an intersection-size matrix as aligned text lines."""
    width = max(len(name) for name in names)
    lines = [" " * width + "".join(name.rjust(width + 1) for name in names)]
    for i in range(len(matrix)):
        cells = ""
        for j in range(len(matrix[i])):
            cells += str(matrix[i][j]).rjust(width + 1)
        lines.append(names[i].ljust(width) + cells)
    return lines


def threshold_report(lists):
    """Describe, for each threshold, which values reach that many lists."""
    lines = []
    for k in range(2, len(lists) + 1):
