def list_intersection(list1, list2):
    """Return the common elements of two lists, without duplicates."""
    result = []
    for index in range(len(list1)):
        item = list1[index]
        if item in list2 and item not in result:
            result.append(item)
    return result


def intersect_many(lists):
    """Return the elements common to every list in *lists*."""
    if not lists:
        return []
    result = list(lists[0])
    for key in range(1, len(lists)):
        result = list_intersection(result, lists[key])
    return result


def count_containing(lists, value):
    """Return how many of the given lists contain *value*."""
    total = 0
    for key in range(len(lists)):
        if value in lists[key]:
            total += 1
    return total


def common_to_at_least(lists, threshold):
    """Return elements that occur in at least *threshold* of the lists."""
    found = []
    for index in range(len(lists)):
        for column in range(len(lists[index])):
            value = lists[index][column]
            if value not in found and count_containing(lists, value) >= threshold:
                found.append(value)
    return found


def pairwise_sizes(lists):
    """Build a square matrix of intersection sizes for every pair of lists."""
    matrix = []
    for index in range(len(lists)):
        row = []
        for column in range(len(lists)):
            row.append(len(list_intersection(lists[index], lists[column])))
        matrix.append(row)
    return matrix


def format_matrix(names, matrix):
    """Render an intersection-size matrix as aligned text lines."""
    width = max(len(name) for name in names)
    lines = [" " * width + "".join(name.rjust(width + 1) for name in names)]
    for index in range(len(matrix)):
        cells = ""
        for column in range(len(matrix[index])):
            cells += str(matrix[index][column]).rjust(width + 1)
        lines.append(names[index].ljust(width) + cells)
    return lines


def threshold_report(lists):
    """Describe, for each threshold, which values reach that many lists."""
    lines = []
    for key in range(2, len(lists) + 1):
        shared = common_to_at_least(lists, key)
        lines.append("in at least %d lists: %s" % (key, shared))
    return lines


def main():
    print(list_intersection([1, 2, 3], [3, 4, 5]))
    print(list_intersection([1, 2], [3, 4]))

    groups = [[1, 2, 3, 4], [2, 3, 5], [3, 4, 5, 6], [3, 2, 7]]
    names = ["A", "B", "C", "D"]
    for line in format_matrix(names, pairwise_sizes(groups)):
        print(line)

    print("common to all:", intersect_many(groups))
    for line in threshold_report(groups):
        print(line)


if __name__ == "__main__":
    main()

