CATEGORIES = (
    (18.5, "Underweight"),
    (25.0, "Normal weight"),
    (30.0, "Overweight"),
)


def calculate_bmi(weight_kg, height_m):
    """Return the Body Mass Index, rounded to two decimals."""
    if weight_kg <= 0 or height_m <= 0:
        raise ValueError("weight and height must be positive")
    return round(weight_kg / height_m ** 2, 2)


def classify_bmi(bmi):
    """Return the WHO category name for a BMI value."""
    for limit, name in CATEGORIES:
        if bmi < limit:
            return name
    return "Obese"


def bmi_series(weights, heights):
    """Compute the BMI of paired weight and height measurements."""
    if len(weights) != len(heights):
        raise ValueError("weights and heights must have the same length")
    series = []
    for i in range(len(weights)):
        series.append(calculate_bmi(weights[i], heights[i]))
    return series


def bmi_changes(series):
    """Return the change in BMI between each measurement and the previous one."""
    changes = []
    for i in range(1, len(series)):
        changes.append(round(series[i] - series[i - 1], 2))
    return changes


def column_widths(rows):
    widths = [0] * len(rows[0])
    for row in rows:
        for j in range(len(row)):
            widths[j] = max(widths[j], len(row[j]))
    return widths


def format_table(rows):
    """Render a list of equal-length string rows as an aligned text table."""
    widths = column_widths(rows)
    lines = []
    for row in rows:
        cells = []
        for j in range(len(row)):
            cells.append(row[j].ljust(widths[j]))
        lines.append("  ".join(cells).rstrip())
    return "\n".join(lines)


def series_report(labels, weights, heights):
    series = bmi_series(weights, heights)
    changes = bmi_changes(series)
    rows = [["date", "kg", "m", "bmi", "change", "category"]]
    for i in range(len(series)):
        row = [labels[i], "{:g}".format(weights[i]), "{:.2f}".format(heights[i])]
        row.append("{:.2f}".format(series[i]))
        if i == 0:
            row.append("-")
        else:
            row.append("{:+.2f}".format(changes[i - 1]))
        row.append(classify_bmi(series[i]))
        rows.append(row)
    return format_table(rows)


def main():
    print("70 kg at 1.75 m ->", calculate_bmi(70, 1.75))
    print("100 kg at 2.00 m ->", calculate_bmi(100, 2.0))
    print()
    dates = ["2025-01", "2025-04", "2025-07", "2025-10"]
    weights = [88.0, 84.5, 80.2, 77.0]
    heights = [1.82, 1.82, 1.82, 1.81]
    print(series_report(dates, weights, heights))


if __name__ == "__main__":
    main()

