def sum_digits(n):
    """Return the sum of the decimal digits of the non-negative integer n."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an int, got %r" % (n,))
    if n < 0:
        raise ValueError("n must be non-negative, got %d" % n)
    total = 0
    for i in str(n):
        total += int(i)
    return total


def digit_counts(n):
    """Return a list of length 10 whose entry d counts the digit d inside n."""
    counts = [0] * 10
    for i in str(n):
        counts[int(i)] += 1
    return counts


def histogram_lines(n):
    """Render the digit histogram of n as a list of 'digit: ***' strings."""
    counts = digit_counts(n)
    lines = []
    for j in range(10):
        if counts[j]:
            lines.append("  %d: %s" % (j, "*" * counts[j]))
    return lines


def digit_sums(numbers):
    """Map each number of the iterable to its digit sum."""
    sums = []
    for k in numbers:
        sums.append(sum_digits(k))
    return sums


def digital_root(n):
    """Repeatedly sum the digits of n until a single digit remains."""
    value = sum_digits(n)
    while value > 9:
        value = sum_digits(value)
    return value


def additive_persistence(n):
    """Number of digit-sum steps needed to reduce n to a single digit."""
    steps = 0
    value = n
    while value > 9:
        value = sum_digits(value)
        steps += 1
    return steps


def report(numbers):
    """Build a multi-line report about the digit structure of each number."""
    out = []
    for i in numbers:
        out.append(
            "%d -> digit sum %d, digital root %d, persistence %d"
            % (i, sum_digits(i), digital_root(i), additive_persistence(i))
        )
        out.extend(histogram_lines(i))
    return "\n".join(out)


def main():
    samples = [123, 9, 0, 98765, 4999]
    print(report(samples))
    print("digit sums:", digit_sums(samples))
    print("numbers under 100 whose digit sum is 9:")
    for k in range(100):
        if sum_digits(k) == 9:
            print("  ", k)


if __name__ == "__main__":
    main()

