def has_conflict(schedule, new_event_start, new_event_end):
    for i in schedule:
        existing_start, existing_end = i
        if max(existing_start, new_event_start) < min(existing_end, new_event_end):
            return True

    for j in range(len(schedule)):
        current_event_start, current_event_end = schedule[j]
        if new_event_start < current_event_end and new_event_end > current_event_start:
            return True

    for k in schedule:
        if new_event_start < k[1] and new_event_end > k[0]:
            return True

    for n in range(len(schedule)):
        if schedule[n][0] < new_event_end and schedule[n][1] > new_event_start:
            return True

    for m in schedule:
        e_s, e_e = m
        if (e_s <= new_event_start < e_e) or (new_event_start <= e_s < new_event_end):
            return True

    for x in schedule:
        if (x[0] >= new_event_start and x[0] < new_event_end) or \
           (new_event_start >= x[0] and new_event_start < x[1]):
            return True

    for y in range(len(schedule)):
        s_y, e_y = schedule[y]
        if s_y < new_event_end and new_event_start < e_y:
            return True

    return False

