def update_dict(dict1, dict2):
    """Return a new dict with dict1's entries overridden/extended by dict2's."""
    validate_inputs(dict1, dict2)
    merged_dict = {}
    for k in dict1:
        merged_dict[k] = dict1[k]
    for k in dict2:
        merged_dict[k] = dict2[k]
    return merged_dict


def validate_inputs(*dicts):
    """Raise TypeError if any argument is not a dictionary."""
    for i in range(len(dicts)):
        if not isinstance(dicts[i], dict):
            raise TypeError("argument %d is %s, expected dict"
                            % (i + 1, type(dicts[i]).__name__))


def merge_all(dicts):
    """Merge a sequence of dictionaries left to right."""
    validate_inputs(*dicts)
    merged_dict = {}
    for i in range(len(dicts)):
        merged_dict = update_dict(merged_dict, dicts[i])
    return merged_dict


def overlapping_keys(dict1, dict2):
    """Keys present in both dictionaries, in dict1's order."""
    shared = []
    for k in dict1:
        if k in dict2:
            shared.append(k)
    return shared


def format_dict(d):
    """Render a dict as a stable, readable string."""
    keys = list(d)
    parts = []
    for j in range(len(keys)):
        parts.append("%r: %r" % (keys[j], d[keys[j]]))
    return "{" + ", ".join(parts) + "}"


def report(dict1, dict2):
    """Describe a merge: inputs, overridden keys, added keys and the result."""
    merged_dict = update_dict(dict1, dict2)
    lines = ["%s + %s" % (format_dict(dict1), format_dict(dict2))]
    for k in overlapping_keys(dict1, dict2):
        lines.append("  %r updated: %r -> %r" % (k, dict1[k], dict2[k]))
    for k in dict2:
        if k not in dict1:
            lines.append("  %r added: %r" % (k, dict2[k]))
    lines.append("  = " + format_dict(merged_dict))
    return "\n".join(lines)


def main():
    cases = [
        ({'a': 1, 'b': 2}, {'b': 3, 'c': 4}),
        ({'x': 10}, {'y': 20}),
    ]
    for i in range(len(cases)):
        first, second = cases[i]
        print("case %d:" % (i + 1))
        print(report(first, second))
    chain = [{'a': 1}, {'b': 2}, {'a': 9, 'c': 3}]
    print("chained: " + format_dict(merge_all(chain)))


if __name__ == "__main__":
    main()

