    validate_2x2(matrix_b, "matrix_b")
    result = [[0, 0], [0, 0]]
    for i in range(2):
        for j in range(2):
            total = 0
            for k in range(2):
                total += matrix_a[i][k] * matrix_b[k][j]
            result[i][j] = total
    return result


def format_2x2(matrix):
    widths = [0, 0]
    for j in range(2):
        for i in range(2):
            widths[j] = max(widths[j], len(str(matrix[i][j])))
