def add_employee(db, employee_id, name, department):
    """Append a new employee record unless employee_id is already present."""
    for i in range(len(db)):
        if db[i]['id'] == employee_id:
            return False
    db.append({'id': employee_id, 'name': name, 'department': department})
    return True


def find_employee(db, employee_id):
    """Return the record with the given id, or None if there is no such record."""
    for i in range(len(db)):
        if db[i]['id'] == employee_id:
            return db[i]
    return None


def department_counts(db):
    """Map each department name to the number of employees working in it."""
    counts = {}
    for i in range(len(db)):
        dept = db[i]['department']
        counts[dept] = counts.get(dept, 0) + 1
    return counts


def format_table(db):
    """Render the database as an aligned text table."""
    headers = ['ID', 'NAME', 'DEPARTMENT']
    rows = [headers]
    for i in range(len(db)):
        record = db[i]
        rows.append([str(record['id']), record['name'], record['department']])

    widths = []
    for j in range(len(headers)):
        widest = 0
        for i in range(len(rows)):
            if len(rows[i][j]) > widest:
                widest = len(rows[i][j])
        widths.append(widest)

    lines = []
    for i in range(len(rows)):
        cells = []
        for j in range(len(headers)):
            cells.append(rows[i][j].ljust(widths[j]))
        lines.append('  '.join(cells).rstrip())
    return '\n'.join(lines)


def main():
    requests = [
        (1, 'Alice', 'HR'),
        (2, 'Bob', 'IT'),
        (3, 'Dana', 'IT'),
        (1, 'Charlie', 'Sales'),
        (4, 'Eve', 'HR'),
    ]

    db = []
    for i in range(len(requests)):
        employee_id, name, department = requests[i]
        if add_employee(db, employee_id, name, department):
            print('added %d: %s (%s)' % (employee_id, name, department))
        else:
            existing = find_employee(db, employee_id)
            print('rejected %d: id taken by %s' % (employee_id, existing['name']))

    print()
    print(format_table(db))
    print()

    counts = department_counts(db)
    names = sorted(counts)
    for i in range(len(names)):
        print('%s: %d employee(s)' % (names[i], counts[names[i]]))


