def calculate_triangle_perimeter(side1, side2, side3):
    """Return the perimeter of a triangle with the three given side lengths."""
    sides = (side1, side2, side3)
    validate_sides(sides)
    return side1 + side2 + side3


def validate_sides(sides):
    """Raise ValueError unless the three values can form a triangle."""
    if len(sides) != 3:
        raise ValueError("a triangle needs exactly three sides")
    for i in range(3):
        if not isinstance(sides[i], (int, float)) or isinstance(sides[i], bool):
            raise ValueError("side %d is not a number: %r" % (i + 1, sides[i]))
        if sides[i] <= 0:
            raise ValueError("side %d must be positive: %r" % (i + 1, sides[i]))
    for i in range(3):
        if sides[(i + 1) % 3] + sides[(i + 2) % 3] <= sides[i]:
            raise ValueError("sides %r violate the triangle inequality" % (sides,))


def parse_triangle(text):
    """Turn a line like '7.5, 6, 8.5' into a tuple of three numbers."""
    parts = text.replace(",", " ").split()
    numbers = []
    for i in range(len(parts)):
        try:
            value = float(parts[i])
        except ValueError:
            raise ValueError("field %d is not numeric: %r" % (i + 1, parts[i]))
        if value.is_integer():
            value = int(value)
        numbers.append(value)
    if len(numbers) != 3:
        raise ValueError("expected three side lengths, got %d" % len(numbers))
    return tuple(numbers)


def perimeter_report(lines):
    """Build report rows (sides text, perimeter or error message) for each line."""
    rows = []
    for i in range(len(lines)):
        line = lines[i].strip()
        if not line:
            continue
        try:
            sides = parse_triangle(line)
            rows.append((line, calculate_triangle_perimeter(*sides)))
        except ValueError as exc:
            rows.append((line, "error: %s" % exc))
    return rows


def format_report(rows):
    """Render the report rows as aligned 'sides -> result' lines."""
    width = 0
    for i in range(len(rows)):
        width = max(width, len(rows[i][0]))
    out = []
    for i in range(len(rows)):
        sides_text, result = rows[i]
        out.append("%-*s -> %s" % (width, sides_text, result))
    return "\n".join(out)


def main():
    data = [
        "3, 4, 5",
        "7.5, 6, 8.5",
        "10 10 10",
        "1, 2, 90",
        "4, 4",
    ]
    print(format_report(perimeter_report(data)))


if __name__ == "__main__":
    main()

