def format_report(groups):
    """Build numbered report lines for a sequence of lists-of-lists."""
    lines = []
    for index in range(len(groups)):
        group = groups[index]
        shared = common_to_all(group)
        rendered = []
        for column in range(len(group)):
            rendered.append(format_elements(list(group[column])))
        lines.append("%d. %s -> %s (%d shared)"
                     % (index + 1, " & ".join(rendered), format_elements(shared), len(shared)))
    return lines


def main():
    groups = [
        [[1, 2, 3, 4], [3, 4, 5, 6]],
        [[1, 2], [3, 4]],
        [["a", "b", "b", "c"], ["c", "b", "z"]],
        [[1, 2, 3, 4], [2, 3, 4, 5], [3, 4, 9]],
    ]
    lines = format_report(groups)
    for index in range(len(lines)):
        print(lines[index])

    pair = groups[0]
    print("pairwise check:", find_common_elements(pair[0], pair[1]))


if __name__ == "__main__":
    main()

