def parse_csv_string(csv_data: str) -> list[list[str]]:
    """Parse a multi-line CSV string into a list of rows of string fields."""
    rows = []
    lines = csv_data.split("\n")
    for i in range(len(lines)):
        line = lines[i].rstrip("\r")
        if line == "" and i == len(lines) - 1:
            continue
        parts = line.split(",")
        row = []
        for j in range(len(parts)):
            row.append(parts[j].strip())
        rows.append(row)
    return rows


def column_widths(rows: list[list[str]]) -> list[int]:
    """Width of the widest field in each column."""
    count = 0
    for i in range(len(rows)):
        if len(rows[i]) > count:
            count = len(rows[i])
    widths = [0] * count
    for i in range(len(rows)):
        for j in range(len(rows[i])):
            if len(rows[i][j]) > widths[j]:
                widths[j] = len(rows[i][j])
    return widths


def ragged_row_numbers(rows: list[list[str]]) -> list[int]:
    """1-based numbers of rows whose field count differs from the header's."""
    if not rows:
        return []
    expected = len(rows[0])
    bad = []
    for i in range(1, len(rows)):
        if len(rows[i]) != expected:
            bad.append(i + 1)
    return bad


def format_table(rows: list[list[str]]) -> str:
    """Render parsed CSV rows as a padded text table with a header rule."""
    widths = column_widths(rows)
    out = []
    for i in range(len(rows)):
        cells = []
        for j in range(len(widths)):
            value = rows[i][j] if j < len(rows[i]) else ""
            cells.append(value.ljust(widths[j]))
        out.append(" | ".join(cells).rstrip())
        if i == 0:
            rule = []
            for k in range(len(widths)):
                rule.append("-" * widths[k])
            out.append("-+-".join(rule))
    return "\n".join(out)


def main() -> None:
    samples = [
        "Name,Age\nAlice,30\nBob,24",
        "A,B\n1,2",
        "id,city,country\n1,Lisbon,PT\n2,Oslo\n3,Kyoto,JP,extra\n",
    ]
    for i in range(len(samples)):
        rows = parse_csv_string(samples[i])
        print("sample %d -> %r" % (i + 1, rows))
        print(format_table(rows))
        bad = ragged_row_numbers(rows)
        for j in range(len(bad)):
            print("  warning: row %d has an unexpected field count" % bad[j])
        print()


if __name__ == "__main__":
    main()

