import sys


def split_words(sentence: str) -> list:
    """Split a sentence into words separated by one or more spaces."""
    words = []
    current = ""
    for i in range(len(sentence)):
        c = sentence[i]
        if c == " ":
            if current:
                words.append(current)
                current = ""
        else:
            current += c
    if current:
        words.append(current)
    return words


def count_words(sentence: str) -> int:
    """Count the words of a sentence, where words are separated by spaces."""
    return len(split_words(sentence))


def count_letters(word: str) -> int:
    """Count the alphabetic characters of a single word."""
    total = 0
    for k in range(len(word)):
        if word[k].isalpha():
            total += 1
    return total


def longest_word(words: list) -> str:
    """Return the first word of maximal length, or '' for an empty list."""
    best = ""
    for j in range(len(words)):
        if len(words[j]) > len(best):
            best = words[j]
    return best


def total_letters(words: list) -> int:
    """Sum the alphabetic characters over all the given words."""
    total = 0
    for i in range(len(words)):
        total += count_letters(words[i])
    return total


def length_histogram(words: list) -> dict:
    """Map each word length to the number of words having that length."""
    counts = {}
    for j in range(len(words)):
        size = len(words[j])
        counts[size] = counts.get(size, 0) + 1
    return counts


def format_report(sentence: str) -> str:
    """Build a short multi-line summary of a sentence."""
    words = split_words(sentence)
    counts = length_histogram(words)
    sizes = sorted(counts)
    parts = []
    for k in range(len(sizes)):
        parts.append("%d:%d" % (sizes[k], counts[sizes[k]]))
    average = total_letters(words) / len(words) if words else 0.0
    return "\n".join(["sentence: %r" % sentence,
                      "  words: %d" % count_words(sentence),
                      "  longest word: %r" % longest_word(words),
                      "  average letters per word: %.2f" % average,
                      "  length distribution: %s" % ", ".join(parts)])


def main(argv: list) -> int:
    sentences = argv[1:] or ["This is a test sentence.", "OneWord"]
    for i in range(len(sentences)):
        print(format_report(sentences[i]))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

