import sys

VOWELS = "aeiou"


def count_vowels(word: str) -> int:
    total = 0
    for i in range(len(word)):
        if word[i].lower() in VOWELS:
            total += 1
    return total


def split_words(sentence: str) -> list:
    words = []
    current = []
    for i in range(len(sentence)):
        c = sentence[i]
        if c.isspace():
            if current:
                words.append("".join(current))
                current = []
        else:
            current.append(c)
    if current:
        words.append("".join(current))
    return words


def word_with_most_vowels(sentence: str) -> str:
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a string")
    words = split_words(sentence)
    if not words:
        return ""
    best = words[0]
    best_count = count_vowels(best)
    for i in range(1, len(words)):
        current_count = count_vowels(words[i])
        if current_count > best_count:
            best = words[i]
            best_count = current_count
    return best


def vowel_table(sentence: str) -> list:
    words = split_words(sentence)
    rows = []
    for i in range(len(words)):
        rows.append((words[i], count_vowels(words[i])))
    return rows


def format_report(sentence: str) -> str:
    rows = vowel_table(sentence)
    if not rows:
        return "(no words)"
    width = 0
    for i in range(len(rows)):
        if len(rows[i][0]) > width:
            width = len(rows[i][0])
    lines = []
    for i in range(len(rows)):
        word, count = rows[i]
        lines.append(word.ljust(width) + "  " + str(count))
    lines.append("winner: " + word_with_most_vowels(sentence))
    return "\n".join(lines)


def main() -> None:
    sentences = sys.stdin.read().splitlines()
    for i in range(len(sentences)):
        print("input: " + repr(sentences[i]))
        print(format_report(sentences[i]))
        print()


