import math


def calculate_distance_2d(x1, y1, x2, y2):
    dx = x2 - x1
    dy = y2 - y1
    return math.sqrt(dx * dx + dy * dy)


def path_length(points):
    total = 0.0
    for i in range(len(points) - 1):
        x1, y1 = points[i]
        x2, y2 = points[i + 1]
        total += calculate_distance_2d(x1, y1, x2, y2)
    return total


def distance_matrix(points):
    matrix = []
    for i in range(len(points)):
        row = []
        for j in range(len(points)):
            row.append(calculate_distance_2d(points[i][0], points[i][1],
                                             points[j][0], points[j][1]))
        matrix.append(row)
    return matrix


def closest_pair(points):
    best = None
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            d = calculate_distance_2d(points[i][0], points[i][1],
                                      points[j][0], points[j][1])
            if best is None or d < best[0]:
                best = (d, i, j)
    return best


def format_points(points):
    labels = []
    for i in range(len(points)):
        labels.append("(%g, %g)" % (points[i][0], points[i][1]))
    return " -> ".join(labels)


def format_matrix(matrix, width=8, digits=3):
    lines = []
    for row in matrix:
        cells = []
        for k in range(len(row)):
            cells.append("{0:>{1}.{2}f}".format(row[k], width, digits))
        lines.append(" ".join(cells))
    return "\n".join(lines)


def main():
    samples = [(0, 0, 3, 4), (1, 1, 1, 5), (-2, -3, 4.5, 1)]
    for i in range(len(samples)):
        x1, y1, x2, y2 = samples[i]
        print("d(({0}, {1}), ({2}, {3})) = {4}".format(
            x1, y1, x2, y2, calculate_distance_2d(x1, y1, x2, y2)))

