import math


def calculate_distance_2d(x1, y1, x2, y2):
    dx = x2 - x1
    dy = y2 - y1
    return math.sqrt(dx * dx + dy * dy)


def path_length(points):
    total = 0.0
    for index in range(len(points) - 1):
        x1, y1 = points[index]
        x2, y2 = points[index + 1]
        total += calculate_distance_2d(x1, y1, x2, y2)
    return total


def distance_matrix(points):
    matrix = []
    for index in range(len(points)):
        row = []
        for column in range(len(points)):
            row.append(calculate_distance_2d(points[index][0], points[index][1],
                                             points[column][0], points[column][1]))
        matrix.append(row)
    return matrix


def closest_pair(points):
    best = None
    for index in range(len(points)):
        for column in range(index + 1, len(points)):
            d = calculate_distance_2d(points[index][0], points[index][1],
                                      points[column][0], points[column][1])
            if best is None or d < best[0]:
                best = (d, index, column)
    return best


def format_points(points):
    labels = []
    for index in range(len(points)):
        labels.append("(%g, %g)" % (points[index][0], points[index][1]))
    return " -> ".join(labels)


def format_matrix(matrix, width=8, digits=3):
    lines = []
    for row in matrix:
        cells = []
        for key in range(len(row)):
            cells.append("{0:>{1}.{2}f}".format(row[key], width, digits))
        lines.append(" ".join(cells))
    return "\n".join(lines)


def main():
    samples = [(0, 0, 3, 4), (1, 1, 1, 5), (-2, -3, 4.5, 1)]
    for index in range(len(samples)):
        x1, y1, x2, y2 = samples[index]
        print("d(({0}, {1}), ({2}, {3})) = {4}".format(
            x1, y1, x2, y2, calculate_distance_2d(x1, y1, x2, y2)))

    route = [(0, 0), (3, 4), (3, 0), (-1, 0)]
    print("route:", format_points(route))
    print("path length: %.4f" % path_length(route))

    print("distance matrix:")
    print(format_matrix(distance_matrix(route)))

    dist, first, second = closest_pair(route)
    print("closest pair: %s and %s at distance %.4f"
          % (route[first], route[second], dist))


if __name__ == "__main__":
    main()

