def validate_matrix(matrix):
    """Check that matrix is a rectangular list of lists of ints."""
    if not isinstance(matrix, list):
        raise TypeError("matrix must be a list of lists")
    width = None
    for index in range(len(matrix)):
        row = matrix[index]
        if not isinstance(row, list):
            raise TypeError("row %d is not a list" % index)
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError("row %d has length %d, expected %d" % (index, len(row), width))
        for column in range(len(row)):
            if not isinstance(row[column], int) or isinstance(row[column], bool):
                raise TypeError("element (%d, %d) is not an int" % (index, column))
    return width if width is not None else 0


def count_negative_matrix(matrix):
    """Return the number of negative numbers in a 2D list."""
    validate_matrix(matrix)
    total = 0
    for index in range(len(matrix)):
        for column in range(len(matrix[index])):
            if matrix[index][column] < 0:
                total += 1
    return total


def negatives_per_row(matrix):
    """Return a list with the count of negatives for each row."""
    counts = []
    for index in range(len(matrix)):
        count = 0
        for column in range(len(matrix[index])):
            if matrix[index][column] < 0:
                count += 1
        counts.append(count)
    return counts


def negatives_per_column(matrix):
    """Return a list with the count of negatives for each column."""
    width = validate_matrix(matrix)
    counts = [0] * width
    for key in range(width):
        for index in range(len(matrix)):
            if matrix[index][key] < 0:
                counts[key] += 1
    return counts


def format_report(matrix):
    """Build a human readable summary of the negative numbers in matrix."""
    row_counts = negatives_per_row(matrix)
    col_counts = negatives_per_column(matrix)
    lines = ["total negatives: %d" % count_negative_matrix(matrix)]
    for index in range(len(row_counts)):
        cells = []
        for column in range(len(matrix[index])):
            cells.append("%4d" % matrix[index][column])
        lines.append("row %d: %s -> %d" % (index, " ".join(cells), row_counts[index]))
    for key in range(len(col_counts)):
        lines.append("col %d: %d" % (key, col_counts[key]))
    return "\n".join(lines)


def main():
