def has_duplicates(input_list):
    """Return True if input_list contains at least one repeated element."""
    seen = set()
    for i in range(len(input_list)):
        item = input_list[i]
        try:
            if item in seen:
                return True
            seen.add(item)
        except TypeError:
            for j in range(i + 1, len(input_list)):
                if input_list[j] == item:
                    return True
    return False


def find_duplicates(input_list):
    """Return the repeated values, each listed once, in order of first repeat."""
    repeats = []
    for i in range(len(input_list)):
        item = input_list[i]
        if item in repeats:
            continue
        for j in range(i + 1, len(input_list)):
            if input_list[j] == item:
                repeats.append(item)
                break
    return repeats


def duplicate_positions(input_list, value):
    """Return every index at which value occurs in input_list."""
    positions = []
    for k in range(len(input_list)):
        if input_list[k] == value:
            positions.append(k)
    return positions


def format_report(input_list):
    """Build a human readable summary of the duplicates in input_list."""
    lines = ["list: %r" % (input_list,)]
    if not has_duplicates(input_list):
        lines.append("  no duplicates")
        return lines
    for value in find_duplicates(input_list):
        spots = duplicate_positions(input_list, value)
        text = ", ".join(str(n) for n in spots)
        lines.append("  %r appears %d times at indices %s" % (value, len(spots), text))
    return lines


def main():
    datasets = [
        [1, 2, 3, 1],
        ['a', 'b', 'c'],
        [],
        ['x', 'y', 'x', 'y', 'z'],
        [[1, 2], [3], [1, 2]],
        [0, False, 1.0, 1],
    ]
    for n in range(len(datasets)):
        print("case %d" % n)
        for line in format_report(datasets[n]):
            print(line)


if __name__ == "__main__":
    main()

