        except TypeError:
            for column in range(index + 1, len(input_list)):
                if input_list[column] == item:
                    return True
    return False


def find_duplicates(input_list):
    """Return the repeated values, each listed once, in order of first repeat."""
    repeats = []
    for index in range(len(input_list)):
        item = input_list[index]
        if item in repeats:
            continue
        for column in range(index + 1, len(input_list)):
            if input_list[column] == item:
                repeats.append(item)
                break
    return repeats


def duplicate_positions(input_list, value):
    """Return every index at which value occurs in input_list."""
    positions = []
    for key in range(len(input_list)):
        if input_list[key] == value:
            positions.append(key)
    return positions


def format_report(input_list):
    """Build a human readable summary of the duplicates in input_list."""
    lines = ["list: %r" % (input_list,)]
    if not has_duplicates(input_list):
        lines.append("  no duplicates")
        return lines
    for value in find_duplicates(input_list):
        spots = duplicate_positions(input_list, value)
        text = ", ".join(str(number) for number in spots)
        lines.append("  %r appears %d times at indices %s" % (value, len(spots), text))
    return lines


def main():
