        [1, 2, 3, 1],
        ['a', 'b', 'c'],
        [],
        ['x', 'y', 'x', 'y', 'z'],
        [[1, 2], [3], [1, 2]],
        [0, False, 1.0, 1],
    ]
    for number in range(len(datasets)):
        print("case %d" % number)
        for line in format_report(datasets[number]):
            print(line)


if __name__ == "__main__":
    main()

