def validate_inputs(values, weights):
    if len(values) != len(weights):
        raise ValueError("values and weights must have the same length")
    if not values:
        raise ValueError("values must not be empty")
    for i in range(len(values)):
        if not isinstance(values[i], (int, float)) or isinstance(values[i], bool):
            raise TypeError("value at index %d is not numeric" % i)
        if not isinstance(weights[i], (int, float)) or isinstance(weights[i], bool):
            raise TypeError("weight at index %d is not numeric" % i)
        if weights[i] < 0:
            raise ValueError("weight at index %d is negative" % i)


def calculate_weighted_average(values, weights):
    validate_inputs(values, weights)
    total = 0.0
    weight_sum = 0.0
    for i in range(len(values)):
        total += values[i] * weights[i]
        weight_sum += weights[i]
    if weight_sum == 0:
        raise ValueError("sum of weights must be greater than zero")
    return total / weight_sum


def normalize_weights(weights):
    weight_sum = 0.0
    for i in range(len(weights)):
        weight_sum += weights[i]
    if weight_sum == 0:
        raise ValueError("sum of weights must be greater than zero")
    normalized = []
    for j in range(len(weights)):
        normalized.append(weights[j] / weight_sum)
    return normalized


def weighted_variance(values, weights):
    mean = calculate_weighted_average(values, weights)
    shares = normalize_weights(weights)
    variance = 0.0
    for k in range(len(values)):
        variance += shares[k] * (values[k] - mean) ** 2
    return variance


def format_report(label, values, weights):
    shares = normalize_weights(weights)
    lines = ["%s (%d entries)" % (label, len(values))]
    for i in range(len(values)):
        lines.append("  value=%8.3f  weight=%6.3f  share=%6.2f%%"
                     % (values[i], weights[i], shares[i] * 100.0))
    lines.append("  weighted average = %.4f" % calculate_weighted_average(values, weights))
    lines.append("  weighted variance = %.4f" % weighted_variance(values, weights))
    return "\n".join(lines)


def main():
    datasets = [
        ("Sample A", [10, 20, 30], [0.5, 0.3, 0.2]),
        ("Sample B", [5, 10], [1, 1]),
        ("Exam scores", [88, 92.5, 74, 100], [2, 3, 1, 4]),
    ]
    for i in range(len(datasets)):
        print(format_report(datasets[i][0], datasets[i][1], datasets[i][2]))
        print()

    means = []
    counts = []
    for j in range(len(datasets)):
        means.append(calculate_weighted_average(datasets[j][1], datasets[j][2]))
        counts.append(len(datasets[j][1]))
    print("Combined average of dataset means:")
    print("  %.4f" % calculate_weighted_average(means, counts))


if __name__ == "__main__":
    main()

