def letter_counts(s: str) -> list:
    """Count the alphabetic characters of s, case-insensitively."""
    counts = [0] * 26
    for i in range(len(s)):
        c = s[i].lower()
        if 'a' <= c <= 'z':
            counts[ord(c) - ord('a')] += 1
    return counts


def are_anagrams(s1: str, s2: str) -> bool:
    """True if s1 and s2 use the same letters, ignoring case and other characters."""
    first = letter_counts(s1)
    second = letter_counts(s2)
    for i in range(26):
        if first[i] != second[i]:
            return False
    return True


def signature(s: str) -> str:
    """Canonical sorted-letter form of s, e.g. 'Silent!' -> 'eilnst'."""
    counts = letter_counts(s)
    parts = []
    for i in range(26):
        parts.append(chr(ord('a') + i) * counts[i])
    return ''.join(parts)


def group_anagrams(words: list) -> list:
    """Partition words into lists whose members are anagrams of one another."""
    groups = []
    for i in range(len(words)):
        placed = False
        for j in range(len(groups)):
            if are_anagrams(words[i], groups[j][0]):
                groups[j].append(words[i])
                placed = True
                break
        if not placed:
            groups.append([words[i]])
    return groups


def format_report(groups: list) -> str:
    """Render the anagram groups as a numbered, human-readable report."""
    lines = []
    for i in range(len(groups)):
        members = groups[i]
        label = signature(members[0]) or '(no letters)'
        lines.append("%d. %s -> %s" % (i + 1, label, ', '.join(members)))
    return '\n'.join(lines)


def main() -> None:
    pairs = [
        ('listen', 'silent'),
        ('hello', 'world'),
        ('Dormitory', 'Dirty room!'),
        ('Conversation', 'Voices rant on'),
    ]
    for i in range(len(pairs)):
        s1, s2 = pairs[i]
        print("are_anagrams(%r, %r) == %s" % (s1, s2, are_anagrams(s1, s2)))

    words = ['listen', 'silent', 'enlist', 'google', 'gooogle', 'banana', 'inlets']
    print()
    print("Anagram groups:")
    print(format_report(group_anagrams(words)))


if __name__ == '__main__':
    main()

