def char_counts(s: str):
    """Return (chars, counts) in order of first appearance."""
    chars = []
    counts = []
    index_of = {}
    for i in range(len(s)):
        ch = s[i]
        if ch in index_of:
            counts[index_of[ch]] += 1
        else:
            index_of[ch] = len(chars)
            chars.append(ch)
            counts.append(1)
    return chars, counts


def most_frequent_char(s: str) -> str:
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    if not s:
        raise ValueError("s must not be empty")
    chars, counts = char_counts(s)
    best = 0
    for j in range(1, len(chars)):
        if counts[j] > counts[best]:
            best = j
    return chars[best]


def top_chars(s: str, limit: int):
    """Return the `limit` most frequent characters as (char, count) pairs."""
    chars, counts = char_counts(s)
    result = []
    for k in range(min(limit, len(chars))):
        best = 0
        for j in range(1, len(chars)):
            if counts[j] > counts[best]:
                best = j
        result.append((chars.pop(best), counts.pop(best)))
    return result


def format_report(s: str, limit: int = 3) -> str:
    pairs = top_chars(s, limit)
    width = 0
    for ch, count in pairs:
        if count > width:
            width = count
    lines = ["input: %r" % s, "winner: %r" % most_frequent_char(s)]
    for i in range(len(pairs)):
        ch, count = pairs[i]
        bar = "#" * count + " " * (width - count)
        lines.append("  %d. %r %s %d" % (i + 1, ch, bar, count))
    return "\n".join(lines)


def main():
    samples = ["abracadabra", "banana", "mississippi", "xyz", "  spaced  out"]
    for i in range(len(samples)):
        if i:
            print()
        print(format_report(samples[i]))


if __name__ == "__main__":
    main()

