    lines = ["input: %r" % s, "winner: %r" % most_frequent_char(s)]
    for index in range(len(pairs)):
        ch, count = pairs[index]
        bar = "#" * count + " " * (width - count)
        lines.append("  %d. %r %s %d" % (index + 1, ch, bar, count))
    return "\n".join(lines)


