def clock_angle(hour: int, minute: int) -> float:
    """Smaller angle in degrees between the hour and minute hands."""
    if not isinstance(hour, int) or not isinstance(minute, int):
        raise TypeError("hour and minute must be integers")
    if not 0 <= hour <= 23:
        raise ValueError("hour must be in 0..23")
    if not 0 <= minute <= 59:
        raise ValueError("minute must be in 0..59")
    hour_angle = (hour % 12) * 30.0 + minute * 0.5
    minute_angle = minute * 6.0
    diff = abs(hour_angle - minute_angle)
    return min(diff, 360.0 - diff)


def format_time(hour: int, minute: int) -> str:
    return "{:d}:{:02d}".format(hour % 12 or 12, minute)


def angle_report(times):
    """Numbered, aligned lines describing the angle at each given time."""
    width = 0
    for i in range(len(times)):
        width = max(width, len(format_time(*times[i])))
    lines = []
    for i in range(len(times)):
        hour, minute = times[i]
        lines.append("{:2d}. {:>{w}}  {:6.1f} deg".format(
            i + 1, format_time(hour, minute), clock_angle(hour, minute), w=width))
    return lines


def times_with_angle(target: float, tolerance: float = 0.5):
    """Every clock reading of a 12-hour dial whose hand angle matches target."""
    matches = []
    for j in range(12):
        for k in range(60):
            if abs(clock_angle(j, k) - target) <= tolerance:
                matches.append((j, k))
    return matches


def best_alignment_per_hour():
    """For each hour, the minute at which the hands come closest together."""
    result = []
    for j in range(12):
        best_minute, best_angle = 0, clock_angle(j, 0)
        for k in range(1, 60):
            angle = clock_angle(j, k)
            if angle < best_angle:
                best_minute, best_angle = k, angle
        result.append((j, best_minute, best_angle))
    return result


def main():
    samples = [(12, 0), (3, 0), (3, 30), (6, 0), (9, 45), (1, 10), (22, 55)]
    report = angle_report(samples)
    print("Angle between the hands:")
    for line in report:
        print(line)

    straight = times_with_angle(180.0, 0.4)
    print("\nTimes with the hands (nearly) opposite:")
    for i in range(0, len(straight), 6):
        chunk = straight[i:i + 6]
        print("  " + "  ".join(format_time(hour, minute) for hour, minute in chunk))

    print("\nClosest approach of the hands, hour by hour:")
    for hour, minute, angle in best_alignment_per_hour():
        print("  {:>5}  {:4.1f} deg".format(format_time(hour, minute), angle))


if __name__ == "__main__":
    main()

