def is_valid_ip_segment(s: str) -> bool:
    if not s or len(s) > 3:
        return False
    for i in range(len(s)):
        if s[i] not in '0123456789':
            return False
    if s[0] == '0' and len(s) > 1:
        return False
    return int(s) <= 255


def is_valid_ipv4(address: str) -> bool:
    parts = address.split('.')
    if len(parts) != 4:
        return False
    for i in range(4):
        if not is_valid_ip_segment(parts[i]):
            return False
    return True


def restore_ip_addresses(digits: str) -> list:
    """All valid IPv4 addresses obtainable by inserting dots into `digits`."""
    results = []
    total = len(digits)
    if total < 4 or total > 12:
        return results
    for i in range(1, 4):
        for j in range(i + 1, i + 4):
            for k in range(j + 1, j + 4):
                if k >= total:
                    break
                a = digits[:i]
                b = digits[i:j]
                c = digits[j:k]
                d = digits[k:]
                if (is_valid_ip_segment(a) and is_valid_ip_segment(b)
                        and is_valid_ip_segment(c) and is_valid_ip_segment(d)):
                    results.append('.'.join((a, b, c, d)))
    return results


def to_integer(address: str) -> int:
    """Pack a dotted-quad address into its 32-bit integer value."""
    if not is_valid_ipv4(address):
        raise ValueError('not a valid IPv4 address: %r' % address)
    parts = address.split('.')
    value = 0
    for i in range(4):
        value = (value << 8) | int(parts[i])
    return value


def format_report(segments, addresses, digit_strings) -> str:
    lines = ['Segment checks:']
    for i in range(len(segments)):
        lines.append('  %-5r -> %s' % (segments[i], is_valid_ip_segment(segments[i])))
    lines.append('Address checks:')
    for j in range(len(addresses)):
        a = addresses[j]
        if is_valid_ipv4(a):
            lines.append('  %-17s -> True  (%d)' % (a, to_integer(a)))
        else:
            lines.append('  %-17s -> False' % a)
    lines.append('Reconstructions:')
    for k in range(len(digit_strings)):
        candidates = restore_ip_addresses(digit_strings[k])
        lines.append('  %s:' % digit_strings[k])
        for i in range(len(candidates)):
            lines.append('    %d. %s' % (i + 1, candidates[i]))
    return '\n'.join(lines)


def main():
    segments = ['255', '01', '256', '0', '', '12a', '1000']
    addresses = ['192.168.0.1', '255.255.255.255', '1.2.3', '01.2.3.4']
    digit_strings = ['25525511135', '0000', '101023']
    print(format_report(segments, addresses, digit_strings))


if __name__ == '__main__':
    main()

