    return int(s) <= 255


def is_valid_ipv4(address: str) -> bool:
    parts = address.split('.')
    if len(parts) != 4:
        return False
    for index in range(4):
        if not is_valid_ip_segment(parts[index]):
            return False
    return True


def restore_ip_addresses(digits: str) -> list:
    """All valid IPv4 addresses obtainable by inserting dots into `digits`."""
    results = []
    total = len(digits)
    if total < 4 or total > 12:
        return results
    for index in range(1, 4):
        for column in range(index + 1, index + 4):
            for key in range(column + 1, column + 4):
                if key >= total:
                    break
                a = digits[:index]
                b = digits[index:column]
                c = digits[column:key]
                d = digits[key:]
                if (is_valid_ip_segment(a) and is_valid_ip_segment(b)
                        and is_valid_ip_segment(c) and is_valid_ip_segment(d)):
                    results.append('.'.join((a, b, c, d)))
    return results


def to_integer(address: str) -> int:
    """Pack a dotted-quad address into its 32-bit integer value."""
    if not is_valid_ipv4(address):
        raise ValueError('not a valid IPv4 address: %r' % address)
    parts = address.split('.')
    value = 0
    for index in range(4):
        value = (value << 8) | int(parts[index])
    return value


def format_report(segments, addresses, digit_strings) -> str:
    lines = ['Segment checks:']
    for index in range(len(segments)):
        lines.append('  %-5r -> %s' % (segments[index], is_valid_ip_segment(segments[index])))
    lines.append('Address checks:')
    for column in range(len(addresses)):
        a = addresses[column]
        if is_valid_ipv4(a):
            lines.append('  %-17s -> True  (%d)' % (a, to_integer(a)))
        else:
            lines.append('  %-17s -> False' % a)
    lines.append('Reconstructions:')
    for key in range(len(digit_strings)):
        candidates = restore_ip_addresses(digit_strings[key])
        lines.append('  %s:' % digit_strings[key])
        for index in range(len(candidates)):
            lines.append('    %d. %s' % (index + 1, candidates[index]))
    return '\n'.join(lines)


def main():
    segments = ['255', '01', '256', '0', '', '12a', '1000']
    addresses = ['192.168.0.1', '255.255.255.255', '1.2.3', '01.2.3.4']
    digit_strings = ['25525511135', '0000', '101023']
    print(format_report(segments, addresses, digit_strings))


if __name__ == '__main__':
    main()

