def jaccard_index(set1: set, set2: set) -> float:
    """Return |A intersect B| / |A union B| for two sets."""
    if not isinstance(set1, (set, frozenset)) or not isinstance(set2, (set, frozenset)):
        raise TypeError("jaccard_index requires two sets")
    if not set1 and not set2:
        return 1.0
    n = 0
    for k in set1:
        if k in set2:
            n += 1
    return n / (len(set1) + len(set2) - n)


def tokenize(text: str) -> set:
    """Split text into a set of lowercase alphanumeric words."""
    cleaned = []
    for k in text.lower():
        cleaned.append(k if (k.isalnum() or k == "'") else " ")
    return set("".join(cleaned).split())


def similarity_matrix(sets: list) -> list:
    """Build the square matrix of pairwise Jaccard indices."""
    n = len(sets)
    matrix = []
    for i in range(n):
        row = []
        for j in range(n):
            row.append(jaccard_index(sets[i], sets[j]))
        matrix.append(row)
    return matrix


def format_matrix(labels: list, matrix: list, width: int = 8) -> str:
    """Render a similarity matrix as an aligned text table."""
    header = " " * width
    for j in range(len(labels)):
        header += labels[j].rjust(width)
    lines = [header]
    for i in range(len(labels)):
        cells = []
        for j in range(len(labels)):
            cells.append("{:.2f}".format(matrix[i][j]).rjust(width))
        lines.append(labels[i].ljust(width) + "".join(cells))
    return "\n".join(lines)


def most_similar_pair(labels: list, matrix: list) -> tuple:
    """Return (label_a, label_b, score) for the closest distinct pair."""
    best = (None, None, -1.0)
    for i in range(len(labels)):
        for j in range(i + 1, len(labels)):
            if matrix[i][j] > best[2]:
                best = (labels[i], labels[j], matrix[i][j])
    return best


def main() -> None:
    documents = {
        "alpha": "The quick brown fox jumps over the lazy dog",
        "beta": "A quick brown dog jumps over a lazy fox",
        "gamma": "Rain in Spain falls mainly on the plain",
        "delta": "The lazy dog sleeps in the rain",
    }
    labels = sorted(documents)
    token_sets = []
    for i in range(len(labels)):
        token_sets.append(tokenize(documents[labels[i]]))
        print("{}: {} distinct words".format(labels[i], len(token_sets[i])))
    matrix = similarity_matrix(token_sets)
    print()
    print(format_matrix(labels, matrix))
    a, b, score = most_similar_pair(labels, matrix)
    print("\nClosest pair: {} / {} at {:.3f}".format(a, b, score))
    shared = sorted(token_sets[labels.index(a)] & token_sets[labels.index(b)])
    print("Shared words: " + ", ".join(shared))


if __name__ == "__main__":
    main()

