DIGITS = "0123456789ABCDEF"


def convert_base(decimal_num: int, base: int) -> str:
    """Return the representation of decimal_num in the given base (2..16)."""
    if not 2 <= base <= 16:
        raise ValueError("base must be between 2 and 16, got %r" % (base,))
    remaining = abs(decimal_num)
    digits = []
    while remaining:
        digits.append(DIGITS[remaining % base])
        remaining //= base
    if not digits:
        return "0"
    text = "-" if decimal_num < 0 else ""
    for i in range(len(digits) - 1, -1, -1):
        text += digits[i]
    return text


def value_of(text: str, base: int) -> int:
    """Read a string written in the given base and return its decimal value."""
    if not 2 <= base <= 16:
        raise ValueError("base must be between 2 and 16, got %r" % (base,))
    body = text.strip().upper()
    sign = 1
    if body.startswith("-"):
        sign = -1
        body = body[1:]
    if not body:
        raise ValueError("no digits to read")
    total = 0
    for i in range(len(body)):
        d = DIGITS.find(body[i])
        if d < 0 or d >= base:
            raise ValueError("%r is not a digit of base %d" % (body[i], base))
        total = total * base + d
    return sign * total


def parse_spec(spec: str):
    """Split a 'value:base' command line argument into its two parts."""
    parts = spec.split(":")
    if len(parts) != 2:
        raise ValueError("expected VALUE:BASE, got %r" % (spec,))
    return parts[0], int(parts[1])


def format_table(numbers, bases):
    header = "decimal".rjust(10)
    for j in range(len(bases)):
        header += ("base" + str(bases[j])).rjust(12)
    lines = [header]
    for i in range(len(numbers)):
        row = str(numbers[i]).rjust(10)
        for j in range(len(bases)):
            row += convert_base(numbers[i], bases[j]).rjust(12)
        lines.append(row)
    return lines


def main(argv):
    numbers = []
    for i in range(1, len(argv)):
        body, base = parse_spec(argv[i])
        numbers.append(value_of(body, base))
    if not numbers:
        numbers = [0, 10, 255, 4095, -123456]
    bases = [2, 8, 10, 16]
    lines = format_table(numbers, bases)
    for k in range(len(lines)):
        print(lines[k])
    return 0


if __name__ == "__main__":
    import sys

    raise SystemExit(main(sys.argv))

