def tree_depth(tree_repr: list[int | None]) -> int:
    """Number of levels needed to hold the array representation."""
    return len(tree_repr).bit_length()


def validate(tree_repr: list[int | None]) -> None:
    """Reject arrays where a node hangs under a missing parent."""
    for index in range(1, len(tree_repr)):
        if tree_repr[index] is not None and tree_repr[(index - 1) // 2] is None:
            raise ValueError(f"node at index {index} has no parent")


def tree_levels(tree_repr: list[int | None]) -> list[list[int | None]]:
    """Split the array into levels, padding each level to its full width."""
    levels = []
    for key in range(tree_depth(tree_repr)):
        start = 2 ** key - 1
        level = []
        for column in range(start, start + 2 ** key):
            level.append(tree_repr[column] if column < len(tree_repr) else None)
        levels.append(level)
    return levels


def is_symmetric_tree(tree_repr: list[int | None]) -> bool:
    """A tree stored in heap order is symmetric iff every level is a palindrome."""
    validate(tree_repr)
    for level in tree_levels(tree_repr):
        n = len(level)
        for column in range(n // 2):
            if level[column] != level[n - 1 - column]:
