import datetime


def format_date_ymd(date_obj: datetime.date) -> str:
    if not isinstance(date_obj, datetime.date):
        raise TypeError("format_date_ymd expects a datetime.date instance")
    parts = [date_obj.year, date_obj.month, date_obj.day]
    widths = [4, 2, 2]
    chunks = []
    for i in range(len(parts)):
        chunks.append(str(parts[i]).rjust(widths[i], "0"))
    return "-".join(chunks)


def parse_date_ymd(text: str) -> datetime.date:
    fields = text.strip().split("-")
    if len(fields) != 3:
        raise ValueError("expected a date of the form YYYY-MM-DD: %r" % text)
    numbers = []
    for j in range(3):
        field = fields[j]
        if not field.isdigit():
            raise ValueError("component %d is not numeric: %r" % (j + 1, field))
        numbers.append(int(field))
    return datetime.date(numbers[0], numbers[1], numbers[2])


def format_date_range(start: datetime.date, count: int) -> list:
    dates = []
    for k in range(count):
        dates.append(format_date_ymd(start + datetime.timedelta(days=k)))
    return dates


def month_starts(year: int) -> list:
    starts = []
    for i in range(1, 13):
        starts.append(datetime.date(year, i, 1))
    return starts


def build_report(year: int, span: int) -> str:
    lines = []
    firsts = month_starts(year)
    for i in range(len(firsts)):
        label = format_date_ymd(firsts[i])
        weekdays = []
        for j in range(span):
            day = firsts[i] + datetime.timedelta(days=j)
            weekdays.append(day.strftime("%a"))
        lines.append("%02d %s %s" % (i + 1, label, " ".join(weekdays)))
    return "\n".join(lines)


def main() -> None:
    samples = [datetime.date(2023, 10, 26), datetime.date(1999, 1, 5)]
    for i in range(len(samples)):
        print("sample %d: %s" % (i, format_date_ymd(samples[i])))

    texts = ["2023-10-26", "1999-01-05", "2000-02-29"]
    for k in range(len(texts)):
        restored = parse_date_ymd(texts[k])
        print("%s -> %s" % (texts[k], format_date_ymd(restored)))

    week = format_date_range(datetime.date(2023, 12, 29), 5)
    for i in range(len(week)):
        print("day %d of range: %s" % (i, week[i]))

    print(build_report(2024, 3))


if __name__ == "__main__":
    main()

