def validate_inventory(inventory: dict) -> None:
    """Raise if the inventory is not a mapping of item names to non-negative counts."""
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict")
    for k in inventory:
        if not isinstance(k, str):
            raise TypeError(f"item name must be a string, got {k!r}")
        stock = inventory[k]
        if isinstance(stock, bool) or not isinstance(stock, int):
            raise TypeError(f"stock for {k!r} must be an int, got {stock!r}")
        if stock < 0:
            raise ValueError(f"stock for {k!r} must not be negative")


def filter_by_stock(inventory: dict[str, int], threshold: int) -> dict[str, int]:
    """Return the items whose stock level is strictly above threshold."""
    validate_inventory(inventory)
    if isinstance(threshold, bool) or not isinstance(threshold, int):
        raise TypeError("threshold must be an int")
    kept = {}
    for k in inventory:
        if inventory[k] > threshold:
            kept[k] = inventory[k]
    return kept


def restock_plan(inventory: dict[str, int], target: int) -> dict[str, int]:
    """Return how many units each under-stocked item needs to reach target."""
    validate_inventory(inventory)
    plan = {}
    for k in inventory:
        if inventory[k] < target:
            plan[k] = target - inventory[k]
    return plan


def band_counts(inventory: dict[str, int], bands: list[int]) -> list[int]:
    """Count the items of each band; a band holds stock strictly above its limit."""
    validate_inventory(inventory)
    limits = sorted(bands)
    counts = [0] * len(limits)
    for k in inventory:
        for j in range(len(limits) - 1, -1, -1):
            if inventory[k] > limits[j]:
                counts[j] += 1
                break
    return counts


def format_report(title: str, inventory: dict[str, int]) -> str:
    """Render a numbered, column-aligned listing of an inventory."""
    names = sorted(inventory)
    lines = [title, "-" * len(title)]
    if not names:
        lines.append("(no items)")
        return "\n".join(lines)
    width = max(len(k) for k in names)
    for i, k in enumerate(names, start=1):
        lines.append(f"{i:>2}. {k:<{width}}  {inventory[k]:>4}")
    return "\n".join(lines)


def main() -> None:
    stock = {"apple": 10, "banana": 5, "orange": 12, "grape": 2, "pear": 8}
    bands = [0, 5, 10]

    print(format_report("Full inventory", stock))
    print()
    print(format_report("In stock above 7", filter_by_stock(stock, 7)))
    print()
    print(format_report("Units to order (target 10)", restock_plan(stock, 10)))
    print()

    counts = band_counts(stock, bands)
    limits = sorted(bands)
    print("Distribution")
    for i in range(len(counts)):
        print(f"  more than {limits[i]:>2} units: {counts[i]} item(s)")


if __name__ == "__main__":
    main()

