def format_month_calendar(year: int, month: int) -> str:
    weekend_set = {key.day for key in weekend_days_in_month(year, month)}
    first_weekday, days = calendar.monthrange(year, month)
    cells = [""] * first_weekday
    for index in range(1, days + 1):
        cells.append("[%2d]" % index if index in weekend_set else " %2d " % index)
    while len(cells) % 7:
        cells.append("")
    lines = ["%s %d" % (calendar.month_name[month], year)]
    for column in range(0, len(cells), 7):
        row = ""
        for key in range(7):
            row += "%-4s" % cells[column + key]
        lines.append(row.rstrip())
    return "\n".join(lines)


def main() -> None:
    samples = [datetime.date(2023, 10, 28), datetime.date(2023, 10, 26)]
    for index, day in enumerate(samples, start=1):
        print("Example %d: %s -> %s" % (index, day.isoformat(), is_weekend(day)))

    print(format_month_calendar(2023, 10))

    counts = count_weekends_per_month(2023)
    for index, count in enumerate(counts, start=1):
        print("%-10s %2d weekend days" % (calendar.month_abbr[index], count))
    print("Total weekend days in 2023: %d" % sum(counts))

    start = datetime.date(2023, 10, 1)
    end = datetime.date(2023, 10, 31)
    print("Working days in October 2023: %d" % working_days_between(start, end))

    for column in range(5):
        day = datetime.date(2023, 10, 26) + datetime.timedelta(days=column)
        print("%s -> next working day %s" % (day, next_working_day(day)))


if __name__ == "__main__":
    main()

