MONTH_LENGTHS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
MONTH_NAMES = ("January", "February", "March", "April", "May", "June",
               "July", "August", "September", "October", "November", "December")


def is_leap_year(year: int) -> bool:
    """Gregorian leap year rule."""
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def get_days_in_month(year: int, month: int) -> int:
    """Return the number of days in the given month of the given year."""
    if not isinstance(year, int) or not isinstance(month, int):
        raise TypeError("year and month must be integers")
    if month < 1 or month > 12:
        raise ValueError("month must be in 1..12")
    if month == 2 and is_leap_year(year):
        return 29
    return MONTH_LENGTHS[month - 1]


def days_in_year(year: int) -> int:
    """Total number of days in the year."""
    total = 0
    for i in range(1, 13):
        total += get_days_in_month(year, i)
    return total


def quarter_lengths(year: int) -> list:
    """Number of days in each of the four quarters of the year."""
    quarters = []
    for j in range(4):
        days = 0
        for k in range(3 * j + 1, 3 * j + 4):
            days += get_days_in_month(year, k)
        quarters.append(days)
    return quarters


def longest_months(year: int) -> list:
    """Names of the months that have the maximum number of days."""
    best = 0
    names = []
    for i in range(1, 13):
        length = get_days_in_month(year, i)
        if length > best:
            best = length
            names = [MONTH_NAMES[i - 1]]
        elif length == best:
            names.append(MONTH_NAMES[i - 1])
    return names


def format_year_table(year: int) -> str:
    """Render a one-line-per-month table of month lengths."""
    lines = ["%d (%d days)" % (year, days_in_year(year))]
    for i in range(1, 13):
        lines.append("  %-9s %2d" % (MONTH_NAMES[i - 1], get_days_in_month(year, i)))
    for j, days in enumerate(quarter_lengths(year), start=1):
        lines.append("  Q%d        %2d" % (j, days))
    lines.append("  longest:  " + ", ".join(longest_months(year)))
    return "\n".join(lines)


def main() -> None:
    for k in (1900, 2000, 2023, 2024):
        print(format_year_table(k))


if __name__ == "__main__":
    main()

