def normalize(rect):
    """Validate a rectangle tuple and return it with corners properly ordered."""
    values = list(rect)
    if len(values) != 4:
        raise ValueError("a rectangle needs exactly 4 coordinates, got %d" % len(values))
    for i in range(4):
        if not isinstance(values[i], (int, float)) or isinstance(values[i], bool):
            raise TypeError("coordinate %d is not a number: %r" % (i, values[i]))
    x1, y1, x2, y2 = values
    return (min(x1, x2), min(y1, y2), max(x1, x2), max(y1, y2))


def rectangle_overlap_area(rect_a, rect_b):
    """Area of the intersection of two axis-aligned rectangles (0 if disjoint)."""
    ax1, ay1, ax2, ay2 = normalize(rect_a)
    bx1, by1, bx2, by2 = normalize(rect_b)
    width = min(ax2, bx2) - max(ax1, bx1)
    height = min(ay2, by2) - max(ay1, by1)
    if width <= 0 or height <= 0:
        return 0
    return width * height


def pairwise_overlaps(rects):
    """Return the index pair and overlap area of every pair that overlaps."""
    found = []
    n = len(rects)
    for i in range(n):
        for j in range(i + 1, n):
            area = rectangle_overlap_area(rects[i], rects[j])
            if area:
                found.append((i, j, area))
    return found


def covered_area(rects):
    """Total area covered by the union of the rectangles, via coordinate slabs."""
    boxes = [normalize(rect) for rect in rects]
    xs = sorted({box[0] for box in boxes} | {box[2] for box in boxes})
    ys = sorted({box[1] for box in boxes} | {box[3] for box in boxes})
    total = 0
    for i in range(len(xs) - 1):
        for j in range(len(ys) - 1):
            cell = (xs[i], ys[j], xs[i + 1], ys[j + 1])
            for k in range(len(boxes)):
                if rectangle_overlap_area(cell, boxes[k]):
                    total += (xs[i + 1] - xs[i]) * (ys[j + 1] - ys[j])
                    break
    return total


def format_report(rects):
    """Build a human readable summary of the rectangles and their overlaps."""
    lines = []
    for i, rect in enumerate(rects):
        x1, y1, x2, y2 = normalize(rect)
        lines.append("R%d: (%g, %g) -> (%g, %g)" % (i, x1, y1, x2, y2))
    overlaps = pairwise_overlaps(rects)
    if not overlaps:
        lines.append("no overlapping pairs")
    for i, j, area in overlaps:
        lines.append("R%d and R%d overlap by %g" % (i, j, area))
    lines.append("union area: %g" % covered_area(rects))
    return "\n".join(lines)


def main():
    print(rectangle_overlap_area((0, 0, 2, 2), (1, 1, 3, 3)))
    print(rectangle_overlap_area((0, 0, 1, 1), (2, 2, 3, 3)))
    shapes = [(0, 0, 2, 2), (1, 1, 3, 3), (2, 0, 4, 1), (5, 5, 6, 7)]
    print(format_report(shapes))


if __name__ == "__main__":
    main()

