BEATS = {'rock': 'scissors', 'paper': 'rock', 'scissors': 'paper'}
OUTCOMES = ('Player 1 wins', 'Player 2 wins', "It's a tie!")


def normalize(choice):
    if not isinstance(choice, str):
        raise TypeError('choice must be a string')
    cleaned = choice.strip().lower()
    if cleaned not in BEATS:
        raise ValueError('invalid choice: %r' % (choice,))
    return cleaned


def rps_round(player1_choice, player2_choice):
    a = normalize(player1_choice)
    b = normalize(player2_choice)
    if a == b:
        return "It's a tie!"
    if BEATS[a] == b:
        return 'Player 1 wins'
    return 'Player 2 wins'


def play_match(rounds):
    tally = {outcome: 0 for outcome in OUTCOMES}
    results = []
    for i, (first, second) in enumerate(rounds, start=1):
        outcome = rps_round(first, second)
        tally[outcome] += 1
        results.append((i, normalize(first), normalize(second), outcome))
    return results, tally


def format_results(results):
    lines = []
    for i, first, second, outcome in results:
        lines.append('Round %d: %-8s vs %-8s -> %s' % (i, first, second, outcome))
    return lines


def match_winner(tally):
    if tally['Player 1 wins'] > tally['Player 2 wins']:
        return 'Player 1 wins the match'
    if tally['Player 2 wins'] > tally['Player 1 wins']:
        return 'Player 2 wins the match'
    return 'The match is a draw'


def outcome_table():
    names = sorted(BEATS)
    grid = []
    for i in range(len(names)):
        row = []
        for j in range(len(names)):
            row.append(rps_round(names[i], names[j]))
        grid.append(row)
    return names, grid


def format_table(names, grid):
    width = max(len(outcome) for outcome in OUTCOMES) + 2
    header = ' ' * 10
    for k in range(len(names)):
        header += '%-*s' % (width, names[k])
    lines = [header]
    for i in range(len(names)):
        cells = ''.join('%-*s' % (width, grid[i][j]) for j in range(len(names)))
        lines.append('%-10s' % names[i] + cells)
    return lines


def main():
    rounds = [('rock', 'scissors'), ('paper', 'rock'), ('scissors', 'scissors'),
              ('ROCK', 'paper'), ('paper', 'Scissors')]
    results, tally = play_match(rounds)
    for line in format_results(results):
        print(line)
    for outcome in OUTCOMES:
        print('%-14s: %d' % (outcome, tally[outcome]))
    print(match_winner(tally))

    print('Full outcome table (rows: player 1, columns: player 2):')
    names, grid = outcome_table()
    for line in format_table(names, grid):
        print(line)


if __name__ == '__main__':
    main()

