    print(circumference_table(radii))
    print()
    steps = growth_steps(radii)
    for index in range(len(steps)):
        print("step %d: %+.6f" % (index + 1, steps[index]))
    print("total: %.6f" % total_length(radii))
    print()
    rings = concentric_lengths(5, 4)
    for column in range(len(rings)):
        print("ring %d: %.6f" % (column + 1, rings[column]))


