def simulate_fair_coin_flip():
    return 'Heads' if random.getrandbits(1) else 'Tails'

def flip_many(count):
    flips = []
    for i in range(count):
        flips.append(simulate_fair_coin_flip())
    return flips

def tally(flips):
    counts = {'Heads': 0, 'Tails': 0}
    for i in range(len(flips)):
        counts[flips[i]] += 1
    return counts

def longest_run(flips):
    best = 0
    current = 0
    previous = None
    for i in range(len(flips)):
        if flips[i] == previous:
            current += 1
        else:
            current = 1
            previous = flips[i]
        if current > best:
            best = current
    return best

def run_trials(trials, flips_per_trial):
    heads_per_trial = []
    for j in range(trials):
        counts = tally(flip_many(flips_per_trial))
        heads_per_trial.append(counts['Heads'])
    return heads_per_trial

def histogram(heads_per_trial, flips_per_trial):
    buckets = [0] * (flips_per_trial + 1)
    for k in range(len(heads_per_trial)):
        buckets[heads_per_trial[k]] += 1
    return buckets

def format_histogram(buckets):
    lines = []
    for i in range(len(buckets)):
        if buckets[i]:
            lines.append('%2d heads | %s (%d)' % (i, '#' * buckets[i], buckets[i]))
    return '\n'.join(lines)

def main():
    sample = flip_many(20)
    print('Sample of 20 flips:')
    for i in range(0, len(sample), 10):
        print('  ' + ' '.join(sample[i:i + 10]))

    counts = tally(sample)
    print('Heads: %d  Tails: %d' % (counts['Heads'], counts['Tails']))
    print('Longest identical run: %d' % longest_run(sample))

    flips_per_trial = 10
    heads_per_trial = run_trials(500, flips_per_trial)
    print('\nDistribution of heads over 500 trials of 10 flips:')
    print(format_histogram(histogram(heads_per_trial, flips_per_trial)))

    total = 0
    for k in range(len(heads_per_trial)):
        total += heads_per_trial[k]
    print('\nMean heads per trial: %.3f (expected %.3f)'
          % (total / len(heads_per_trial), flips_per_trial / 2))

if __name__ == '__main__':
    main()

