def _validated_coords(values):
    coords = []
    for k in range(len(values)):
        value = values[k]
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("coordinate %d is not a number: %r" % (k, value))
        coords.append(float(value))
    return coords


def normalize(x1, y1, x2, y2):
    x1, y1, x2, y2 = _validated_coords((x1, y1, x2, y2))
    return (min(x1, x2), min(y1, y2), max(x1, x2), max(y1, y2))


def rectangle_overlap_area(r1x1, r1y1, r1x2, r1y2, r2x1, r2y1, r2x2, r2y2):
    ax1, ay1, ax2, ay2 = normalize(r1x1, r1y1, r1x2, r1y2)
    bx1, by1, bx2, by2 = normalize(r2x1, r2y1, r2x2, r2y2)
    width = min(ax2, bx2) - max(ax1, bx1)
    height = min(ay2, by2) - max(ay1, by1)
    if width <= 0.0 or height <= 0.0:
        return 0.0
    return width * height


def overlap_matrix(rects):
    matrix = []
    for i in range(len(rects)):
        row = []
        for j in range(len(rects)):
            if i == j:
                row.append(0.0)
            else:
                row.append(rectangle_overlap_area(*rects[i], *rects[j]))
        matrix.append(row)
    return matrix


def total_pairwise_overlap(rects):
    total = 0.0
    for i in range(len(rects)):
        for j in range(i + 1, len(rects)):
            total += rectangle_overlap_area(*rects[i], *rects[j])
    return total


def union_area(rects):
    boxes = [normalize(*rect) for rect in rects]
    xs = sorted({box[0] for box in boxes} | {box[2] for box in boxes})
    ys = sorted({box[1] for box in boxes} | {box[3] for box in boxes})
    area = 0.0
    for i in range(len(xs) - 1):
        for j in range(len(ys) - 1):
            cx = (xs[i] + xs[i + 1]) / 2.0
            cy = (ys[j] + ys[j + 1]) / 2.0
            for bx1, by1, bx2, by2 in boxes:
                if bx1 <= cx <= bx2 and by1 <= cy <= by2:
                    area += (xs[i + 1] - xs[i]) * (ys[j + 1] - ys[j])
                    break
    return area


def report(rects):
    matrix = overlap_matrix(rects)
    lines = []
    for i in range(len(rects)):
        lines.append("R%d = (%g, %g) .. (%g, %g)" % (i, *rects[i]))
    for i in range(len(matrix)):
        cells = []
        for j in range(len(matrix[i])):
            cells.append("%8.3f" % matrix[i][j])
        lines.append("R%d |%s" % (i, " ".join(cells)))
    lines.append("sum of pairwise overlaps: %.3f" % total_pairwise_overlap(rects))
    lines.append("area of union: %.3f" % union_area(rects))
    return "\n".join(lines)


def main():
    print(rectangle_overlap_area(0, 0, 2, 2, 1, 1, 3, 3))
    print(rectangle_overlap_area(0, 0, 1, 1, 2, 2, 3, 3))
    rects = [(0, 0, 2, 2), (1, 1, 3, 3), (2, 2, 3, 3), (-1, 0.5, 1.5, 1.0)]
    print(report(rects))


if __name__ == "__main__":
    main()

