DAY_NAMES = ('Monday', 'Tuesday', 'Wednesday', 'Thursday',
             'Friday', 'Saturday', 'Sunday')

MONTH_LENGTHS = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)

FIELD_WIDTHS = (4, 2, 2)


def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def days_in_month(year, month):
    if month == 2 and is_leap(year):
        return 29
    return MONTH_LENGTHS[month - 1]


def parse_date(date_str):
    parts = date_str.split('-')
    if len(parts) != 3:
        raise ValueError("date must look like 'YYYY-MM-DD': %r" % date_str)
    values = []
    for i in range(3):
        field = parts[i]
        if len(field) != FIELD_WIDTHS[i] or not field.isdigit():
            raise ValueError("bad field %r in %r" % (field, date_str))
        values.append(int(field))
    year, month, day = values
    if year < 1:
        raise ValueError("year must be positive: %d" % year)
    if not 1 <= month <= 12:
        raise ValueError("month out of range: %d" % month)
    if not 1 <= day <= days_in_month(year, month):
        raise ValueError("day out of range for %04d-%02d: %d" % (year, month, day))
    return year, month, day


def day_number(year, month, day):
    """Days elapsed since 0001-01-01, counting that date as 1."""
    past = year - 1
    total = past * 365 + past // 4 - past // 100 + past // 400 + day
    for k in range(1, month):
        total += days_in_month(year, k)
    return total


def get_weekday(date_str):
    year, month, day = parse_date(date_str)
    return DAY_NAMES[(day_number(year, month, day) - 1) % 7]


def format_month(year, month):
    cells = [''] * ((day_number(year, month, 1) - 1) % 7)
    for j in range(1, days_in_month(year, month) + 1):
        cells.append(str(j))
    while len(cells) % 7:
        cells.append('')
    header = []
    for k in range(7):
        header.append(DAY_NAMES[k][:2])
    lines = ['%04d-%02d' % (year, month), ' '.join(header)]
    for i in range(0, len(cells), 7):
        row = []
        for k in range(7):
            row.append(cells[i + k].rjust(2))
        lines.append(' '.join(row))
    return '\n'.join(lines)


def main():
    samples = ['2023-10-26', '2023-01-01', '2000-02-29', '1900-03-01']
    for i in range(len(samples)):
        print('%d. %s -> %s' % (i + 1, samples[i], get_weekday(samples[i])))
    print(format_month(2023, 10))


if __name__ == '__main__':
    main()

