import random

SIZE = 5


def validate_card(bingo_card):
    if len(bingo_card) != SIZE:
        raise ValueError("card must have %d rows" % SIZE)
    for i in range(SIZE):
        row = bingo_card[i]
        if len(row) != SIZE:
            raise ValueError("row %d must have %d cells" % (i, SIZE))
        for j in range(SIZE):
            if not isinstance(row[j], bool):
                raise ValueError("cell (%d, %d) is not a boolean" % (i, j))


def check_diagonal_bingo(bingo_card):
    validate_card(bingo_card)
    main = True
    anti = True
    for i in range(SIZE):
        if not bingo_card[i][i]:
            main = False
        if not bingo_card[i][SIZE - 1 - i]:
            anti = False
    return main or anti


def diagonal_progress(bingo_card):
    validate_card(bingo_card)
    main = 0
    anti = 0
    for i in range(SIZE):
        if bingo_card[i][i]:
            main += 1
        if bingo_card[i][SIZE - 1 - i]:
            anti += 1
    return main, anti


def random_card(marks, rng):
    positions = []
    for i in range(SIZE):
        for j in range(SIZE):
            positions.append((i, j))
    rng.shuffle(positions)
    card = [[False] * SIZE for _ in range(SIZE)]
    for k in range(marks):
        i, j = positions[k]
        card[i][j] = True
    return card


def format_card(bingo_card):
    lines = []
    for i in range(SIZE):
        cells = []
        for j in range(SIZE):
            cells.append("X" if bingo_card[i][j] else ".")
        lines.append(" ".join(cells))
    return "\n".join(lines)


def main():
    rng = random.Random(7)
    cards = [
        [[i == j for j in range(SIZE)] for i in range(SIZE)],
        [[False] * SIZE for _ in range(SIZE)],
    ]
    for marks in (8, 15, 22):
        cards.append(random_card(marks, rng))

    for number, card in enumerate(cards, start=1):
        main_count, anti_count = diagonal_progress(card)
        print("Card %d:" % number)
        print(format_card(card))
        print("main=%d/5 anti=%d/5 bingo=%s" % (main_count, anti_count,
                                                check_diagonal_bingo(card)))
        print()


if __name__ == "__main__":
    main()

