def validate_sudoku_block(block):
    """Return True if the 3x3 block holds no repeated digit from 1 to 9."""
    if len(block) != 3:
        return False
    seen = set()
    for i in range(3):
        row = block[i]
        if len(row) != 3:
            return False
        for j in range(3):
            value = row[j]
            if not isinstance(value, int) or isinstance(value, bool):
                return False
            if value < 0 or value > 9:
                return False
            if value == 0:
                continue
            if value in seen:
                return False
            seen.add(value)
    return True


def extract_block(grid, block_row, block_col):
    """Pull the 3x3 block whose top-left corner is at (3*block_row, 3*block_col)."""
    block = []
    for i in range(3):
        row = []
        for j in range(3):
            row.append(grid[3 * block_row + i][3 * block_col + j])
        block.append(row)
    return block


def validate_grid_blocks(grid):
    """Validate all nine blocks of a 9x9 grid, returning the list of bad block labels."""
    if len(grid) != 9:
        raise ValueError("grid must have 9 rows")
    for i in range(9):
        if len(grid[i]) != 9:
            raise ValueError("row %d must have 9 cells" % i)
    invalid = []
    for i in range(3):
        for j in range(3):
            if not validate_sudoku_block(extract_block(grid, i, j)):
                invalid.append((i, j))
    return invalid


def parse_grid(text):
    """Read a grid from nine lines of nine digits, dots meaning empty."""
    grid = []
    for line in text.strip().splitlines():
        line = line.strip()
        if not line:
            continue
        row = []
        for ch in line:
            row.append(0 if ch == "." else int(ch))
        grid.append(row)
    return grid


def main():
    puzzle = """
    534678912
    672195348
    198342567
    859761423
    426853791
    713924856
    961537284
    287419635
    345286179
    """
    broken = """
    534678912
    672195348
    198342567
    859761423
    426853791
    713924856
    961537284
    287419635
    345286177
    """
    for name, text in [("solved", puzzle), ("broken", broken)]:
        bad = validate_grid_blocks(parse_grid(text))
        print("%s grid: %s" % (name, "all blocks valid" if not bad else "invalid"))
        for block_row, block_col in bad:
            print("  bad block at row %d, col %d" % (block_row, block_col))


if __name__ == "__main__":
    main()

