CHANNEL_NAMES = ("red", "green", "blue")
HEX_DIGITS = "0123456789ABCDEF"


def validate_rgb(rgb_tuple):
    """Return the triple as a tuple of ints, raising on invalid input."""
    values = tuple(rgb_tuple)
    if len(values) != 3:
        raise ValueError("an RGB colour needs exactly 3 channels, got %d" % len(values))
    checked = []
    for i in range(3):
        value = values[i]
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("%s channel must be an int, got %r" % (CHANNEL_NAMES[i], value))
        if not 0 <= value <= 255:
            raise ValueError("%s channel %d is outside 0..255" % (CHANNEL_NAMES[i], value))
        checked.append(value)
    return tuple(checked)


def rgb_to_hex(rgb_tuple):
    """Convert (r, g, b) into a '#RRGGBB' string."""
    channels = validate_rgb(rgb_tuple)
    text = "#"
    for i in range(3):
        value = channels[i]
        text += HEX_DIGITS[value // 16] + HEX_DIGITS[value % 16]
    return text


def hex_to_rgb(hex_string):
    """Convert '#RRGGBB' (or 'RRGGBB') back into an (r, g, b) tuple."""
    digits = hex_string[1:] if hex_string.startswith("#") else hex_string
    if len(digits) != 6:
        raise ValueError("expected 6 hex digits, got %r" % hex_string)
    digits = digits.upper()
    channels = []
    for i in range(3):
        value = 0
        for j in range(2):
            position = HEX_DIGITS.find(digits[2 * i + j])
            if position < 0:
                raise ValueError("%r is not a hex digit" % digits[2 * i + j])
            value = value * 16 + position
        channels.append(value)
    return tuple(channels)


def gradient(start, end, steps):
    """Build a list of `steps` colours interpolating from start to end."""
    first = validate_rgb(start)
    last = validate_rgb(end)
    if steps < 2:
        raise ValueError("a gradient needs at least 2 steps")
    colours = []
    for i in range(steps):
        blended = []
        for j in range(3):
            span = last[j] - first[j]
            blended.append(first[j] + round(span * i / (steps - 1)))
        colours.append(tuple(blended))
    return colours


def format_palette(colours):
    """Render colours as numbered 'index: #RRGGBB (r, g, b)' lines."""
    lines = []
    for i in range(len(colours)):
        code = rgb_to_hex(colours[i])
        lines.append("%2d: %s %s" % (i + 1, code, hex_to_rgb(code)))
    return "\n".join(lines)


def main():
    samples = [(255, 0, 0), (0, 128, 255), (0, 0, 0), (255, 255, 255)]
    for i in range(len(samples)):
        print("%-16s -> %s" % (str(samples[i]), rgb_to_hex(samples[i])))
    print()
    print(format_palette(gradient((255, 0, 0), (0, 128, 255), 6)))


if __name__ == "__main__":
    main()

